window.STAT_RESOURCES = {"meta": {"tb_total": 13, "lit_total": 400, "oa_total": 113, "generated": "2026-09-14"}, "textbooks": {"probability_and_statistics": [{"title": "MIT 1805 Lecture Notes Full", "file": "MIT_1805_Lecture_Notes_Full.pdf", "source": "开放授权教材/讲义", "size": "0.1MB"}, {"title": "NIST EDA ExploratoryDataAnalysis", "file": "NIST_EDA_ExploratoryDataAnalysis.pdf", "source": "开放授权教材/讲义", "size": "3.6MB"}, {"title": "Online Statistics Education DavidLane", "file": "Online_Statistics_Education_DavidLane.pdf", "source": "开放授权教材/讲义", "size": "34.1MB"}, {"title": "OpenIntro Statistics 4th", "file": "OpenIntro_Statistics_4th.pdf", "source": "开放授权教材/讲义", "size": "20.7MB"}, {"title": "NIST E-Handbook Statistical Methods full", "file": "NIST_E-Handbook_Statistical_Methods_full.pdf", "source": "开放授权教材", "size": "12.8MB", "root": true}, {"title": "NIST EDA exploratory data analysis", "file": "NIST_EDA_exploratory_data_analysis.pdf", "source": "开放授权教材", "size": "3.6MB", "root": true}, {"title": "OpenIntro Statistics 4th edition", "file": "OpenIntro_Statistics_4th_edition.pdf", "source": "开放授权教材", "size": "20.7MB", "root": true}], "regression_analysis": [{"title": "An Introduction to Statistical Learning ISLR", "file": "An_Introduction_to_Statistical_Learning_ISLR.pdf", "source": "开放授权教材/讲义", "size": "15.9MB"}, {"title": "NIST Process Characterization", "file": "NIST_Process_Characterization.pdf", "source": "开放授权教材/讲义", "size": "1.7MB"}], "design_of_experiments": [{"title": "NIST Design of Experiments", "file": "NIST_Design_of_Experiments.pdf", "source": "开放授权教材/讲义", "size": "2.8MB"}, {"title": "NIST Process Improvement", "file": "NIST_Process_Improvement.pdf", "source": "开放授权教材/讲义", "size": "0.9MB"}, {"title": "NIST Product Improvement", "file": "NIST_Product_Improvement.pdf", "source": "开放授权教材/讲义", "size": "0.4MB"}], "multivariate_statistics": [], "time_series": [{"title": "State Space Models Notes", "file": "State_Space_Models_Notes.pdf", "source": "开放授权教材/讲义", "size": "0.4MB"}], "survey_sampling": []}, "literature": {"probability_and_statistics": {"cn": "概率论与数理统计", "items": [{"title": "Fitting Linear Mixed-Effects Models Using lme4", "doi": "https://doi.org/10.18637/jss.v067.i01", "year": 2015, "authors": ["Douglas M. Bates", "Martin Mächler", "Benjamin M. Bolker", "Steve Walker"], "source": "Journal of Statistical Software", "cited": 88651, "abstract": "Maximum likelihood or restricted maximum likelihood (REML) estimates of the parameters in linear mixed-effects models can be determined using the lmer function in the lme4 package for R. As for most model-fitting functions in R, the model is described in an lmer call by a formula, in this case including both fixed- and random-effects terms. The formula and data together determine a numerical representation of the model from which the profiled deviance or the profiled REML criterion can be evaluated as a function of some of the model parameters. The appropriate criterion is optimized, using one of the constrained optimization functions in R, to provide the parameter estimates. We describe the structure of the model, the steps in evaluating the profiled deviance or REML criterion, and the st", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v067i01/v67i01.pdf", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "A new look at the statistical model identification", "doi": "https://doi.org/10.1109/tac.1974.1100705", "year": 1974, "authors": ["Hirotugu Akaike"], "source": "IEEE Transactions on Automatic Control", "cited": 51476, "abstract": "The history of the development of statistical hypothesis testing in time series analysis is reviewed briefly and it is pointed out that the hypothesis testing procedure is not adequately defined as the procedure for statistical model identification. The classical maximum likelihood estimation procedure is reviewed and a new estimate minimum information theoretical criterion (AIC) estimate (MAICE) which is designed for the purpose of statistical identification is introduced. When there are several competing models the MAICE is defined by the model and the maximum likelihood estimates of the parameters which give the minimum of AIC defined by AIC = (-2)log-(maximum likelihood) + 2(number of independently adjusted parameters within the model). MAICE provides a versatile procedure for statisti", "oa": true, "pdf_url": "https://doi.org/10.1109/tac.1974.1100705", "local_pdf": "", "api": ""}, {"title": "The central role of the propensity score in observational studies for causal effects", "doi": "https://doi.org/10.1093/biomet/70.1.41", "year": 1983, "authors": ["Paul R. Rosenbaum", "Donald B. Rubin"], "source": "Biometrika", "cited": 31472, "abstract": "The propensity score is the conditional probability of assignment to a particular treatment given a vector of observed covariates. Both large and small sample theory show that adjustment for the scalar propensity score is sufficient to remove bias due to all observed covariates. Applications include: (i) matched sampling on the univariate propensity score, which is a generalization of discriminant matching, (ii) multivariate adjustment by subclassification on the propensity score where the same subclasses are used to estimate treatment effects for all outcome variables and in all subpopulations, and (iii) visual representation of multivariate covariance adjustment by a two- dimensional plot.", "oa": true, "pdf_url": "https://academic.oup.com/biomet/article-pdf/70/1/41/662954/70-1-41.pdf", "local_pdf": "", "api": ""}, {"title": "Convex Optimization", "doi": "https://doi.org/10.1017/cbo9780511804441", "year": 2004, "authors": ["Stephen Boyd", "Lieven Vandenberghe"], "source": "Cambridge University Press eBooks", "cited": 31185, "abstract": "Convex optimization problems arise frequently in many different fields. This book provides a comprehensive introduction to the subject, and shows in detail how such problems can be solved numerically with great efficiency. The book begins with the basic elements of convex sets and functions, and then describes various classes of convex optimization problems. Duality and approximation techniques are then covered, as are statistical estimation techniques. Various geometrical problems are then presented, and there is detailed discussion of unconstrained and constrained minimization problems, and interior-point methods. The focus of the book is on recognizing convex optimization problems and then finding the most appropriate technique for solving them. It contains many worked examples and home", "oa": true, "pdf_url": "https://doi.org/10.1017/cbo9780511804441", "local_pdf": "", "api": ""}, {"title": "MrBayes 3.2: Efficient Bayesian Phylogenetic Inference and Model Choice Across a Large Model Space", "doi": "https://doi.org/10.1093/sysbio/sys029", "year": 2012, "authors": ["Fredrik Ronquist", "Maxim Teslenko", "Paul van der Mark", "Daniel L. Ayres", "Aaron E. Darling", "Sebastian Höhna"], "source": "Systematic Biology", "cited": 28551, "abstract": "Since its introduction in 2001, MrBayes has grown in popularity as a software package for Bayesian phylogenetic inference using Markov chain Monte Carlo (MCMC) methods. With this note, we announce the release of version 3.2, a major upgrade to the latest official release presented in 2003. The new version provides convergence diagnostics and allows multiple analyses to be run in parallel with convergence progress monitored on the fly. The introduction of new proposals and automatic optimization of tuning parameters has improved convergence for many problems. The new version also sports significantly faster likelihood calculations through streaming single-instruction-multiple-data extensions (SSE) and support of the BEAGLE library, allowing likelihood calculations to be delegated to graphic", "oa": true, "pdf_url": "https://academic.oup.com/sysbio/article-pdf/61/3/539/24563565/sys029.pdf", "local_pdf": "", "api": ""}, {"title": "MRBAYES: Bayesian inference of phylogenetic trees", "doi": "https://doi.org/10.1093/bioinformatics/17.8.754", "year": 2001, "authors": ["John P. Huelsenbeck", "Fredrik Ronquist"], "source": "Bioinformatics", "cited": 22301, "abstract": "SUMMARY: The program MRBAYES performs Bayesian inference of phylogeny using a variant of Markov chain Monte Carlo. AVAILABILITY: MRBAYES, including the source code, documentation, sample data files, and an executable, is available at http://brahms.biology.rochester.edu/software.html.", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/17/8/754/48837190/bioinformatics_17_8_754.pdf", "local_pdf": "", "api": ""}, {"title": "Inference from Iterative Simulation Using Multiple Sequences", "doi": "https://doi.org/10.1214/ss/1177011136", "year": 1992, "authors": ["Andrew Gelman", "Donald B. Rubin"], "source": "Statistical Science", "cited": 17066, "abstract": "The Gibbs sampler, the algorithm of Metropolis and similar iterative simulation methods are potentially very helpful for summarizing multivariate distributions. Used naively, however, iterative simulation can give misleading answers. Our methods are simple and generally applicable to the output of any iterative simulation; they are designed for researchers primarily interested in the science underlying the data and models they are analyzing, rather than for researchers interested in the probability theory underlying the iterative simulations themselves. Our recommended strategy is to use several independent sequences, with starting points sampled from an overdispersed distribution. At each step of the iterative simulation, we obtain, for each univariate estimand of interest, a distribution", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-7/issue-4/Inference-from-Iterative-Simulation-Using-Multiple-Sequences/10.1214/ss/1177011136.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Probability, Random Variables, and Stochastic Processes.", "doi": "https://doi.org/10.2307/2288754", "year": 1984, "authors": ["Julia Abrahams", "A. Papoulis"], "source": "Journal of the American Statistical Association", "cited": 16353, "abstract": "Part 1 Probability and Random Variables 1 The Meaning of Probability 2 The Axioms of Probability 3 Repeated Trials 4 The Concept of a Random Variable 5 Functions of One Random Variable 6 Two Random Variables 7 Sequences of Random Variables 8 Statistics Part 2 Stochastic Processes 9 General Concepts 10 Random Walk and Other Applications 11 Spectral Representation 12 Spectral Estimation 13 Mean Square Estimation 14 Entropy 15 Markov Chains 16 Markov Processes and Queueing Theory", "oa": true, "pdf_url": "https://doi.org/10.2307/2288754", "local_pdf": "068_Graph Theory and Probability.pdf", "api": ""}, {"title": "Maps of Dust Infrared Emission for Use in Estimation of Reddening and Cosmic Microwave Background Radiation Foregrounds", "doi": "https://doi.org/10.1086/305772", "year": 1998, "authors": ["David J. Schlegel", "Douglas P. Finkbeiner", "Marc Davis"], "source": "The Astrophysical Journal", "cited": 15395, "abstract": "We present a full-sky 100 μm map that is a reprocessed composite of the COBE /DIRBE and IRAS /ISSA maps, with the zodiacal foreground and confirmed point sources removed. Before using the ISSA maps, we remove the remaining artifacts from the IRAS scan pattern. Using the DIRBE 100 and 240 μm data, we have constructed a map of the dust temperature so that the 100 μm map may be converted to a map proportional to dust column density. The dust temperature varies from 17 to 21 K, which is modest but does modify the estimate of the dust column by a factor of 5. The result of these manipulations is a map with DIRBE quality calibration and IRAS resolution. A wealth of filamentary detail is apparent on many different scales at all Galactic latitudes. In high-latitude regions, the dust map correlates", "oa": true, "pdf_url": "https://iopscience.iop.org/article/10.1086/305772/pdf", "local_pdf": "", "api": ""}, {"title": "Statistical method for testing the neutral mutation hypothesis by DNA polymorphism.", "doi": "https://doi.org/10.1093/genetics/123.3.585", "year": 1989, "authors": ["Fumio Tajima"], "source": "Genetics", "cited": 14343, "abstract": "The relationship between the two estimates of genetic variation at the DNA level, namely the number of segregating sites and the average number of nucleotide differences estimated from pairwise comparison, is investigated. It is found that the correlation between these two estimates is large when the sample size is small, and decreases slowly as the sample size increases. Using the relationship obtained, a statistical method for testing the neutral mutation hypothesis is developed. This method needs only the data of DNA polymorphism, namely the genetic variation within population at the DNA level. A simple method of computer simulation, that was used in order to obtain the distribution of a new statistic developed, is also presented. Applying this statistical method to the five regions of ", "oa": true, "pdf_url": "https://academic.oup.com/genetics/article-pdf/123/3/585/34466400/genetics0585.pdf", "local_pdf": "", "api": ""}, {"title": "BEAST: Bayesian evolutionary analysis by sampling trees", "doi": "https://doi.org/10.1186/1471-2148-7-214", "year": 2007, "authors": ["Alexei J. Drummond", "Andrew Rambaut"], "source": "BMC Evolutionary Biology", "cited": 13193, "abstract": "BACKGROUND: The evolutionary analysis of molecular sequence variation is a statistical enterprise. This is reflected in the increased use of probabilistic models for phylogenetic inference, multiple sequence alignment, and molecular population genetics. Here we present BEAST: a fast, flexible software architecture for Bayesian analysis of molecular sequences related by an evolutionary tree. A large number of popular stochastic models of sequence evolution are provided and tree-based models suitable for both within- and between-species sequence data are implemented. RESULTS: BEAST version 1.4.6 consists of 81000 lines of Java source code, 779 classes and 81 packages. It provides models for DNA and protein sequence evolution, highly parametric coalescent analysis, relaxed clock phylogenetics", "oa": true, "pdf_url": "https://bmcecolevol.biomedcentral.com/counter/pdf/10.1186/1471-2148-7-214", "local_pdf": "010_BEAST_ Bayesian evolutionary analysis by.pdf", "api": ""}, {"title": "Theory of Superconductivity", "doi": "https://doi.org/10.1103/physrev.108.1175", "year": 1957, "authors": ["J. Bardeen", "Leon N. Cooper", "J. R. Schrieffer"], "source": "Physical Review", "cited": 13163, "abstract": "A theory of superconductivity is presented, based on the fact that the interaction between electrons resulting from virtual exchange of phonons is attractive when the energy difference between the electrons states involved is less than the phonon energy, $\\ensuremath{\\hbar}\\ensuremath{\\omega}$. It is favorable to form a superconducting phase when this attractive interaction dominates the repulsive screened Coulomb interaction. The normal phase is described by the Bloch individual-particle model. The ground state of a superconductor, formed from a linear combination of normal state configurations in which electrons are virtually excited in pairs of opposite spin and momentum, is lower in energy than the normal state by amount proportional to an average ${(\\ensuremath{\\hbar}\\ensuremath{\\omeg", "oa": true, "pdf_url": "http://link.aps.org/pdf/10.1103/PhysRev.108.1175", "local_pdf": "", "api": ""}, {"title": "Random effects structure for confirmatory hypothesis testing: Keep it maximal", "doi": "https://doi.org/10.1016/j.jml.2012.11.001", "year": 2013, "authors": ["Dale J. Barr", "Roger Lévy", "Christoph Scheepers", "Harry Tily"], "source": "Journal of Memory and Language", "cited": 10702, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jml.2012.11.001", "local_pdf": "", "api": ""}, {"title": "Bayesian Analysis of Radiocarbon Dates", "doi": "https://doi.org/10.1017/s0033822200033865", "year": 2009, "authors": ["Christopher Bronk Ramsey"], "source": "Radiocarbon", "cited": 8790, "abstract": "If radiocarbon measurements are to be used at all for chronological purposes, we have to use statistical methods for calibration. The most widely used method of calibration can be seen as a simple application of Bayesian statistics, which uses both the information from the new measurement and information from the 14 C calibration curve. In most dating applications, however, we have larger numbers of 14 C measurements and we wish to relate those to events in the past. Bayesian statistics provides a coherent framework in which such analysis can be performed and is becoming a core element in many 14 C dating projects. This article gives an overview of the main model components used in chronological analysis, their mathematical formulation, and examples of how such analyses can be performed us", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/F622173B70F9C1597F2738DEFC597114/S0033822200033865a.pdf/div-class-title-bayesian-analysis-of-radiocarbon-dates-div.pdf", "local_pdf": "013_Bayesian Analysis of Radiocarbon Dates.pdf", "api": ""}, {"title": "Inference of Population Structure Using Multilocus Genotype Data: Linked Loci and Correlated Allele Frequencies", "doi": "https://doi.org/10.1093/genetics/164.4.1567", "year": 2003, "authors": ["Daniel Falush", "Matthew Stephens", "Jonathan K. Pritchard"], "source": "Genetics", "cited": 8110, "abstract": "We describe extensions to the method of Pritchard et al. for inferring population structure from multilocus genotype data. Most importantly, we develop methods that allow for linkage between loci. The new model accounts for the correlations between linked loci that arise in admixed populations (\"admixture linkage disequilibium\"). This modification has several advantages, allowing (1) detection of admixture events farther back into the past, (2) inference of the population of origin of chromosomal regions, and (3) more accurate estimates of statistical uncertainty when linked loci are used. It is also of potential use for admixture mapping. In addition, we describe a new prior model for the allele frequencies within each population, which allows identification of subtle population subdivisi", "oa": true, "pdf_url": "https://academic.oup.com/genetics/article-pdf/164/4/1567/37401990/genetics1567.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "The Theory of Probability", "doi": "https://doi.org/10.1038/109132a0", "year": 1922, "authors": ["Harold Jeffreys", "P. A. P. Moran", "C. Chatfield"], "source": "Nature", "cited": 6732, "abstract": "Abstract Jeffreys' Theory of Probability, first published in 1939, was the first attempt to develop a fundamental theory of scientific inference based on Bayesian statistics. His ideas were well ahead of their time and it is only in the past ten years that the subject of Bayes' factors has been significantly developed and extended. Recent work has made Bayesian statistics an essential subject for graduate students and researchers. This seminal book is their starting point.", "oa": true, "pdf_url": "https://www.nature.com/articles/109132a0.pdf", "local_pdf": "", "api": ""}, {"title": "Statistical Inference", "doi": "https://doi.org/10.1201/9781003456285", "year": 1993, "authors": ["George Casella", "Roger L. Berger"], "source": "Biometrics", "cited": 5366, "abstract": "This classic textbook builds theoretical statistics from the first principles of probability theory. Starting from the basics of probability, the authors develop the theory of statistical inference using techniques, definitions, and concepts that are statistical and natural extensions, and consequences, of previous concepts. It covers all topics from a standard inference course including: distributions, random variables, data reduction, point estimation, hypothesis testing, and interval estimation. Features The classic graduate-level textbook on statistical inference Develops elements of statistical theory from first principles of probability Written in a lucid style accessible to anyone with some background in calculus Covers all key topics of a standard course in inference Hundreds of ex", "oa": true, "pdf_url": "https://doi.org/10.2307/2532634", "local_pdf": "", "api": ""}, {"title": "Bayesian Test for Colocalisation between Pairs of Genetic Association Studies Using Summary Statistics", "doi": "https://doi.org/10.1371/journal.pgen.1004383", "year": 2014, "authors": ["Claudia Giambartolomei", "Damjan Vukcevic", "Eric E. Schadt", "Lude Franke", "Aroon D. Hingorani", "Chris Wallace"], "source": "PLoS Genetics", "cited": 4765, "abstract": "Genetic association studies, in particular the genome-wide association study (GWAS) design, have provided a wealth of novel insights into the aetiology of a wide range of human diseases and traits, in particular cardiovascular diseases and lipid biomarkers. The next challenge consists of understanding the molecular basis of these associations. The integration of multiple association datasets, including gene expression datasets, can contribute to this goal. We have developed a novel statistical methodology to assess whether two association signals are consistent with a shared causal variant. An application is the integration of disease scans with expression quantitative trait locus (eQTL) studies, but any pair of GWAS datasets can be integrated in this framework. We demonstrate the value of", "oa": true, "pdf_url": "https://journals.plos.org/plosgenetics/article/file?id=10.1371/journal.pgen.1004383&type=printable", "local_pdf": "017_Bayesian Test for Colocalisation between.pdf", "api": ""}, {"title": "Model Selection and Inference: A Practical Information-Theoretic Approach", "doi": "https://doi.org/10.2307/2669574", "year": 2000, "authors": ["Robert L. Strawderman", "Kenneth P. Burnham", "David R. Anderson"], "source": "Journal of the American Statistical Association", "cited": 4218, "abstract": "We wrote this book to introduce graduate students and research workers in various scientific disciplines to the use of information-theoretic approaches in the analysis of empirical data.In its fully developed form, the information-theoretic approach allows inference based on more than one model (including estimates of unconditional precision); in its initial form, it is useful in selecting a \"best\" model and ranking the remaining models.We believe that often the critical issue in data analysis is the selection of a good approximating model that best represents the inference supported by the data (an estimated \"best approximating model\").Information theory includes the well-known Kullback-Leibler \"distance\" between two models (actually, probability distributions), and this represents a fund", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f2669574", "local_pdf": "", "api": ""}, {"title": "Bayesian t tests for accepting and rejecting the null hypothesis", "doi": "https://doi.org/10.3758/pbr.16.2.225", "year": 2009, "authors": ["Jeffrey N. Rouder", "Paul L. Speckman", "Dongchu Sun", "Richard D. Morey", "Geoffrey Iverson"], "source": "Psychonomic Bulletin & Review", "cited": 4006, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/PBR.16.2.225.pdf", "local_pdf": "019_Bayesian t tests for accepting and rejec.pdf", "api": ""}, {"title": "Permutation inference for the general linear model", "doi": "https://doi.org/10.1016/j.neuroimage.2014.01.060", "year": 2014, "authors": ["Anderson M. Winkler", "Gerard R. Ridgway", "Matthew Webster", "Stephen M. Smith", "Thomas E. Nichols"], "source": "NeuroImage", "cited": 3878, "abstract": "Permutation methods can provide exact control of false positives and allow the use of non-standard statistics, making only weak assumptions about the data. With the availability of fast and inexpensive computing, their main limitation would be some lack of flexibility to work with arbitrary experimental designs. In this paper we report on results on approximate permutation methods that are more flexible with respect to the experimental design and nuisance variables, and conduct detailed simulations to identify the best method for settings that are typical for imaging research scenarios. We present a generic framework for permutation inference for complex general linear models (GLMS) when the errors are exchangeable and/or have a symmetric distribution, and show that, even in the presence o", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S1053811914000913/pdf", "local_pdf": "", "api": ""}, {"title": "A Measure of Asymptotic Efficiency for Tests of a Hypothesis Based on the sum of Observations", "doi": "https://doi.org/10.1214/aoms/1177729330", "year": 1952, "authors": ["Herman Chernoff"], "source": "The Annals of Mathematical Statistics", "cited": 3642, "abstract": "In many cases an optimum or computationally convenient test of a simple hypothesis $H_0$ against a simple alternative $H_1$ may be given in the following form. Reject $H_0$ if $S_n = \\sum^n_{j=1} X_j \\leqq k,$ where $X_1, X_2, \\cdots, X_n$ are $n$ independent observations of a chance variable $X$ whose distribution depends on the true hypothesis and where $k$ is some appropriate number. In particular the likelihood ratio test for fixed sample size can be reduced to this form. It is shown that with each test of the above form there is associated an index $\\rho$. If $\\rho_1$ and $\\rho_2$ are the indices corresponding to two alternative tests $e = \\log \\rho_1/\\log \\rho_2$ measures the relative efficiency of these tests in the following sense. For large samples, a sample of size $n$ with the f", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-23/issue-4/A-Measure-of-Asymptotic-Efficiency-for-Tests-of-a-Hypothesis/10.1214/aoms/1177729330.pdf", "local_pdf": "", "api": ""}, {"title": "Causal Inference without Balance Checking: Coarsened Exact Matching", "doi": "https://doi.org/10.1093/pan/mpr013", "year": 2011, "authors": ["Stefano M. Iacus", "Gary King", "Giuseppe Porro"], "source": "Political Analysis", "cited": 3612, "abstract": "We discuss a method for improving causal inferences called “Coarsened Exact Matching” (CEM), and the new “Monotonic Imbalance Bounding” (MIB) class of matching methods from which CEM is derived. We summarize what is known about CEM and MIB, derive and illustrate several new desirable statistical properties of CEM, and then propose a variety of useful extensions. We show that CEM possesses a wide range of statistical properties not available in most other matching methods but is at the same time exceptionally easy to comprehend and use. We focus on the connection between theoretical properties and practical applications. We also make available easy-to-use open source software for R, Stata , and SPSS that implement all our suggestions.", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/5ABCF5B3FC3089A87FD59CECBB3465C0/S1047198700012985a.pdf/div-class-title-causal-inference-without-balance-checking-coarsened-exact-matching-div.pdf", "local_pdf": "", "api": ""}, {"title": "Mathematical Statistics and Data Analysis", "doi": "https://doi.org/10.2307/3556160", "year": 1989, "authors": ["Larry Rabinowitz", "John A. Rice"], "source": "Technometrics", "cited": 3094, "abstract": "1. Probability. 2. Random Variables. 3. Joint Distributions. 4. Expected Values. 5. Limit Theorems. 6. Distributions Derived from the Normal Distribution. 7. Survey Sampling. 8. Estimation of Parameters and Fitting of Probability Distributions. 9. Testing Hypotheses and Assessing Goodness of Fit. 10. Summarizing Data. 11. Comparing Two Samples. 12. The Analysis of Variance. 13. The Analysis of Categorical Data. 14. Linear Least Squares. 15. Decision Theory and Bayesian Inference.", "oa": true, "pdf_url": "https://doi.org/10.2307/3556160", "local_pdf": "", "api": ""}, {"title": "Inference of Population Splits and Mixtures from Genome-Wide Allele Frequency Data", "doi": "https://doi.org/10.1371/journal.pgen.1002967", "year": 2012, "authors": ["Joseph K. Pickrell", "Jonathan K. Pritchard"], "source": "PLoS Genetics", "cited": 3066, "abstract": "Many aspects of the historical relationships between populations in a species are reflected in genetic data. Inferring these relationships from genetic data, however, remains a challenging task. In this paper, we present a statistical model for inferring the patterns of population splits and mixtures in multiple populations. In our model, the sampled populations in a species are related to their common ancestor through a graph of ancestral populations. Using genome-wide allele frequency data and a Gaussian approximation to genetic drift, we infer the structure of this graph. We applied this method to a set of 55 human populations and a set of 82 dog breeds and wild canids. In both species, we show that a simple bifurcating tree does not fully describe the data; in contrast, we infer many m", "oa": true, "pdf_url": "https://doi.org/10.1371/journal.pgen.1002967", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "HyPhy: hypothesis testing using phylogenies", "doi": "https://doi.org/10.1093/bioinformatics/bti079", "year": 2004, "authors": ["Sergei L. Kosakovsky Pond", "Simon D. W. Frost", "Spencer V. Muse"], "source": "Bioinformatics", "cited": 3062, "abstract": "UNLABELLED: The HyPhypackage is designed to provide a flexible and unified platform for carrying out likelihood-based analyses on multiple alignments of molecular sequence data, with the emphasis on studies of rates and patterns of sequence evolution. AVAILABILITY: http://www.hyphy.org CONTACT: muse@stat.ncsu.edu SUPPLEMENTARY INFORMATION: HyPhydocumentation and tutorials are available at http://www.hyphy.org.", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/21/5/676/48962517/bioinformatics_21_5_676.pdf", "local_pdf": "", "api": ""}, {"title": "Bayesian Inference of Species Trees from Multilocus Data", "doi": "https://doi.org/10.1093/molbev/msp274", "year": 2009, "authors": ["Joseph Heled", "Alexei J. Drummond"], "source": "Molecular Biology and Evolution", "cited": 2573, "abstract": "Until recently, it has been common practice for a phylogenetic analysis to use a single gene sequence from a single individual organism as a proxy for an entire species. With technological advances, it is now becoming more common to collect data sets containing multiple gene loci and multiple individuals per species. These data sets often reveal the need to directly model intraspecies polymorphism and incomplete lineage sorting in phylogenetic estimation procedures. For a single species, coalescent theory is widely used in contemporary population genetics to model intraspecific gene trees. Here, we present a Bayesian Markov chain Monte Carlo method for the multispecies coalescent. Our method coestimates multiple gene trees embedded in a shared species tree along with the effective populati", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/27/3/570/6314000/msp274.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Terrace Aware Data Structure for Phylogenomic Inference from Supermatrices", "doi": "https://doi.org/10.1093/sysbio/syw037", "year": 2016, "authors": ["Olga Chernomor", "Arndt von Haeseler", "Bùi Quang Minh"], "source": "Systematic Biology", "cited": 2415, "abstract": "In phylogenomics the analysis of concatenated gene alignments, the so-called supermatrix, is commonly accompanied by the assumption of partition models. Under such models each gene, or more generally partition, is allowed to evolve under its own evolutionary model. Although partition models provide a more comprehensive analysis of supermatrices, missing data may hamper the tree search algorithms due to the existence of phylogenetic (partial) terraces. Here, we introduce the phylogenetic terrace aware (PTA) data structure for the efficient analysis under partition models. In the presence of missing data PTA exploits (partial) terraces and induced partition trees to save computation time. We show that an implementation of PTA in IQ-TREE leads to a substantial speedup of up to 4.5 and 8 times", "oa": true, "pdf_url": "https://academic.oup.com/sysbio/article-pdf/65/6/997/19609034/syw037.pdf", "local_pdf": "", "api": ""}, {"title": "Causal inference in statistics: An overview", "doi": "https://doi.org/10.1214/09-ss057", "year": 2009, "authors": ["Judea Pearl"], "source": "Statistics Surveys", "cited": 2395, "abstract": "This review presents empirical researchers with recent advances in causal inference, and stresses the paradigmatic shifts that must be undertaken in moving from traditional statistical analysis to causal analysis of multivariate data. Special emphasis is placed on the assumptions that underly all causal inferences, the languages used in formulating those assumptions, the conditional nature of all causal and counterfactual claims, and the methods that have been developed for the assessment of such claims. These advances are illustrated using a general theory of causation based on the Structural Causal Model (SCM) described in Pearl (2000a), which subsumes and unifies other approaches to causation, and provides a coherent mathematical foundation for the analysis of causes and counterfactuals", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistics-surveys/volume-3/issue-none/Causal-inference-in-statistics-An-overview/10.1214/09-SS057.pdf", "local_pdf": "", "api": ""}, {"title": "Stochastic Volatility: Likelihood Inference and Comparison with ARCH Models", "doi": "https://doi.org/10.1111/1467-937x.00050", "year": 1998, "authors": ["Sang‐Joon Kim", "Neil Shepherd", "Siddhartha Chib"], "source": "The Review of Economic Studies", "cited": 2342, "abstract": "In this paper, Markov chain Monte Carlo sampling methods are exploited to provide a unified, practical likelihood-based framework for the analysis of stochastic volatility models. A highly effective method is developed that samples all the unobserved volatilities at once using an approximating offset mixture model, followed by an importance reweighting procedure. This approach is compared with several alternative methods using real data. The paper also develops simulation-based methods for filtering, likelihood evaluation and model failure diagnostics. The issue of model choice using non-nested likelihood ratios and Bayes factors is also investigated. These methods are used to compare the fit of stochastic volatility and GARCH models. All the procedures are illustrated in detail.", "oa": true, "pdf_url": "https://doi.org/10.1111/1467-937x.00050", "local_pdf": "", "api": ""}, {"title": "A brief introduction to mixed effects modelling and multi-model inference in ecology", "doi": "https://doi.org/10.7717/peerj.4794", "year": 2018, "authors": ["Xavier A. Harrison", "Lynda Donaldson", "Maria Correa-Cano", "Julian Evans", "David N. Fisher", "Cecily Goodwin"], "source": "PeerJ", "cited": 2133, "abstract": "The use of linear mixed effects models (LMMs) is increasingly common in the analysis of biological data. Whilst LMMs offer a flexible approach to modelling a broad range of data types, ecological data are often complex and require complex model structures, and the fitting and interpretation of such models is not always straightforward. The ability to achieve robust biological inference requires that practitioners know how and when to apply these tools. Here, we provide a general overview of current methods for the application of LMMs to biological data, and highlight the typical pitfalls that can be encountered in the statistical modelling process. We tackle several issues regarding methods of model selection, with particular reference to the use of information theory and multi-model infer", "oa": true, "pdf_url": "https://doi.org/10.7717/peerj.4794", "local_pdf": "", "api": ""}, {"title": "Confidence intervals rather than P values: estimation rather than hypothesis testing.", "doi": "https://doi.org/10.1136/bmj.292.6522.746", "year": 1986, "authors": ["Michael Gardner", "Douglas G. Altman"], "source": "BMJ", "cited": 2050, "abstract": "Overemphasis on hypothesis testing--and the use of P values to dichotomise significant or non-significant results--has detracted from more useful approaches to interpreting study results, such as estimation and confidence intervals. In medical studies investigators are usually interested in determining the size of difference of a measured outcome between groups, rather than a simple indication of whether or not it is statistically significant. Confidence intervals present a range of values, on the basis of the sample data, in which the population value for such a difference may lie. Some methods of calculating confidence intervals for means and differences between means are given, with similar information for proportions. The paper also gives suggestions for graphical display. Confidence i", "oa": true, "pdf_url": "https://www.bmj.com/content/bmj/292/6522/746.full.pdf", "local_pdf": "", "api": ""}, {"title": "Sparse and Compositionally Robust Inference of Microbial Ecological Networks", "doi": "https://doi.org/10.1371/journal.pcbi.1004226", "year": 2015, "authors": ["Zachary Kurtz", "Christian L. Müller", "Emily R. Miraldi", "Dan R. Littman", "Martin J. Blaser", "Richard Bonneau"], "source": "PLoS Computational Biology", "cited": 1951, "abstract": "16S ribosomal RNA (rRNA) gene and other environmental sequencing techniques provide snapshots of microbial communities, revealing phylogeny and the abundances of microbial populations across diverse ecosystems. While changes in microbial community structure are demonstrably associated with certain environmental conditions (from metabolic and immunological health in mammals to ecological stability in soils and oceans), identification of underlying mechanisms requires new statistical tools, as these datasets present several technical challenges. First, the abundances of microbial operational taxonomic units (OTUs) from amplicon-based datasets are compositional. Counts are normalized to the total number of counts in the sample. Thus, microbial abundances are not independent, and traditional s", "oa": true, "pdf_url": "https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1004226&type=printable", "local_pdf": "032_Sparse and Compositionally Robust Infere.pdf", "api": ""}, {"title": "The Future of Data Analysis", "doi": "https://doi.org/10.1214/aoms/1177704711", "year": 1962, "authors": ["John W. Tukey"], "source": "The Annals of Mathematical Statistics", "cited": 1889, "abstract": "For a long time I have thought I was a statistician, interested in inferences from the particular to the general. But as I have watched mathematical statistics evolve, I have had cause to wonder and to doubt. And when I have pondered about why such techniques as the spectrum analysis of time series have proved so useful, it has become clear that their “dealing with fluctuations” aspects are, in many circumstances, of lesser importance than the aspects that would already have been required to deal effectively with the simpler case of very extensive data, where fluctuations would no longer be a problem. All in all, I have come to feel that my central interest is in data analysis, which I take to include, among other things: procedures for analyzing data, techniques for interpreting the resul", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-33/issue-1/The-Future-of-Data-Analysis/10.1214/aoms/1177704711.pdf", "local_pdf": "", "api": ""}, {"title": "Bayesian inference for psychology. Part II: Example applications with JASP", "doi": "https://doi.org/10.3758/s13423-017-1323-7", "year": 2017, "authors": ["Eric‐Jan Wagenmakers", "Jonathon Love", "Maarten Marsman", "Tahira Jamil", "Alexander Ly", "Josine Verhagen"], "source": "Psychonomic Bulletin & Review", "cited": 1837, "abstract": "Bayesian hypothesis testing presents an attractive alternative to p value hypothesis testing. Part I of this series outlined several advantages of Bayesian hypothesis testing, including the ability to quantify evidence and the ability to monitor and update this evidence as data come in, without the need to know the intention with which the data were collected. Despite these and other practical advantages, Bayesian hypothesis tests are still reported relatively rarely. An important impediment to the widespread adoption of Bayesian tests is arguably the lack of user-friendly software for the run-of-the-mill statistical problems that confront psychologists for the analysis of almost every experiment: the t-test, ANOVA, correlation, regression, and contingency tables. In Part II of this series", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13423-017-1323-7.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Homo Heuristicus: Why Biased Minds Make Better Inferences", "doi": "https://doi.org/10.1111/j.1756-8765.2008.01006.x", "year": 2009, "authors": ["Gerd Gigerenzer", "Henry Brighton"], "source": "Topics in Cognitive Science", "cited": 1826, "abstract": "Heuristics are efficient cognitive processes that ignore information. In contrast to the widely held view that less processing reduces accuracy, the study of heuristics shows that less information, computation, and time can in fact improve accuracy. We review the major progress made so far: (a) the discovery of less-is-more effects; (b) the study of the ecological rationality of heuristics, which examines in which environments a given strategy succeeds or fails, and why; (c) an advancement from vague labels to computational models of heuristics; (d) the development of a systematic theory of heuristics that identifies their building blocks and the evolved capacities they exploit, and views the cognitive system as relying on an \"adaptive toolbox;\" and (e) the development of an empirical meth", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1756-8765.2008.01006.x", "local_pdf": "", "api": ""}, {"title": "Wisdom of crowds for robust gene network inference", "doi": "https://doi.org/10.1038/nmeth.2016", "year": 2012, "authors": ["Daniel Marbach", "James C. Costello", "Robert Küffner", "Nic M. Vega", "Robert J. Prill", "Diogo M. Camacho"], "source": "Nature Methods", "cited": 1800, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.2016.pdf", "local_pdf": "", "api": ""}, {"title": "On the Application of Probability Theory to Agricultural Experiments. Essay on Principles. Section 9", "doi": "https://doi.org/10.1214/ss/1177012031", "year": 1990, "authors": ["Jerzy Splawa-Neyman", "D. M. Dabrowska", "Terence P. Speed"], "source": "Statistical Science", "cited": 1670, "abstract": "In the portion of the paper translated here, Neyman introduces a model for the analysis of field experiments conducted for the purpose of comparing a number of crop varieties, which makes use of a double-indexed array of unknown potential yields, one index corresponding to varieties and the other to plots. The yield corresponding to only one variety will be observed on any given plot, but through an urn model embodying sampling without replacement from this doubly indexed array, Neyman obtains a formula for the variance of the difference between the averages of the observed yields of two varieties. This variance involves the variance over all plots of the potential yields and the correlation coefficient $r$ between the potential yields of the two varieties on the same plot. Since it is imp", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-5/issue-4/On-the-Application-of-Probability-Theory-to-Agricultural-Experiments-Essay/10.1214/ss/1177012031.pdf", "local_pdf": "", "api": ""}, {"title": "On the mathematical foundations of learning", "doi": "https://doi.org/10.1090/s0273-0979-01-00923-5", "year": 2001, "authors": ["Felipe Cucker", "Steve Smale"], "source": "Bulletin of the American Mathematical Society", "cited": 1596, "abstract": "The problem of learning is arguably at the very core of the problem of intelligence, both biological and artificial.", "oa": true, "pdf_url": "https://www.ams.org/bull/2002-39-01/S0273-0979-01-00923-5/S0273-0979-01-00923-5.pdf", "local_pdf": "", "api": ""}, {"title": "Hierarchical Bayesian inference in the visual cortex", "doi": "https://doi.org/10.1364/josaa.20.001434", "year": 2003, "authors": ["Tai Sing Lee", "David B. Mumford"], "source": "Journal of the Optical Society of America A", "cited": 1549, "abstract": "Traditional views of visual processing suggest that early visual neurons in areas V1 and V2 are static spatiotemporal filters that extract local features from a visual scene. The extracted information is then channeled through a feedforward chain of modules in successively higher visual areas for further analysis. Recent electrophysiological recordings from early visual neurons in awake behaving monkeys reveal that there are many levels of complexity in the information processing of the early visual cortex, as seen in the long-latency responses of its neurons. These new findings suggest that activity in the early visual cortex is tightly coupled and highly interactive with the rest of the visual system. They lead us to propose a new theoretical setting based on the mathematical framework o", "oa": true, "pdf_url": "https://opg.optica.org/viewmedia.cfm?uri=josaa-20-7-1434&seq=0", "local_pdf": "", "api": ""}, {"title": "Statistics versus machine learning", "doi": "https://doi.org/10.1038/nmeth.4642", "year": 2018, "authors": ["Danilo Bzdok", "Naomi Altman", "Martin Krzywinski"], "source": "Nature Methods", "cited": 1540, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.4642.pdf", "local_pdf": "043_The Bayesian New Statistics_ Hypothesis .pdf", "api": ""}, {"title": "Strong Control, Conservative Point Estimation and Simultaneous Conservative Consistency of False Discovery Rates: A Unified Approach", "doi": "https://doi.org/10.1111/j.1467-9868.2004.00439.x", "year": 2003, "authors": ["John D. Storey", "Jonathan Taylor", "David Siegmund"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 1451, "abstract": "Summary The false discovery rate (FDR) is a multiple hypothesis testing quantity that describes the expected proportion of false positive results among all rejected null hypotheses. Benjamini and Hochberg introduced this quantity and proved that a particular step-up p-value method controls the FDR. Storey introduced a point estimate of the FDR for fixed significance regions. The former approach conservatively controls the FDR at a fixed predetermined level, and the latter provides a conservatively biased estimate of the FDR for a fixed predetermined significance region. In this work, we show in both finite sample and asymptotic settings that the goals of the two approaches are essentially equivalent. In particular, the FDR point estimates can be used to define valid FDR controlling procedu", "oa": true, "pdf_url": "https://academic.oup.com/jrsssb/article-pdf/66/1/187/49727331/jrsssb_66_1_187.pdf", "local_pdf": "", "api": ""}, {"title": "A CENTRAL LIMIT THEOREM AND A STRONG MIXING CONDITION", "doi": "https://doi.org/10.1073/pnas.42.1.43", "year": 1956, "authors": ["M. Rosenblatt"], "source": "Proceedings of the National Academy of Sciences", "cited": 1395, "abstract": "* research for this paper was supported by the United States Air Force under Contract No. AF18(600-685) monitored by the Office of Scientific Research. 1 A discussion of the problem along with the necessary references will be found in Harry Pollard, The Harmonic Analysis of Bounded Functions, Duke Math. / . , 20, 499-512, 1953. 2 See ibid. 3 See S. Bochner, Fouriersche Integrate (Leipzig, 1932), p. 33. 4 Levitan polynomial. See N.I. Achieser, Approximationstheorie (Berlin, 1953), p. 146.", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.42.1.43", "local_pdf": "092_A central limit theorem for quadratic fo.pdf", "api": ""}, {"title": "The Bayesian New Statistics: Hypothesis testing, estimation, meta-analysis, and power analysis from a Bayesian perspective", "doi": "https://doi.org/10.3758/s13423-016-1221-4", "year": 2017, "authors": ["John K. Kruschke", "Torrin M. Liddell"], "source": "Psychonomic Bulletin & Review", "cited": 1384, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13423-016-1221-4.pdf", "local_pdf": "043_The Bayesian New Statistics_ Hypothesis .pdf", "api": ""}, {"title": "SUN: A Bayesian framework for saliency using natural statistics", "doi": "https://doi.org/10.1167/8.7.32", "year": 2008, "authors": ["Lingyun Zhang", "Matthew H. Tong", "Tim K. Marks", "Honghao Shan", "Garrison W. Cottrell"], "source": "Journal of Vision", "cited": 1237, "abstract": "We propose a definition of saliency by considering what the visual system is trying to optimize when directing attention. The resulting model is a Bayesian framework from which bottom-up saliency emerges naturally as the self-information of visual features, and overall saliency (incorporating top-down information with bottom-up saliency) emerges as the pointwise mutual information between the features and the target when searching for a target. An implementation of our framework demonstrates that our model's bottom-up saliency maps perform as well as or better than existing algorithms in predicting people's fixations in free viewing. Unlike existing saliency measures, which depend on the statistics of the particular image being viewed, our measure of saliency is derived from natural image ", "oa": true, "pdf_url": "https://doi.org/10.1167/8.7.32", "local_pdf": "", "api": ""}, {"title": "Active Inference: A Process Theory", "doi": "https://doi.org/10.1162/neco_a_00912", "year": 2016, "authors": ["Karl Friston", "Thomas H. B. FitzGerald", "Francesco Rigoli", "Philipp Schwartenbeck", "Giovanni Pezzulo"], "source": "Neural Computation", "cited": 1224, "abstract": "This article describes a process theory based on active inference and belief propagation. Starting from the premise that all neuronal processing (and action selection) can be explained by maximizing Bayesian model evidence-or minimizing variational free energy-we ask whether neuronal responses can be described as a gradient descent on variational free energy. Using a standard (Markov decision process) generative model, we derive the neuronal dynamics implicit in this description and reproduce a remarkable range of well-characterized neuronal phenomena. These include repetition suppression, mismatch negativity, violation responses, place-cell activity, phase precession, theta sequences, theta-gamma coupling, evidence accumulation, race-to-bound dynamics, and transfer of dopamine responses. ", "oa": true, "pdf_url": "https://doi.org/10.1162/neco_a_00912", "local_pdf": "", "api": ""}, {"title": "Dynamic Ideal Point Estimation via Markov Chain Monte Carlo for the U.S. Supreme Court, 1953–1999", "doi": "https://doi.org/10.1093/pan/10.2.134", "year": 2002, "authors": ["Andrew D. Martin", "Kevin M. Quinn"], "source": "Political Analysis", "cited": 1186, "abstract": "At the heart of attitudinal and strategic explanations of judicial behavior is the assumption that justices have policy preferences. In this paper we employ Markov chain Monte Carlo methods to fit a Bayesian measurement model of ideal points for all justices serving on the U.S. Supreme Court from 1953 through 1999. We are particularly interested in determining to what extent ideal points of justices change throughout their tenure on the Court. This is important because judicial politics scholars oftentimes invoke preference measures that are time invariant. To investigate preference change, we posit a dynamic item response model that allows ideal points to change systematically over time. Additionally, we introduce Bayesian methods for fitting multivariate dynamic linear models to politica", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/2A57930D5D0C81216491B40CA2BA5D12/S1047198700009931a.pdf/div-class-title-dynamic-ideal-point-estimation-via-markov-chain-monte-carlo-for-the-u-s-supreme-court-1953-1999-div.pdf", "local_pdf": "046_Dynamic Ideal Point Estimation via Marko.pdf", "api": ""}, {"title": "Wilcoxon-Mann-Whitney or t-test? On assumptions for hypothesis tests and multiple interpretations of decision rules", "doi": "https://doi.org/10.1214/09-ss051", "year": 2010, "authors": ["Michael P. Fay", "Michael A. Proschan"], "source": "Statistics Surveys", "cited": 1141, "abstract": "In a mathematical approach to hypothesis tests, we start with a clearly defined set of hypotheses and choose the test with the best properties for those hypotheses. In practice, we often start with less precise hypotheses. For example, often a researcher wants to know which of two groups generally has the larger responses, and either a t-test or a Wilcoxon-Mann-Whitney (WMW) test could be acceptable. Although both t-tests and WMW tests are usually associated with quite different hypotheses, the decision rule and p-value from either test could be associated with many different sets of assumptions, which we call perspectives. It is useful to have many of the different perspectives to which a decision rule may be applied collected in one place, since each perspective allows a different interp", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistics-surveys/volume-4/issue-none/Wilcoxon-Mann-Whitney-or-t-test-On-assumptions-for-hypothesis/10.1214/09-SS051.pdf", "local_pdf": "", "api": ""}, {"title": "Multiple Hypothesis Testing in Microarray Experiments", "doi": "https://doi.org/10.1214/ss/1056397487", "year": 2003, "authors": ["Sandrine Dudoit", "Juliet Popper Shaffer", "Jennifer C. Boldrick"], "source": "Statistical Science", "cited": 1098, "abstract": "DNA microarrays are part of a new and promising class of biotechnologies that allow the monitoring of expression levels in cells for thousands of genes simultaneously. An important and common question in DNA microarray experiments is the identification of differentially expressed genes, that is, genes whose expression levels are associated with a response or covariate of interest. The biological question of differential expression can be restated as a problem in multiple hypothesis testing: the simultaneous test for each gene of the null hypothesis of no association between the expression levels and the responses or covariates. As a typical microarray experiment measures expression levels for thousands of genes simultaneously, large multiplicity problems are generated. This article discuss", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-18/issue-1/Multiple-Hypothesis-Testing-in-Microarray-Experiments/10.1214/ss/1056397487.pdf", "local_pdf": "", "api": ""}, {"title": "Central limit theorem: the cornerstone of modern statistics", "doi": "https://doi.org/10.4097/kjae.2017.70.2.144", "year": 2017, "authors": ["Sang Gyu Kwak", "Jonghae Kim"], "source": "Korean Journal of Anesthesiology", "cited": 1072, "abstract": ", distribute normally with mean, µ, and variance, [Formula: see text]. Using the central limit theorem, a variety of parametric tests have been developed under assumptions about the parameters that determine the population probability distribution. Compared to non-parametric tests, which do not require any assumptions about the population probability distribution, parametric tests produce more accurate and precise estimates with higher statistical powers. However, many medical researchers use parametric tests to present their data without knowledge of the contribution of the central limit theorem to the development of such tests. Thus, this review presents the basic concepts of the central limit theorem and its role in binomial distributions and the Student's t-test, and provides an exampl", "oa": true, "pdf_url": "https://doi.org/10.4097/kjae.2017.70.2.144", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "Bayesian Versus Orthodox Statistics: Which Side Are You On?", "doi": "https://doi.org/10.1177/1745691611406920", "year": 2011, "authors": ["Zoltán Dienes"], "source": "Perspectives on Psychological Science", "cited": 993, "abstract": "Researchers are often confused about what can be inferred from significance tests. One problem occurs when people apply Bayesian intuitions to significance testing-two approaches that must be firmly separated. This article presents some common situations in which the approaches come to different conclusions; you can see where your intuitions initially lie. The situations include multiple testing, deciding when to stop running participants, and when a theory was thought of relative to finding out results. The interpretation of nonsignificant results has also been persistently problematic in a way that Bayesian inference can clarify. The Bayesian and orthodox approaches are placed in the context of different notions of rationality, and I accuse myself and others as having been irrational in ", "oa": true, "pdf_url": "https://doi.org/10.1177/1745691611406920", "local_pdf": "", "api": ""}, {"title": "Birds of the Same Feather Tweet Together: Bayesian Ideal Point Estimation Using Twitter Data", "doi": "https://doi.org/10.1093/pan/mpu011", "year": 2014, "authors": ["Pablo Barberá"], "source": "Political Analysis", "cited": 992, "abstract": "Politicians and citizens increasingly engage in political conversations on social media outlets such as Twitter. In this article, I show that the structure of the social networks in which they are embedded can be a source of information about their ideological positions. Under the assumption that social networks are homophilic, I develop a Bayesian Spatial Following model that considers ideology as a latent variable, whose value can be inferred by examining which politics actors each user is following. This method allows us to estimate ideology for more actors than any existing alternative, at any point in time and across many polities. I apply this method to estimate ideal points for a large sample of both elite and mass public Twitter users in the United States and five European countrie", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/91E37205F69AEA32EF27F12563DC2A0A/S104719870001161Xa.pdf/div-class-title-birds-of-the-same-feather-tweet-together-bayesian-ideal-point-estimation-using-twitter-data-div.pdf", "local_pdf": "051_Birds of the Same Feather Tweet Together.pdf", "api": ""}, {"title": "Robust performance hypothesis testing with the Sharpe ratio", "doi": "https://doi.org/10.1016/j.jempfin.2008.03.002", "year": 2008, "authors": ["Oliver Ledoit", "Michael Wolf"], "source": "Journal of Empirical Finance", "cited": 985, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jempfin.2008.03.002", "local_pdf": "", "api": ""}, {"title": "Estimation of the point of zero charge of simple oxides by mass titration", "doi": "https://doi.org/10.1016/0021-9797(89)90086-6", "year": 1989, "authors": ["Joong S Noh", "J.A. Schwarz"], "source": "Journal of Colloid and Interface Science", "cited": 908, "abstract": "A method is proposed to estimate the point of zero charge (pzc) of pure compounds which can be described accurately by the surface ionization model of amphoteric oxides. It is demonstrated that under the limiting conditions of “infinite” mass/volume ratio, the pH of the system will approach pH∞ = 12(pK1 + pK2)  pzc. Experimental values of the pH of the oxides of titanium, aluminum, a silicon suspended in a closed aqueous system exhibited the existence of a constant pH at high mass fractions. This limiting pH is found to be a reasonable estimate for the point of zero charge of each oxide.", "oa": true, "pdf_url": "https://doi.org/10.1016/0021-9797(89)90086-6", "local_pdf": "046_Dynamic Ideal Point Estimation via Marko.pdf", "api": ""}, {"title": "Mathematical Statistics and Data Analysis", "doi": "https://doi.org/10.2307/1269179", "year": 1995, "authors": ["Eric R. Ziegel", "John Rice"], "source": "Technometrics", "cited": 844, "abstract": "Concluding Remarks p.Problems p.", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f1269179", "local_pdf": "", "api": ""}, {"title": "Hypothesis Testing and Multiplicative Interaction Terms", "doi": "https://doi.org/10.1017/s0020818304040251", "year": 2004, "authors": ["Bear Braumoeller"], "source": "International Organization", "cited": 832, "abstract": "When a statistical equation incorporates a multiplicative term in an attempt to model interaction effects, the statistical significance of the lower-order coefficients is largely useless for the typical purposes of hypothesis testing. This fact remains largely unappreciated in political science, however. This brief article explains this point, provides examples, and offers some suggestions for more meaningful interpretation.", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/5AE39EABAA8F26582C65F0D3FAD153D8/S0020818304040251a.pdf/div-class-title-hypothesis-testing-and-multiplicative-interaction-terms-div.pdf", "local_pdf": "073_A default Bayesian hypothesis test for c.pdf", "api": ""}, {"title": "HyPhy 2.5—A Customizable Platform for Evolutionary Hypothesis Testing Using Phylogenies", "doi": "https://doi.org/10.1093/molbev/msz197", "year": 2019, "authors": ["Sergei L. Kosakovsky Pond", "Art F. Y. Poon", "Ryan Velazquez", "Steven Weaver", "N. Lance Hepler", "Ben Murrell"], "source": "Molecular Biology and Evolution", "cited": 822, "abstract": "HYpothesis testing using PHYlogenies (HyPhy) is a scriptable, open-source package for fitting a broad range of evolutionary models to multiple sequence alignments, and for conducting subsequent parameter estimation and hypothesis testing, primarily in the maximum likelihood statistical framework. It has become a popular choice for characterizing various aspects of the evolutionary process: natural selection, evolutionary rates, recombination, and coevolution. The 2.5 release (available from www.hyphy.org) includes a completely re-engineered computational core and analysis library that introduces new classes of evolutionary models and statistical tests, delivers substantial performance and stability enhancements, improves usability, streamlines end-to-end analysis workflows, makes it easier", "oa": true, "pdf_url": "https://doi.org/10.1093/molbev/msz197", "local_pdf": "", "api": ""}, {"title": "Bayesian hypothesis testing for psychologists: A tutorial on the Savage–Dickey method", "doi": "https://doi.org/10.1016/j.cogpsych.2009.12.001", "year": 2010, "authors": ["Eric‐Jan Wagenmakers", "Tom Lodewyckx", "Himanshu Kuriyal", "Raoul P. P. P. Grasman"], "source": "Cognitive Psychology", "cited": 805, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0010028509000826", "local_pdf": "073_A default Bayesian hypothesis test for c.pdf", "api": ""}, {"title": "Rapid Hypothesis Testing with Candida albicans through Gene Disruption with Short Homology Regions", "doi": "https://doi.org/10.1128/jb.181.6.1868-1874.1999", "year": 1999, "authors": ["R. Bryce Wilson", "Dana A. Davis", "Aaron P. Mitchell"], "source": "Journal of Bacteriology", "cited": 769, "abstract": "Disruption of newly identified genes in the pathogen Candida albicans is a vital step in determination of gene function. Several gene disruption methods described previously employ long regions of homology flanking a selectable marker. Here, we describe disruption of C. albicans genes with PCR products that have 50 to 60 bp of homology to a genomic sequence on each end of a selectable marker. We used the method to disrupt two known genes, ARG5 and ADE2, and two sequences newly identified through the Candida genome project, HRM101 and ENX3. HRM101 and ENX3 are homologous to genes in the conserved RIM101 (previously called RIM1) and PacC pathways of Saccharomyces cerevisiae and Aspergillus nidulans. We show that three independent hrm101/hrm101 mutants and two independent enx3/enx3 mutants ar", "oa": true, "pdf_url": "https://doi.org/10.1128/jb.181.6.1868-1874.1999", "local_pdf": "", "api": ""}, {"title": "Simple methods for testing the molecular evolutionary clock hypothesis.", "doi": "10.1093/genetics/135.2.599", "year": 1993, "authors": ["F Tajima"], "source": "Genetics", "cited": 766, "abstract": "【Abstract】\n                   Simple statistical methods for testing the molecular evolutionary clock hypothesis are developed which can be applied to both nucleotide and amino acid sequences. These methods are based on the chi-square test and are applicable even when the pattern of substitution rates is unknown and/or the substitution rate varies among different sites. Furthermore, some of the methods can be applied even when the outgroup is unknown. Using computer simulations, these methods were compared with the likelihood ratio test and the relative rate test. The results indicate that the powers of the present methods are similar to those of the likelihood ratio test and the relative rate test, in spite of the fact that the latter two tests assume that the pattern of substitution rate", "oa": true, "pdf_url": "http://academic.oup.com/genetics/article-pdf/135/2/599/34593395/genetics0599.pdf", "local_pdf": "", "api": "crossref"}, {"title": "Counterfactuals and Hypothesis Testing in Political Science", "doi": "https://doi.org/10.2307/2010470", "year": 1991, "authors": ["James D. Fearon"], "source": "World Politics", "cited": 729, "abstract": "Scholars in comparative politics and international relations routinely evaluate causal hypotheses by referring tocounterfactual caseswhere a hypothesized causal factor is supposed to have been absent. The methodological status and the viability of this very common procedure are unclear and are worth examining. How does the strategy of counterfactual argument relate, if at all, to methods of hypothesis testing based on the comparison of actual cases, such as regression analysis or Mill's Method of Difference? Are counterfactual thought experiments a viable means of assessing hypotheses about national and international outcomes, or are they methodologically invalid in principle? The paper addresses the first question in some detail and begins discussion of the second. Examples from work on t", "oa": true, "pdf_url": "https://doi.org/10.2307/2010470", "local_pdf": "", "api": ""}, {"title": "Determination of absolute structure using Bayesian statistics on Bijvoet differences", "doi": "https://doi.org/10.1107/s0021889807059870", "year": 2008, "authors": ["Rob Hooft", "L. Straver", "Anthony L. Spek"], "source": "Journal of Applied Crystallography", "cited": 725, "abstract": "A new probabilistic approach is introduced for the determination of the absolute structure of a compound which is known to be enantiopure based on Bijvoet-pair intensity differences. The new method provides relative probabilities for different models of the chiral composition of the structure. The outcome of this type of analysis can also be cast in the form of a new value, along with associated standard uncertainty, that resembles the value of the well known Flack x parameter. The standard uncertainty we obtain is often about half of the standard uncertainty in the value of the Flack x parameter. The proposed formalism is suited in particular to absolute configuration determination from diffraction data of biologically active (pharmaceutical) compounds where the strongest resonant scatter", "oa": true, "pdf_url": "http://journals.iucr.org/j/issues/2008/01/00/ks5161/ks5161.pdf", "local_pdf": "", "api": ""}, {"title": "Martingale Central Limit Theorems", "doi": "https://doi.org/10.1214/aoms/1177693494", "year": 1971, "authors": ["B. M. Brown"], "source": "The Annals of Mathematical Statistics", "cited": 719, "abstract": "The classical Lindeberg-Feller CLT for sums of independent random variables (rv's) provides more than the convergence in distribution of the sum to a normal law. The independence of summands also guarantees the weak convergence of all finite dimensional distributions of an a.e. sample continuous stochastic process (suitably defined in terms of the partial sums) to those of a Gaussian process with independent increments, namely, the Wiener process. Moreover, the distributions of said process converge weakly to Wiener measure on $C\\lbrack 0, 1\\rbrack$, the latter result being known as an invariance principle, or functional CLT, an idea originating with Erdos and Kac [10] and Donsker [5], then developed by Billingsley, Prohorov, Skorohod and others. The present work contains an invariance pri", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-42/issue-1/Martingale-Central-Limit-Theorems/10.1214/aoms/1177693494.pdf", "local_pdf": "", "api": ""}, {"title": "Using Bayes factor hypothesis testing in neuroscience to establish evidence of absence", "doi": "https://doi.org/10.1038/s41593-020-0660-4", "year": 2020, "authors": ["Christian Keysers", "Valeria Gazzola", "Eric‐Jan Wagenmakers"], "source": "Nature Neuroscience", "cited": 718, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1038/s41593-020-0660-4", "local_pdf": "", "api": ""}, {"title": "Convergence of Random Processes and Limit Theorems in Probability Theory", "doi": "10.1137/1101016", "year": 1956, "authors": ["Yu. V. Prokhorov"], "source": "Theory of Probability &amp; Its Applications", "cited": 707, "abstract": " The convergence of stochastic processes is defined in terms of the so-called “weak convergence” (w. c.) of probability measures in appropriate functional spaces (c. s. m. s.). \n                   Chapter 1. Let $\\Re $ be the c.s.m.s. and v a set of all finite measures on $\\Re $. The distance $L(\\mu _1 ,\\mu _2 )$ (that is analogous to the Lévy distance) is introduced, and equivalence of L-convergence and w. c. is proved. It is shown that $V\\Re = (v,L)$ is c. s. m. s. Then, the necessary and sufficient conditions for compactness in $V\\Re $ are given. \n                   In section 1.6 the concept of “characteristic functionals” is applied to the study of w. cc of measures in Hilbert space. \n                   Chapter 2. On the basis of the above results the necessary and sufficient compactn", "oa": false, "pdf_url": "", "local_pdf": "", "api": "crossref"}, {"title": "[On the Application of Probability Theory to Agricultural Experiments. Essay on Principles. Section 9.] Comment: Neyman (1923) and Causal Inference in Experiments and Observational Studies", "doi": "https://doi.org/10.1214/ss/1177012032", "year": 1990, "authors": ["Donald B. Rubin"], "source": "Statistical Science", "cited": 663, "abstract": "", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-5/issue-4/On-the-Application-of-Probability-Theory-to-Agricultural-Experiments-Essay/10.1214/ss/1177012032.pdf", "local_pdf": "", "api": ""}, {"title": "Philosophy and the practice of Bayesian statistics", "doi": "https://doi.org/10.1111/j.2044-8317.2011.02037.x", "year": 2012, "authors": ["Andrew Gelman", "Cosma Rohilla Shalizi"], "source": "British Journal of Mathematical and Statistical Psychology", "cited": 624, "abstract": "A substantial school in the philosophy of science identifies Bayesian inference with inductive inference and even rationality as such, and seems to be strengthened by the rise and practical success of Bayesian statistics. We argue that the most successful forms of Bayesian statistics do not actually support that particular philosophy but rather accord much better with sophisticated forms of hypothetico-deductivism. We examine the actual role played by prior distributions in Bayesian models, and the crucial aspects of model checking and model revision, which fall outside the scope of Bayesian confirmation theory. We draw on the literature on the consistency of Bayesian updating and also on our experience of applied work in social science. Clarity about these matters should benefit not just ", "oa": true, "pdf_url": "https://doi.org/10.1111/j.2044-8317.2011.02037.x", "local_pdf": "", "api": ""}, {"title": "Non-central limit theorems for non-linear functional of Gaussian fields", "doi": "https://doi.org/10.1007/bf00535673", "year": 1979, "authors": ["R. L. Dobrushin", "Péter Major"], "source": "Probability Theory and Related Fields", "cited": 618, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF00535673.pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "Graph Theory and Probability", "doi": "https://doi.org/10.4153/cjm-1959-003-9", "year": 1959, "authors": ["Paul Erdős"], "source": "Canadian Journal of Mathematics", "cited": 602, "abstract": "A well-known theorem of Ramsay (8; 9) states that to every n there exists a smallest integer g(n) so that every graph of g(n) vertices contains either a set of n independent points or a complete graph of order n , but there exists a graph of g(n) — 1 vertices which does not contain a complete subgraph of n vertices and also does not contain a set of n independent points. (A graph is called complete if every two of its vertices are connected by an edge; a set of points is called independent if no two of its points are connected by an edge.) The determination of g(n) seems a very difficult problem; the best inequalities for g(n) are (3) It is not even known that g(n) 1/n tends to a limit. The lower bound in (1) has been obtained by combinatorial and probabilistic arguments without an explici", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/154EF813293BC7D0652C4CBCD9D18E84/S0008414X00002947a.pdf/div-class-title-graph-theory-and-probability-div.pdf", "local_pdf": "068_Graph Theory and Probability.pdf", "api": ""}, {"title": "Equivalence of distance-based and RKHS-based statistics in hypothesis testing", "doi": "https://doi.org/10.1214/13-aos1140", "year": 2013, "authors": ["Dino Sejdinović", "Bharath K. Sriperumbudur", "Arthur Gretton", "Kenji Fukumizu"], "source": "The Annals of Statistics", "cited": 602, "abstract": "We provide a unifying framework linking two classes of statistics used in two-sample and independence testing: on the one hand, the energy distances and distance covariances from the statistics literature; on the other, maximum mean discrepancies (MMD), that is, distances between embeddings of distributions to reproducing kernel Hilbert spaces (RKHS), as established in machine learning. In the case where the energy distance is computed with a semimetric of negative type, a positive definite kernel, termed distance kernel, may be defined such that the MMD corresponds exactly to the energy distance. Conversely, for any positive definite kernel, we can interpret the MMD as energy distance with respect to some negative-type semimetric. This equivalence readily extends to distance covariance us", "oa": true, "pdf_url": "https://doi.org/10.1214/13-aos1140", "local_pdf": "", "api": ""}, {"title": "Dependent Central Limit Theorems and Invariance Principles", "doi": "https://doi.org/10.1214/aop/1176996608", "year": 1974, "authors": ["D. L. McLeish"], "source": "The Annals of Probability", "cited": 598, "abstract": "Central limit theorems are proved for martingales and near-martingales without the existence of moments or the full Lindeberg condition. These theorems are extended to invariance principles with a discussion of both random and nonrandom norming.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-2/issue-4/Dependent-Central-Limit-Theorems-and-Invariance-Principles/10.1214/aop/1176996608.pdf", "local_pdf": "", "api": ""}, {"title": "Quantum theory of probability and decisions", "doi": "https://doi.org/10.1098/rspa.1999.0443", "year": 1999, "authors": ["David Deutsch"], "source": "Proceedings of the Royal Society A Mathematical Physical and Engineering Sciences", "cited": 587, "abstract": "The probabilistic predictions of quantum theory are conventionally obtained from a special probabilistic axiom. But that is unnecessary because all the practical consequences of such predictions follow from the remaining non–probabilistic axioms of quantum theory, together with the non–probabilistic part of classical decision theory.", "oa": true, "pdf_url": "https://doi.org/10.1098/rspa.1999.0443", "local_pdf": "", "api": ""}, {"title": "Central Limit Theorems for Empirical Measures", "doi": "https://doi.org/10.1214/aop/1176995384", "year": 1978, "authors": ["R. M. Dudley"], "source": "The Annals of Probability", "cited": 584, "abstract": "Let $(X, \\mathscr{A}, P)$ be a probability space. Let $X_1, X_2,\\cdots,$ be independent $X$-valued random variables with distribution $P$. Let $P_n := n^{-1}(\\delta_{X_1} + \\cdots + \\delta_{X_n})$ be the empirical measure and let $\\nu_n := n^\\frac{1}{2}(P_n - P)$. Given a class $\\mathscr{C} \\subset \\mathscr{a}$, we study the convergence in law of $\\nu_n$, as a stochastic process indexed by $\\mathscr{C}$, to a certain Gaussian process indexed by $\\mathscr{C}$. If convergence holds with respect to the supremum norm $\\sup_{C \\in \\mathscr{C}}|f(C)|$, in a suitable (usually nonseparable) function space, we call $\\mathscr{C}$ a Donsker class. For measurability, $X$ may be a complete separable metric space, $\\mathscr{a} =$ Borel sets, and $\\mathscr{C}$ a suitable collection of closed sets or open", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-6/issue-6/Central-Limit-Theorems-for-Empirical-Measures/10.1214/aop/1176995384.pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "A default Bayesian hypothesis test for correlations and partial correlations", "doi": "https://doi.org/10.3758/s13423-012-0295-x", "year": 2012, "authors": ["Ruud Wetzels", "Eric‐Jan Wagenmakers"], "source": "Psychonomic Bulletin & Review", "cited": 550, "abstract": "We propose a default Bayesian hypothesis test for the presence of a correlation or a partial correlation. The test is a direct application of Bayesian techniques for variable selection in regression models. The test is easy to apply and yields practical advantages that the standard frequentist tests lack; in particular, the Bayesian test can quantify evidence in favor of the null hypothesis and allows researchers to monitor the test results as the data come in. We illustrate the use of the Bayesian correlation test with three examples from the psychological literature. Computer code and example data are provided in the journal archives.", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758%2Fs13423-012-0295-x.pdf", "local_pdf": "073_A default Bayesian hypothesis test for c.pdf", "api": ""}, {"title": "Central limit theorem for integrated square error of multivariate nonparametric density estimators", "doi": "https://doi.org/10.1016/0047-259x(84)90044-7", "year": 1984, "authors": ["Peter Hall"], "source": "Journal of Multivariate Analysis", "cited": 481, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/0047259X84900447/pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "Improving transparency and replication in Bayesian statistics: The WAMBS-Checklist.", "doi": "https://doi.org/10.1037/met0000065", "year": 2015, "authors": ["Sarah Depaoli", "Rens van de Schoot"], "source": "Psychological Methods", "cited": 460, "abstract": "Bayesian statistical methods are slowly creeping into all fields of science and are becoming ever more popular in applied research. Although it is very attractive to use Bayesian statistics, our personal experience has led us to believe that naively applying Bayesian methods can be dangerous for at least 3 main reasons: the potential influence of priors, misinterpretation of Bayesian features and results, and improper reporting of Bayesian results. To deal with these 3 points of potential danger, we have developed a succinct checklist: the WAMBS-checklist (When to worry and how to Avoid the Misuse of Bayesian Statistics). The purpose of the questionnaire is to describe 10 main points that should be thoroughly checked when applying Bayesian analysis. We provide an account of \"when to worry\"", "oa": true, "pdf_url": "https://doi.org/10.1037/met0000065", "local_pdf": "", "api": ""}, {"title": "Central limit theorems for sequences of multiple stochastic integrals", "doi": "https://doi.org/10.1214/009117904000000621", "year": 2005, "authors": ["David Nualart", "Giovanni Peccati"], "source": "The Annals of Probability", "cited": 459, "abstract": "We characterize the convergence in distribution to a standard normal law for a sequence of multiple stochastic integrals of a fixed order with variance converging to 1. Some applications are given, in particular to study the limiting behavior of quadratic functionals of Gaussian processes.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-33/issue-1/Central-limit-theorems-for-sequences-of-multiple-stochastic-integrals/10.1214/009117904000000621.pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "Risk aversion in the theory of expected utility with rank dependent probabilities", "doi": "https://doi.org/10.1016/0022-0531(87)90093-7", "year": 1987, "authors": ["Chew Soo Hong", "Edi Karni", "Zvi Safra"], "source": "Journal of Economic Theory", "cited": 448, "abstract": "Expected utility with rank dependent probability theory is a model of decision-making under risk where the preference relations on the set of probability distributions is represented by the mathematical expectation of a utility function with respect to a transformation of the probability distributions on the set of outcomes. This paper defines, based on Gâteaux differentiability, measures of risk aversion for such preferences which characterize the relation “more risk averse” and applies these measures to the analysis of unconditional and conditional portfolio choice problems.", "oa": true, "pdf_url": "https://doi.org/10.1016/0022-0531(87)90093-7", "local_pdf": "", "api": ""}, {"title": "Missing Point Estimation in Models Described by Proper Orthogonal Decomposition", "doi": "https://doi.org/10.1109/tac.2008.2006102", "year": 2008, "authors": ["P. Astrid", "S. Weiland", "Karen Willcox", "Ton Backx"], "source": "IEEE Transactions on Automatic Control", "cited": 445, "abstract": "This paper presents a new method of missing point estimation (MPE) to derive efficient reduced-order models for large-scale parameter-varying systems. Such systems often result from the discretization of nonlinear partial differential equations. A projection-based model reduction framework is used where projection spaces are inferred from proper orthogonal decompositions of data-dependent correlation operators. The key contribution of the MPE method is to perform online computations efficiently by computing Galerkin projections over a restricted subset of the spatial domain. Quantitative criteria for optimally selecting such a spatial subset are proposed and the resulting optimization problem is solved using an efficient heuristic method. The effectiveness of the MPE method is demonstrated", "oa": true, "pdf_url": "https://doi.org/10.1109/tac.2008.2006102", "local_pdf": "", "api": ""}, {"title": "Change-point detection in time-series data by relative density-ratio estimation", "doi": "https://doi.org/10.1016/j.neunet.2013.01.012", "year": 2013, "authors": ["Song Liu", "Makoto Yamada", "Nigel Collier", "Masashi Sugiyama"], "source": "Neural Networks", "cited": 445, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.neunet.2013.01.012", "local_pdf": "", "api": ""}, {"title": "Surrogate data for hypothesis testing of physical systems", "doi": "https://doi.org/10.1016/j.physrep.2018.06.001", "year": 2018, "authors": ["Gemma Lancaster", "Dmytro Iatsenko", "Aleksandra Pidde", "Valentina Ticcinelli", "Aneta Stefanovska"], "source": "Physics Reports", "cited": 444, "abstract": "The availability of time series of the evolution of the properties of physical systems is increasing, stimulating the development of many novel methods for the extraction of information about their behaviour over time, including whether or not they arise from deterministic or stochastic dynamical systems. Surrogate data testing is an essential part of many of these methods, as it enables robust statistical evaluations to ensure that the results observed are not obtained by chance, but are a true characteristic of the underlying system. The surrogate data technique is based on the comparison of a particular property of the data (a discriminating statistic) with the distribution of the same property calculated in a set of constructed signals (surrogates) which match the original data set but", "oa": true, "pdf_url": "https://doi.org/10.1016/j.physrep.2018.06.001", "local_pdf": "", "api": ""}, {"title": "Central limit theorem for sequential Monte Carlo methods and its application to Bayesian inference", "doi": "https://doi.org/10.1214/009053604000000698", "year": 2004, "authors": ["Nicolas Chopin"], "source": "The Annals of Statistics", "cited": 443, "abstract": "The term “sequential Monte Carlo methods” or, equivalently, “particle filters,” refers to a general class of iterative algorithms that performs Monte Carlo approximations of a given sequence of distributions of interest (πt). We establish in this paper a central limit theorem for the Monte Carlo estimates produced by these computational methods. This result holds under minimal assumptions on the distributions πt, and applies in a general framework which encompasses most of the sequential Monte Carlo methods that have been considered in the literature, including the resample-move algorithm of Gilks and Berzuini [J. R. Stat. Soc. Ser. B Stat. Methodol. 63 (2001) 127–146] and the residual resampling scheme. The corresponding asymptotic variances provide a convenient measurement of the precisi", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-32/issue-6/Central-limit-theorem-for-sequential-Monte-Carlo-methods-and-its/10.1214/009053604000000698.pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}, {"title": "Optimal Inequalities in Probability Theory: A Convex Optimization Approach", "doi": "https://doi.org/10.1137/s1052623401399903", "year": 2005, "authors": ["Dimitris Bertsimas", "Ioana Popescu"], "source": "SIAM Journal on Optimization", "cited": 438, "abstract": "We propose a semidefinite optimization approach to the problem of deriving tight moment inequalities for $P(X\\in S)$, for a set S defined by polynomial inequalities and a random vector X defined on $\\Omega\\subseteq {\\cal R}^n$ that has a given collection of up to kth-order moments. In the univariate case, we provide optimal bounds on $P(X\\in S)$, when the first k moments of X are given, as the solution of a semidefinite optimization problem in k + 1 dimensions. In the multivariate case, if the sets S and $\\Omega$ are given by polynomial inequalities, we obtain an improving sequence of bounds by solving semidefinite optimization problems of polynomial size in n, for fixed k. We characterize the complexity of the problem of deriving tight moment inequalities. We show that it is NP-hard to fi", "oa": true, "pdf_url": "https://doi.org/10.1137/s1052623401399903", "local_pdf": "", "api": ""}, {"title": "Advanced Statistics: Bootstrapping Confidence Intervals for Statistics with “Difficult” Distributions", "doi": "https://doi.org/10.1197/j.aem.2004.11.018", "year": 2005, "authors": ["Jason S. Haukoos", "Roger Lewis"], "source": "Academic Emergency Medicine", "cited": 437, "abstract": "The use of confidence intervals in reporting results of research has increased dramatically and is now required or highly recommended by editors of many scientific journals. Many resources describe methods for computing confidence intervals for statistics with mathematically simple distributions. Computing confidence intervals for descriptive statistics with distributions that are difficult to represent mathematically is more challenging. The bootstrap is a computationally intensive statistical technique that allows the researcher to make inferences from data without making strong distributional assumptions about the data or the statistic being calculated. This allows the researcher to estimate confidence intervals for statistics that do not have simple sampling distributions (e.g., the me", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1197/j.aem.2004.11.018", "local_pdf": "", "api": ""}, {"title": "Hypothesis testing, type I and type II errors", "doi": "https://doi.org/10.4103/0972-6748.62274", "year": 2009, "authors": ["Banerjee Ak", "UB Chitnis", "Sudhir Jadhav", "JS Bhawalkar", "Suprakash Chaudhury"], "source": "Industrial Psychiatry Journal", "cited": 437, "abstract": "Hypothesis testing is an important activity of empirical research and evidence-based medicine. A well worked up hypothesis is half the answer to the research question. For this, both knowledge of the subject derived from extensive review of the literature and working knowledge of basic statistical concepts are desirable. The present paper discusses the methods of working up a good hypothesis and statistical concepts of hypothesis testing.", "oa": true, "pdf_url": "https://doi.org/10.4103/0972-6748.62274", "local_pdf": "073_A default Bayesian hypothesis test for c.pdf", "api": ""}, {"title": "Attention and Conscious Perception in the Hypothesis Testing Brain", "doi": "https://doi.org/10.3389/fpsyg.2012.00096", "year": 2012, "authors": ["Jakob Hohwy"], "source": "Frontiers in Psychology", "cited": 426, "abstract": "Conscious perception and attention are difficult to study, partly because their relation to each other is not fully understood. Rather than conceiving and studying them in isolation from each other it may be useful to locate them in an independently motivated, general framework, from which a principled account of how they relate can then emerge. Accordingly, these mental phenomena are here reviewed through the prism of the increasingly influential predictive coding framework. On this framework, conscious perception can be seen as the upshot of prediction error minimization and attention as the optimization of precision expectations during such perceptual inference. This approach maps on well to a range of standard characteristics of conscious perception and attention, and can be used to in", "oa": true, "pdf_url": "https://www.frontiersin.org/articles/10.3389/fpsyg.2012.00096/pdf", "local_pdf": "085_Attention and Conscious Perception in th.pdf", "api": ""}, {"title": "A Modern Approach to Probability Theory", "doi": "https://doi.org/10.1007/978-1-4899-2837-5", "year": 1997, "authors": ["Bert Fristedt", "Lawrence Gray"], "source": "Birkhäuser Boston eBooks", "cited": 403, "abstract": "Overview This book is intended as a textbook in probability for graduate students in math ematics and related areas such as statistics, economics, physics, and operations research. Probability theory", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/978-1-4899-2837-5.pdf", "local_pdf": "", "api": ""}, {"title": "Entropy and the Central Limit Theorem", "doi": "https://doi.org/10.1214/aop/1176992632", "year": 1986, "authors": ["Andrew R. Barron"], "source": "The Annals of Probability", "cited": 375, "abstract": "A strengthened central limit theorem for densities is established showing monotone convergence in the sense of relative entropy.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-14/issue-1/Entropy-and-the-Central-Limit-Theorem/10.1214/aop/1176992632.pdf", "local_pdf": "", "api": ""}, {"title": "On the Markov chain central limit theorem", "doi": "https://doi.org/10.1214/154957804100000051", "year": 2004, "authors": ["Galin L. Jones"], "source": "Probability Surveys", "cited": 375, "abstract": "The goal of this expository paper is to describe conditions which guarantee a central limit theorem for functionals of general state space Markov chains. This is done with a view towards Markov chain Monte Carlo settings and hence the focus is on the connections between drift and mixing conditions and their implications. In particular, we consider three commonly cited central limit theorems and discuss their relationship to classical results for mixing processes. Several motivating examples are given which range from toy one-dimensional settings to complicated settings encountered in Markov chain Monte Carlo.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/probability-surveys/volume-1/issue-none/On-the-Markov-chain-central-limit-theorem/10.1214/154957804100000051.pdf", "local_pdf": "", "api": ""}, {"title": "A central limit theorem for generalized quadratic forms", "doi": "https://doi.org/10.1007/bf00354037", "year": 1987, "authors": ["Peter de Jong"], "source": "Probability Theory and Related Fields", "cited": 372, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF00354037.pdf", "local_pdf": "089_A central limit theorem for generalized .pdf", "api": ""}, {"title": "An Introduction to Bayesian Hypothesis Testing for Management Research", "doi": "https://doi.org/10.1177/0149206314560412", "year": 2014, "authors": ["Sandra Andraszewicz", "Benjamin Scheibehenne", "Jörg Rieskamp", "Raoul P. P. P. Grasman", "Josine Verhagen", "Eric‐Jan Wagenmakers"], "source": "Journal of Management", "cited": 370, "abstract": "In management research, empirical data are often analyzed using p-value null hypothesis significance testing (pNHST). Here we outline the conceptual and practical advantages of an alternative analysis method: Bayesian hypothesis testing and model selection using the Bayes factor. In contrast to pNHST, Bayes factors allow researchers to quantify evidence in favor of the null hypothesis. Also, Bayes factors do not require adjustment for the intention with which the data were collected. The use of Bayes factors is demonstrated through an extended example for hierarchical regression based on the design of an experiment recently published in the Journal of Management. This example also highlights the fact that p values overestimate the evidence against the null hypothesis, misleading researcher", "oa": true, "pdf_url": "https://doi.org/10.1177/0149206314560412", "local_pdf": "", "api": ""}, {"title": "Information theory and hypothesis testing: a call for pluralism", "doi": "https://doi.org/10.1111/j.1365-2664.2005.01002.x", "year": 2005, "authors": ["Philip A. Stephens", "Steven W. Buskirk", "Gregory D. Hayward", "Carlos Martı́nez del Rio"], "source": "Journal of Applied Ecology", "cited": 365, "abstract": "Summary A major paradigm shift is occurring in the approach of ecologists to statistical analysis. The use of the traditional approach of null‐hypothesis testing has been questioned and an alternative, model selection by information–theoretic methods, has been strongly promoted and is now widely used. For certain types of analysis, information–theoretic approaches offer powerful and compelling advantages over null‐hypothesis testing. The benefits of information–theoretic methods are often framed as criticisms of null‐hypothesis testing. We argue that many of these criticisms are neither irremediable nor always fair. Many are criticisms of the paradigm's application, rather than of its formulation. Information–theoretic methods are equally vulnerable to many such misuses. Care must be taken", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1365-2664.2005.01002.x", "local_pdf": "", "api": ""}, {"title": "A central limit theorem for quadratic forms in strongly dependent linear variables and its application to asymptotical normality of Whittle's estimate", "doi": "https://doi.org/10.1007/bf01207515", "year": 1990, "authors": ["Liudas Giraitis", "Донатас Сургайлис"], "source": "Probability Theory and Related Fields", "cited": 344, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF01207515.pdf", "local_pdf": "092_A central limit theorem for quadratic fo.pdf", "api": ""}, {"title": "Break Point Estimation and Spurious Rejections With Endogenous Unit Root Tests", "doi": "https://doi.org/10.1111/1468-0084.00234", "year": 2001, "authors": ["Junsoo Lee", "Mark C. Strazicich"], "source": "Oxford Bulletin of Economics and Statistics", "cited": 332, "abstract": "This paper examines the accuracy of break point estimation using the endogenous break unit root tests of Zivot and Andrews (1992) and Perron (1997). We find that these tests tend to identify the break point incorrectly at one‐period behind (TB‐1) the true break point (TB), where bias in estimating the persistence parameter and spurious rejections are the greatest. In addition, this outcome occurs under the null and alternative hypotheses, and more so as the magnitude of the break increases. Consequences of utilizing these endogenous break tests are similar to (incorrectly) omitting the break term Bt in Perron's (1989) exogenous test.", "oa": true, "pdf_url": "https://doi.org/10.1111/1468-0084.00234", "local_pdf": "", "api": ""}, {"title": "Chi-square test and its application in hypothesis testing", "doi": "https://doi.org/10.4103/2395-5414.157577", "year": 2015, "authors": ["Richa Singhal", "Rakesh Rana"], "source": "Journal of the Practice of Cardiovascular Sciences", "cited": 314, "abstract": "In medical research, there are studies which often collect data on categorical variables that can be summarized as a series of counts. These counts are commonly arranged in a tabular format known as a contingency table. The chi-square test statistic can be used to evaluate whether there is an association between the rows and columns in a contingency table. More specifically, this statistic can be used to determine whether there is any difference between the study groups in the proportions of the risk factor of interest. Chi-square test and the logic of hypothesis testing were developed by Karl Pearson. This article describes in detail what is a chi-square test, on which type of data it is used, the assumptions associated with its application, how to manually calculate it and how to make us", "oa": true, "pdf_url": "https://doi.org/10.4103/2395-5414.157577", "local_pdf": "", "api": ""}, {"title": "The Law of Large Numbers and the Central Limit Theorem in Banach Spaces", "doi": "https://doi.org/10.1214/aop/1176996029", "year": 1976, "authors": ["J. Hoffmann-Jørgensen", "Gilles Pisier"], "source": "The Annals of Probability", "cited": 312, "abstract": "Let $X_1, X_2, \\cdots$ be independent random variables with values in a Banach space $E$. It is then shown that Chung's version of the strong law of large numbers holds, if and only if $E$ is of type $p$. If the $X_n$'s are identically distributed, then it is shown that the central limit theorem is valid, if and only if $E$ is of type 2. Similar results are obtained for vectorvalued martingales.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-4/issue-4/The-Law-of-Large-Numbers-and-the-Central-Limit-Theorem/10.1214/aop/1176996029.pdf", "local_pdf": "", "api": ""}, {"title": "On the Central Limit Theorem for Stationary Mixing Random Fields", "doi": "https://doi.org/10.1214/aop/1176993726", "year": 1982, "authors": ["Erwin Bolthausen"], "source": "The Annals of Probability", "cited": 299, "abstract": "A simple proof of a central limit theorem for stationary random fields under mixing conditions is given, generalizing some results obtained by more complicated methods, e.g. Bernstein's method.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-10/issue-4/On-the-Central-Limit-Theorem-for-Stationary-Mixing-Random-Fields/10.1214/aop/1176993726.pdf", "local_pdf": "", "api": ""}, {"title": "Objections to Bayesian statistics", "doi": "https://doi.org/10.1214/08-ba318", "year": 2008, "authors": ["Andrew Gelman"], "source": "Bayesian Analysis", "cited": 284, "abstract": "Bayesian inference is one of the more controversial approaches to statistics. The fundamental objections to Bayesian methods are twofold: on one hand, Bayesian methods are presented as an automatic inference engine, and this raises suspicion in anyone with applied experience. The second objection to Bayes comes from the opposite direction and addresses the subjective strand of Bayesian inference. This article presents a series of objections to Bayesian inference, written in the voice of a hypothetical anti-Bayesian statistician. The article is intended to elicit elaborations and extensions of these and other arguments from non-Bayesians and responses from Bayesians who might have different perspectives on these issues.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/bayesian-analysis/volume-3/issue-3/Objections-to-Bayesian-statistics/10.1214/08-BA318.pdf", "local_pdf": "", "api": ""}, {"title": "On the Probability Theory of Linkage in Mendelian Heredity", "doi": "https://doi.org/10.1214/aoms/1177731313", "year": 1944, "authors": ["Hilda Geiringer"], "source": "The Annals of Mathematical Statistics", "cited": 283, "abstract": "", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-15/issue-1/On-the-Probability-Theory-of-Linkage-in-Mendelian-Heredity/10.1214/aoms/1177731313.pdf", "local_pdf": "", "api": ""}, {"title": "Central limit theorem for linear eigenvalue statistics of random matrices with independent entries", "doi": "https://doi.org/10.1214/09-aop452", "year": 2009, "authors": ["Anna Lytova", "L. А. Pastur"], "source": "The Annals of Probability", "cited": 274, "abstract": "We consider n×n real symmetric and Hermitian Wigner random matrices n−1/2W with independent (modulo symmetry condition) entries and the (null) sample covariance matrices n−1X*X with independent entries of m×n matrix X. Assuming first that the 4th cumulant (excess) κ4 of entries of W and X is zero and that their 4th moments satisfy a Lindeberg type condition, we prove that linear statistics of eigenvalues of the above matrices satisfy the central limit theorem (CLT) as n→∞, m→∞, m/n→c∈[0, ∞) with the same variance as for Gaussian matrices if the test functions of statistics are smooth enough (essentially of the class C5). This is done by using a simple “interpolation trick” from the known results for the Gaussian matrices and the integration by parts, presented in the form of certain differ", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-37/issue-5/Central-limit-theorem-for-linear-eigenvalue-statistics-of-random-matrices/10.1214/09-AOP452.pdf", "local_pdf": "067_Non-central limit theorems for non-linea.pdf", "api": ""}]}, "regression_analysis": {"cn": "回归分析", "items": [{"title": "Fitting Linear Mixed-Effects Models Using lme4", "doi": "https://doi.org/10.18637/jss.v067.i01", "year": 2015, "authors": ["Douglas M. Bates", "Martin Mächler", "Benjamin M. Bolker", "Steve Walker"], "source": "Journal of Statistical Software", "cited": 88651, "abstract": "Maximum likelihood or restricted maximum likelihood (REML) estimates of the parameters in linear mixed-effects models can be determined using the lmer function in the lme4 package for R. As for most model-fitting functions in R, the model is described in an lmer call by a formula, in this case including both fixed- and random-effects terms. The formula and data together determine a numerical representation of the model from which the profiled deviance or the profiled REML criterion can be evaluated as a function of some of the model parameters. The appropriate criterion is optimized, using one of the constrained optimization functions in R, to provide the parameter estimates. We describe the structure of the model, the steps in evaluating the profiled deviance or REML criterion, and the st", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v067i01/v67i01.pdf", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "Exploiting Generative AI to Scale up Intelligent Tutoring Systems", "doi": "https://doi.org/10.4230/lipics.itp.2023.19", "year": 2023, "authors": ["Jakubův, Jan", "Chvalovský, Karel", "Goertzel, Zarathustra", "Kaliszyk, Cezary", "Olšák, Mirek", "Piotrowski, Bartosz"], "source": "DROPS (Schloss Dagstuhl – Leibniz Center for Informatics)", "cited": 79058, "abstract": "As a present to Mizar on its 50th anniversary, we develop an AI/TP system that automatically proves about 60% of the Mizar theorems in the hammer setting. We also automatically prove 75% of the Mizar theorems when the automated provers are helped by using only the premises used in the human-written Mizar proofs. We describe the methods and large-scale experiments leading to these results. This includes in particular the E and Vampire provers, their ENIGMA and Deepire learning modifications, a number of learning-based premise selection methods, and the incremental loop that interleaves growing a corpus of millions of ATP proofs with training increasingly strong AI/TP systems on them. We also present a selection of Mizar problems that were proved automatically.", "oa": true, "pdf_url": "https://drops.dagstuhl.de/storage/00lipics/lipics-vol268-itp2023/LIPIcs.ITP.2023.19/LIPIcs.ITP.2023.19.pdf", "local_pdf": "001_Exploiting Generative AI to Scale up Int.pdf", "api": ""}, {"title": "Introduction to Mediation, Moderation, and Conditional Process Analysis: A Regression-Based Approach", "doi": null, "year": 2013, "authors": ["Andrew F. Hayes"], "source": "", "cited": 45149, "abstract": "I. FUNDAMENTAL CONCEPTS 1. Introduction 1.1. A Scientist in Training 1.2. Questions of Whether, If, How, and When 1.3. Conditional Process Analysis 1.4. Correlation, Causality, and Statistical Modeling 1.5. Statistical Software 1.6. Overview of this Book 1.7. Chapter Summary 2. Simple Linear Regression 2.1. Correlation and Prediction 2.2. The Simple Linear Regression Equation 2.3. Statistical Inference 2.4. Assumptions for Interpretation and Statistical Inference 2.5. Chapter Summary 3. Multiple Linear Regression 3.1. The Multiple Linear Regression Equation 3.2. Partial Association and Statistical Control 3.3. Statistical Inference in Multiple Regression 3.4. Statistical and Conceptual Diagrams 3.5. Chapter Summary II. MEDIATION ANALYSIS 4. The Simple Mediation Model 4.1. The Simple Mediat", "oa": true, "pdf_url": "http://bvbr.bib-bvb.de:8991/F?func=service&amp;doc_library=BVB01&amp;local_base=BVB01&amp;doc_number=025778167&amp;sequence=000004&amp;line_number=0002&amp;func_code=DB_RECORDS&amp;service_type=MEDIA", "local_pdf": "", "api": ""}, {"title": "Statistical power analyses using G*Power 3.1: Tests for correlation and regression analyses", "doi": "https://doi.org/10.3758/brm.41.4.1149", "year": 2009, "authors": ["Franz Faul", "Edgar Erdfelder", "Axel Buchner", "Albert-Georg Lang"], "source": "Behavior Research Methods", "cited": 37461, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/BRM.41.4.1149.pdf", "local_pdf": "003_Statistical power analyses using G_Power.pdf", "api": ""}, {"title": "lmerTest Package: Tests in Linear Mixed Effects Models", "doi": "https://doi.org/10.18637/jss.v082.i13", "year": 2017, "authors": ["Alexandra Kuznetsova", "Per B. Brockhoff", "Rune Haubo Bojesen Christensen"], "source": "Journal of Statistical Software", "cited": 24483, "abstract": "One of the frequent questions by users of the mixed model function lmer of the lme4 package has been: How can I get p values for the F and t tests for objects returned by lmer? The lmerTest package extends the 'lmerMod' class of the lme4 package, by overloading the anova and summary functions by providing p values for tests for fixed effects. We have implemented the Satterthwaite's method for approximating degrees of freedom for the t and F tests. We have also implemented the construction of Type I - III ANOVA tables. Furthermore, one may also obtain the summary as well as the anova table using the Kenward-Roger approximation for denominator degrees of freedom (based on the KRmodcomp function from the pbkrtest package). Some other convenient mixed model analysis tools such as a step method", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v082i13/v82i13.pdf", "local_pdf": "004_lmerTest Package_ Tests in Linear Mixed .pdf", "api": ""}, {"title": "Regularization and Variable Selection Via the Elastic Net", "doi": "https://doi.org/10.1111/j.1467-9868.2005.00503.x", "year": 2005, "authors": ["Hui Zou", "Trevor Hastie"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 21591, "abstract": "Summary We propose the elastic net, a new regularization and variable selection method. Real world data and a simulation study show that the elastic net often outperforms the lasso, while enjoying a similar sparsity of representation. In addition, the elastic net encourages a grouping effect, where strongly correlated predictors tend to be in or out of the model together. The elastic net is particularly useful when the number of predictors (p) is much bigger than the number of observations (n). By contrast, the lasso is not a very satisfactory variable selection method in the p≫n case. An algorithm called LARS-EN is proposed for computing elastic net regularization paths efficiently, much like algorithm LARS does for the lasso.", "oa": true, "pdf_url": "https://academic.oup.com/jrsssb/article-pdf/67/2/301/49795094/jrsssb_67_2_301.pdf", "local_pdf": "085_Elastic Net Regularization Paths for All.pdf", "api": ""}, {"title": "Mixed effects models and extensions in ecology with R", "doi": "https://doi.org/10.1007/978-0-387-87458-6", "year": 2009, "authors": ["Alain F. Zuur", "Elena N. Ieno", "N. P. J. Walker", "Anatoly A. Saveliev", "Graham M. Smith"], "source": "Statistics for biology and health", "cited": 17923, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/978-0-387-87458-6", "local_pdf": "", "api": ""}, {"title": "Regularization Paths for Generalized Linear Models via Coordinate Descent", "doi": "https://doi.org/10.18637/jss.v033.i01", "year": 2010, "authors": ["Jerome H. Friedman", "Trevor Hastie", "Robert Tibshirani"], "source": "Journal of Statistical Software", "cited": 17631, "abstract": "We develop fast algorithms for estimation of generalized linear models with convex penalties. The models include linear regression, two-class logistic regression, and multi- nomial regression problems while the penalties include ℓ1 (the lasso), ℓ2 (ridge regression) and mixtures of the two (the elastic net). The algorithms use cyclical coordinate descent, computed along a regularization path. The methods can handle large problems and can also deal efficiently with sparse features. In comparative timings we find that the new algorithms are considerably faster than competing methods.", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v033.i01", "local_pdf": "085_Elastic Net Regularization Paths for All.pdf", "api": ""}, {"title": "jModelTest 2: more models, new heuristics and parallel computing", "doi": "https://doi.org/10.1038/nmeth.2109", "year": 2012, "authors": ["Diego Darriba", "Guillermo L. Taboada", "Ramón Doallo", "David Posada"], "source": "Nature Methods", "cited": 17215, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.2109.pdf", "local_pdf": "", "api": ""}, {"title": "Simultaneous Inference in General Parametric Models", "doi": "https://doi.org/10.1002/bimj.200810425", "year": 2008, "authors": ["Torsten Hothorn", "Frank Bretz", "Peter H. Westfall"], "source": "Biometrical Journal", "cited": 14229, "abstract": "Simultaneous inference is a common problem in many areas of application. If multiple null hypotheses are tested simultaneously, the probability of rejecting erroneously at least one of them increases beyond the pre-specified significance level. Simultaneous inference procedures have to be used which adjust for multiplicity and thus control the overall type I error rate. In this paper we describe simultaneous inference procedures in general parametric models, where the experimental questions are specified through a linear combination of elemental model parameters. The framework described here is quite general and extends the canonical theory of multiple comparison procedures in ANOVA models to linear regression problems, generalized linear models, linear mixed effects models, the Cox model,", "oa": true, "pdf_url": "https://doi.org/10.1002/bimj.200810425", "local_pdf": "", "api": ""}, {"title": "Regularization Paths for Generalized Linear Models via Coordinate Descent.", "doi": null, "year": 2010, "authors": ["Jerome H. Friedman", "Trevor Hastie", "Rob Tibshirani"], "source": "PubMed", "cited": 14023, "abstract": "We develop fast algorithms for estimation of generalized linear models with convex penalties. The models include linear regression, two-class logistic regression, and multinomial regression problems while the penalties include ℓ(1) (the lasso), ℓ(2) (ridge regression) and mixtures of the two (the elastic net). The algorithms use cyclical coordinate descent, computed along a regularization path. The methods can handle large problems and can also deal efficiently with sparse features. In comparative timings we find that the new algorithms are considerably faster than competing methods.", "oa": true, "pdf_url": "https://pubmed.ncbi.nlm.nih.gov/20808728", "local_pdf": "085_Elastic Net Regularization Paths for All.pdf", "api": ""}, {"title": "glmmTMB Balances Speed and Flexibility Among Packages for Zero-inflated Generalized Linear Mixed Modeling", "doi": "https://doi.org/10.32614/rj-2017-066", "year": 2017, "authors": ["Mollie,E. Brooks", "Kasper Kristensen", "Koen,J.,van Benthem", "Árni Magnússon", "Casper,W. Berg", "Anders Nielsen"], "source": "The R Journal", "cited": 13303, "abstract": "Count data can be analyzed using generalized linear mixed models when observations are correlated in ways that require random effects.However, count data are often zero-inflated, containing more zeros than would be expected from the typical error distributions.We present a new package, glmmTMB, and compare it to other R packages that fit zero-inflated mixed models.The glmmTMB package fits many types of GLMMs and extensions, including models with continuously distributed responses, but here we focus on count responses.glmmTMB is faster than glmmADMB, MCMCglmm, and brms, and more flexible than INLA and mgcv for zero-inflated modeling.One unique feature of glmmTMB (among packages that fit zero-inflated mixed models) is its ability to estimate the Conway-Maxwell-Poisson distribution parameteri", "oa": true, "pdf_url": "https://journal.r-project.org/archive/2017/RJ-2017-066/RJ-2017-066.pdf", "local_pdf": "011_glmmTMB Balances Speed and Flexibility A.pdf", "api": ""}, {"title": "Random effects structure for confirmatory hypothesis testing: Keep it maximal", "doi": "https://doi.org/10.1016/j.jml.2012.11.001", "year": 2013, "authors": ["Dale J. Barr", "Roger Lévy", "Christoph Scheepers", "Harry Tily"], "source": "Journal of Memory and Language", "cited": 10702, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jml.2012.11.001", "local_pdf": "072_Random effects structure for testing int.pdf", "api": ""}, {"title": "jModelTest: Phylogenetic Model Averaging", "doi": "https://doi.org/10.1093/molbev/msn083", "year": 2008, "authors": ["David Posada"], "source": "Molecular Biology and Evolution", "cited": 10634, "abstract": "jModelTest is a new program for the statistical selection of models of nucleotide substitution based on \"Phyml\" (Guindon and Gascuel 2003. A simple, fast, and accurate algorithm to estimate large phylogenies by maximum likelihood. Syst Biol. 52:696-704.). It implements 5 different selection strategies, including \"hierarchical and dynamical likelihood ratio tests,\" the \"Akaike information criterion,\" the \"Bayesian information criterion,\" and a \"decision-theoretic performance-based\" approach. This program also calculates the relative importance and model-averaged estimates of substitution parameters, including a model-averaged estimate of the phylogeny. jModelTest is written in Java and runs under Mac OSX, Windows, and Unix systems with a Java Runtime Environment installed. The program, incl", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/25/7/1253/3543852/msn083.pdf", "local_pdf": "", "api": ""}, {"title": "Multimodel Inference", "doi": "10.1177/0049124104268644", "year": 2004, "authors": ["Kenneth P. Burnham", "David R. Anderson"], "source": "Sociological Methods &amp; Research", "cited": 10357, "abstract": " The model selection literature has been generally poor at reflecting the deep foundations of the Akaike information criterion (AIC) and at making appropriate comparisons to the Bayesian information criterion (BIC). There is a clear philosophy, a sound criterion based in information theory, and a rigorous statistical foundation for AIC. AIC can be justified as Bayesian using a “savvy” prior on models that is a function of sample size and the number of model parameters. Furthermore, BIC can be derived as a non-Bayesian result. Therefore, arguments about using AIC versus BIC for model selection cannot be from a Bayes versus frequentist perspective. The philosophical context of what is assumed about reality, approximating models, and the intent of model-based inference should determine whethe", "oa": true, "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/0049124104268644", "local_pdf": "", "api": "crossref"}, {"title": "Partial Least Squares Structural Equation Modeling (PLS-SEM) Using R", "doi": "https://doi.org/10.1007/978-3-030-80519-7", "year": 2021, "authors": ["Joseph F. Hair", "G. Tomas M. Hult", "Christian M. Ringle", "Marko Sarstedt", "Nicholas P. Danks", "Soumya Ray"], "source": "Classroom companion: business", "cited": 9597, "abstract": "This is an open-access step-by-step guide to analyzing PLS models using R, especially using the SEMinR package and with in-depth case studies.", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007%2F978-3-030-80519-7.pdf", "local_pdf": "015_Partial Least Squares Structural Equatio.pdf", "api": ""}, {"title": "Least angle regression", "doi": "https://doi.org/10.1214/009053604000000067", "year": 2004, "authors": ["Bradley Efron", "Trevor Hastie", "Iain M. Johnstone", "Robert Tibshirani"], "source": "The Annals of Statistics", "cited": 9533, "abstract": "The purpose of model selection algorithms such as All Subsets, Forward Selection and Backward Elimination is to choose a linear model on the basis of the same set of data to which the model will be applied. Typically we have available a large collection of possible covariates from which we hope to select a parsimonious set for the efficient prediction of a response variable. Least Angle Regression (LARS), a new model selection algorithm, is a useful and less greedy version of traditional forward selection methods. Three main properties are derived: (1) A simple modification of the LARS algorithm implements the Lasso, an attractive version of ordinary least squares that constrains the sum of the absolute regression coefficients; the LARS modification calculates all possible Lasso estimates ", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-32/issue-2/Least-angle-regression/10.1214/009053604000000067.pdf", "local_pdf": "", "api": ""}, {"title": "A simulation study of the number of events per variable in logistic regression analysis", "doi": "https://doi.org/10.1016/s0895-4356(96)00236-3", "year": 1996, "authors": ["Peter Peduzzi", "John Concato", "Elizabeth Kemper", "Theodore R. Holford", "Alvan R. Feinstein"], "source": "Journal of Clinical Epidemiology", "cited": 9506, "abstract": "We performed a Monte Carlo study to evaluate the effect of the number of events per variable (EPV) analyzed in logistic regression analysis. The simulations were based on data from a cardiac trial of 673 patients in which 252 deaths occurred and seven variables were cogent predictors of mortality; the number of events per predictive variable was (252/7 =) 36 for the full sample. For the simulations, at values of EPV = 2, 5, 10, 15, 20, and 25, we randomly generated 500 samples of the 673 patients, chosen with replacement, according to a logistic model derived from the full sample. Simulation results for the regression coefficients for each variable in each group of 500 samples were compared for bias, precision, and significance testing against the results of the model fitted to the origina", "oa": true, "pdf_url": "https://doi.org/10.1016/s0895-4356(96)00236-3", "local_pdf": "", "api": ""}, {"title": "Mixed-Effects Models in S and S-PLUS", "doi": "https://doi.org/10.1198/tech.2001.s574", "year": 2001, "authors": ["Pinheiro, José C.", "Bates, Douglas M."], "source": "Technometrics", "cited": 9357, "abstract": "Mixed-effects models provide a flexible and powerful tool for the analysis of grouped data, which arise in many areas as diverse as agriculture, biology, economics, manufacturing, and geophysics.Examples of grouped data include longitudinal data, repeated measures, blocked designs, and multilevel data.The increasing popularity of mixed-effects models is explained by the flexibility they offer in modeling the within-group correlation often present in grouped data, by the handling of balanced and unbalanced data in a unified framework, and by the availability of reliable and efficient software for fitting them.This book provides an overview of the theory and application of linear and nonlinear mixed-effects models in the analysis of grouped data.A unified model-building strategy for both lin", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/abs/10.1198/tech.2001.s574", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "Structural Equation Modelling: Guidelines for Determining Model Fit", "doi": "https://doi.org/10.21427/d7cf7r", "year": 2008, "authors": ["Daire Hooper", "Joseph Coughlan", "Michael R. Mullen"], "source": "Maynooth University ePrints and eTheses Archive (Maynooth University)", "cited": 8792, "abstract": "The following paper presents current thinking and research on fit indices for structural equation modelling. The paper presents a selection of fit indices that are widely regarded as the most informative indices available to researchers. As well as outlining each of these indices, guidelines are presented on their use. The paper also provides reporting strategies of these indices and concludes with a discussion on the future of fit indices.", "oa": true, "pdf_url": "https://mural.maynoothuniversity.ie/id/eprint/6596/1/JC-Structural-Equation.pdf", "local_pdf": "019_Structural Equation Modelling_ Guideline.pdf", "api": ""}, {"title": "Mixed-effects modeling with crossed random effects for subjects and items", "doi": "https://doi.org/10.1016/j.jml.2007.12.005", "year": 2008, "authors": ["R. Harald Baayen", "Douglas Davidson", "Douglas M. Bates"], "source": "Journal of Memory and Language", "cited": 8709, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jml.2007.12.005", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "Fast Stable Restricted Maximum Likelihood and Marginal Likelihood Estimation of Semiparametric Generalized Linear Models", "doi": "https://doi.org/10.1111/j.1467-9868.2010.00749.x", "year": 2010, "authors": ["Simon N. Wood"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 7786, "abstract": "Summary Recent work by Reiss and Ogden provides a theoretical basis for sometimes preferring restricted maximum likelihood (REML) to generalized cross-validation (GCV) for smoothing parameter selection in semiparametric regression. However, existing REML or marginal likelihood (ML) based methods for semiparametric generalized linear models (GLMs) use iterative REML or ML estimation of the smoothing parameters of working linear approximations to the GLM. Such indirect schemes need not converge and fail to do so in a non-negligible proportion of practical analyses. By contrast, very reliable prediction error criteria smoothing parameter selection methods are available, based on direct optimization of GCV, or related criteria, for the GLM itself. Since such methods directly optimize properly ", "oa": true, "pdf_url": "https://academic.oup.com/jrsssb/article-pdf/73/1/3/49162718/jrsssb_73_1_3.pdf", "local_pdf": "", "api": ""}, {"title": "PartitionFinder: Combined Selection of Partitioning Schemes and Substitution Models for Phylogenetic Analyses", "doi": "https://doi.org/10.1093/molbev/mss020", "year": 2012, "authors": ["Robert Lanfear", "Brett Calcott", "Simon Y. W. Ho", "Stéphane Guindon"], "source": "Molecular Biology and Evolution", "cited": 5842, "abstract": "In phylogenetic analyses of molecular sequence data, partitioning involves estimating independent models of molecular evolution for different sets of sites in a sequence alignment. Choosing an appropriate partitioning scheme is an important step in most analyses because it can affect the accuracy of phylogenetic reconstruction. Despite this, partitioning schemes are often chosen without explicit statistical justification. Here, we describe two new objective methods for the combined selection of best-fit partitioning schemes and nucleotide substitution models. These methods allow millions of partitioning schemes to be compared in realistic time frames and so permit the objective selection of partitioning schemes even for large multilocus DNA data sets. We demonstrate that these methods sign", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/29/6/1695/3208781/mss020.pdf", "local_pdf": "", "api": ""}, {"title": "Model Selection and Inference: A Practical Information-Theoretic Approach", "doi": "https://doi.org/10.2307/2669574", "year": 2000, "authors": ["Robert L. Strawderman", "Kenneth P. Burnham", "David R. Anderson"], "source": "Journal of the American Statistical Association", "cited": 4218, "abstract": "We wrote this book to introduce graduate students and research workers in various scientific disciplines to the use of information-theoretic approaches in the analysis of empirical data.In its fully developed form, the information-theoretic approach allows inference based on more than one model (including estimates of unconditional precision); in its initial form, it is useful in selecting a \"best\" model and ranking the remaining models.We believe that often the critical issue in data analysis is the selection of a good approximating model that best represents the inference supported by the data (an estimated \"best approximating model\").Information theory includes the well-known Kullback-Leibler \"distance\" between two models (actually, probability distributions), and this represents a fund", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f2669574", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Alternatives for logistic regression in cross-sectional studies: an empirical comparison of models that directly estimate the prevalence ratio", "doi": "https://doi.org/10.1186/1471-2288-3-21", "year": 2003, "authors": ["Aluísio J. D. Barros", "Vânia Naomi Hirakata"], "source": "BMC Medical Research Methodology", "cited": 4204, "abstract": "BACKGROUND: Cross-sectional studies with binary outcomes analyzed by logistic regression are frequent in the epidemiological literature. However, the odds ratio can importantly overestimate the prevalence ratio, the measure of choice in these studies. Also, controlling for confounding is not equivalent for the two measures. In this paper we explore alternatives for modeling data of such studies with techniques that directly estimate the prevalence ratio. METHODS: We compared Cox regression with constant time at risk, Poisson regression and log-binomial regression against the standard Mantel-Haenszel estimators. Models with robust variance estimators in Cox and Poisson regressions and variance corrected by the scale parameter in Poisson regression were also evaluated. RESULTS: Three outcome", "oa": true, "pdf_url": "https://bmcmedresmethodol.biomedcentral.com/track/pdf/10.1186/1471-2288-3-21", "local_pdf": "024_Alternatives for logistic regression in .pdf", "api": ""}, {"title": "Purposeful selection of variables in logistic regression", "doi": "https://doi.org/10.1186/1751-0473-3-17", "year": 2008, "authors": ["Zoran Bursac", "C. Heath Gauss", "David Williams", "David W. Hosmer"], "source": "Source Code for Biology and Medicine", "cited": 4058, "abstract": "BACKGROUND: The main problem in many model-building situations is to choose from a large set of covariates those that should be included in the \"best\" model. A decision to keep a variable in the model might be based on the clinical or statistical significance. There are several variable selection algorithms in existence. Those methods are mechanical and as such carry some limitations. Hosmer and Lemeshow describe a purposeful selection of covariates within which an analyst makes a variable selection decision at each step of the modeling process. METHODS: In this paper we introduce an algorithm which automates that process. We conduct a simulation study to compare the performance of this algorithm with three well documented variable selection procedures in SAS PROC LOGISTIC: FORWARD, BACKWA", "oa": true, "pdf_url": "https://scfbm.biomedcentral.com/counter/pdf/10.1186/1751-0473-3-17", "local_pdf": "025_Purposeful selection of variables in log.pdf", "api": ""}, {"title": "Model Selection and Model Averaging in Phylogenetics: Advantages of Akaike Information Criterion and Bayesian Approaches Over Likelihood Ratio Tests", "doi": "https://doi.org/10.1080/10635150490522304", "year": 2004, "authors": ["David Posada", "Thomas R. Buckley"], "source": "Systematic Biology", "cited": 4013, "abstract": "Model selection is a topic of special relevance in molecular phylogenetics that affects many, if not all, stages of phylogenetic inference. Here we discuss some fundamental concepts and techniques of model selection in the context of phylogenetics. We start by reviewing different aspects of the selection of substitution models in phylogenetics from a theoretical, philosophical and practical point of view, and summarize this comparison in table format. We argue that the most commonly implemented model selection approach, the hierarchical likelihood ratio test, is not the optimal strategy for model selection in phylogenetics, and that approaches like the Akaike Information Criterion (AIC) and Bayesian methods offer important advantages. In particular, the latter two methods are able to simul", "oa": true, "pdf_url": "https://academic.oup.com/sysbio/article-pdf/53/5/793/24197659/53-5-793.pdf", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Model Selection and Akaike's Information Criterion (AIC): The General Theory and its Analytical Extensions", "doi": "10.1007/bf02294361", "year": 1987, "authors": ["Hamparsum Bozdogan"], "source": "Psychometrika", "cited": 3601, "abstract": " During the last fifteen years, Akaike's entropy-based Information Criterion (AIC) has had a fundamental impact in statistical model evaluation problems. This paper studies the general theory of the AIC procedure and provides its analytical extensions in two ways without violating Akaike's main principles. These extensions make AIC asymptotically consistent and penalize overparameterization more stringently to pick only the simplest of the “true” models. These selection criteria are called CAIC and CAICF. Asymptotic properties of AIC and its extensions are investigated, and empirical performances of these criteria are studied in choosing the correct degree of a polynomial model in two different Monte Carlo experiments under different conditions. ", "oa": true, "pdf_url": "http://link.springer.com/content/pdf/10.1007/BF02294361.pdf", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": "crossref"}, {"title": "A survey of cross-validation procedures for model selection", "doi": "https://doi.org/10.1214/09-ss054", "year": 2010, "authors": ["Sylvain Arlot", "Alain Celisse"], "source": "Statistics Surveys", "cited": 3406, "abstract": "Used to estimate the risk of an estimator or to perform model selection, cross-validation is a widespread strategy because of its simplicity and its (apparent) universality. Many results exist on model selection performances of cross-validation procedures. This survey intends to relate these results to the most recent advances of model selection theory, with a particular emphasis on distinguishing empirical statements from rigorous theoretical results. As a conclusion, guidelines are provided for choosing the best cross-validation procedure according to the particular features of the problem in hand.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistics-surveys/volume-4/issue-none/A-survey-of-cross-validation-procedures-for-model-selection/10.1214/09-SS054.pdf", "local_pdf": "", "api": ""}, {"title": "ProtTest: selection of best-fit models of protein evolution", "doi": "https://doi.org/10.1093/bioinformatics/bti263", "year": 2005, "authors": ["Federico Abascal", "Rafael Zardoya", "David Posada"], "source": "Computer applications in the biosciences", "cited": 3120, "abstract": "SUMMARY: Using an appropriate model of amino acid replacement is very important for the study of protein evolution and phylogenetic inference. We have built a tool for the selection of the best-fit model of evolution, among a set of candidate models, for a given protein sequence alignment. AVAILABILITY: ProtTest is available under the GNU license from http://darwin.uvigo.es", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/21/9/2104/48972592/bioinformatics_21_9_2104.pdf", "local_pdf": "", "api": ""}, {"title": "A tutorial on regularized partial correlation networks.", "doi": "https://doi.org/10.1037/met0000167", "year": 2018, "authors": ["Sacha Epskamp", "Eiko I. Fried"], "source": "Psychological Methods", "cited": 2898, "abstract": "Recent years have seen an emergence of network modeling applied to moods, attitudes, and problems in the realm of psychology. In this framework, psychological variables are understood to directly affect each other rather than being caused by an unobserved latent entity. In this tutorial, we introduce the reader to estimating the most popular network model for psychological data: the partial correlation network. We describe how regularization techniques can be used to efficiently estimate a parsimonious and interpretable network structure in psychological data. We show how to perform these analyses in R and demonstrate the method in an empirical example on posttraumatic stress disorder data. In addition, we discuss the effect of the hyperparameter that needs to be manually set by the resear", "oa": true, "pdf_url": "https://doi.org/10.1037/met0000167", "local_pdf": "", "api": ""}, {"title": "The coefficient of determination R 2 and intra-class correlation coefficient from generalized linear mixed-effects models revisited and expanded", "doi": "https://doi.org/10.1098/rsif.2017.0213", "year": 2017, "authors": ["Shinichi Nakagawa", "P. Johnson", "Holger Schielzeth"], "source": "Journal of The Royal Society Interface", "cited": 2839, "abstract": "The coefficient of determination R 2 quantifies the proportion of variance explained by a statistical model and is an important summary statistic of biological interest. However, estimating R 2 for generalized linear mixed models (GLMMs) remains challenging. We have previously introduced a version of R 2 that we called for Poisson and binomial GLMMs, but not for other distributional families. Similarly, we earlier discussed how to estimate intra-class correlation coefficients (ICCs) using Poisson and binomial GLMMs. In this paper, we generalize our methods to all other non-Gaussian distributions, in particular to negative binomial and gamma distributions that are commonly used for modelling biological data. While expanding our approach, we highlight two useful concepts for biologists, Jens", "oa": true, "pdf_url": "https://royalsocietypublishing.org/doi/pdf/10.1098/rsif.2017.0213", "local_pdf": "", "api": ""}, {"title": "Sure Independence Screening for Ultrahigh Dimensional Feature Space", "doi": "https://doi.org/10.1111/j.1467-9868.2008.00674.x", "year": 2008, "authors": ["Jianqing Fan", "Jinchi Lv"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 2838, "abstract": "Summary Variable selection plays an important role in high dimensional statistical modelling which nowadays appears in many areas and is key to various scientific discoveries. For problems of large scale or dimensionality p, accuracy of estimation and computational cost are two top concerns. Recently, Candes and Tao have proposed the Dantzig selector using L1-regularization and showed that it achieves the ideal risk up to a logarithmic factor log(p). Their innovative procedure and remarkable result are challenged when the dimensionality is ultrahigh as the factor log(p) can be large and their uniform uncertainty principle can fail. Motivated by these concerns, we introduce the concept of sure screening and propose a sure screening method that is based on correlation learning, called sure i", "oa": true, "pdf_url": "https://doi.org/10.1111/j.1467-9868.2008.00674.x", "local_pdf": "", "api": ""}, {"title": "AIC model selection using Akaike weights", "doi": "https://doi.org/10.3758/bf03206482", "year": 2004, "authors": ["Eric‐Jan Wagenmakers", "Simon Farrell"], "source": "Psychonomic Bulletin & Review", "cited": 2837, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/BF03206482.pdf", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Simultaneous analysis of Lasso and Dantzig selector", "doi": "https://doi.org/10.1214/08-aos620", "year": 2009, "authors": ["Peter J. Bickel", "Ya’acov Ritov", "Alexandre B. Tsybakov"], "source": "The Annals of Statistics", "cited": 2537, "abstract": "We show that, under a sparsity scenario, the Lasso estimator and the Dantzig selector exhibit similar behavior. For both methods, we derive, in parallel, oracle inequalities for the prediction risk in the general nonparametric regression model, as well as bounds on the ℓp estimation loss for 1≤p≤2 in the linear model when the number of variables can be much larger than the sample size.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-37/issue-4/Simultaneous-analysis-of-Lasso-and-Dantzig-selector/10.1214/08-AOS620.pdf", "local_pdf": "", "api": ""}, {"title": "Model Selection and Inference: A Practical Information-Theoretic Approach", "doi": "https://doi.org/10.2307/3803117", "year": 2001, "authors": ["Paul Beier", "Kenneth P. Burnham", "David R. Anderson"], "source": "Journal of Wildlife Management", "cited": 2505, "abstract": "We wrote this book to introduce graduate students and research workers in various scientific disciplines to the use of information-theoretic approaches in the analysis of empirical data.In its fully developed form, the information-theoretic approach allows inference based on more than one model (including estimates of unconditional precision); in its initial form, it is useful in selecting a \"best\" model and ranking the remaining models.We believe that often the critical issue in data analysis is the selection of a good approximating model that best represents the inference supported by the data (an estimated \"best approximating model\").Information theory includes the well-known Kullback-Leibler \"distance\" between two models (actually, probability distributions), and this represents a fund", "oa": true, "pdf_url": "https://doi.org/10.2307/3803117", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Computational procedures for probing interactions in OLS and logistic regression: SPSS and SAS implementations", "doi": "https://doi.org/10.3758/brm.41.3.924", "year": 2009, "authors": ["Andrew F. Hayes", "Jörg Matthes"], "source": "Behavior Research Methods", "cited": 2449, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758%2FBRM.41.3.924.pdf", "local_pdf": "", "api": ""}, {"title": "Ecological niche modeling in Maxent: the importance of model complexity and the performance of model selection criteria", "doi": "https://doi.org/10.1890/10-1171.1", "year": 2010, "authors": ["Dan L. Warren", "Stephanie N. Seifert"], "source": "Ecological Applications", "cited": 2357, "abstract": "Maxent, one of the most commonly used methods for inferring species distributions and environmental tolerances from occurrence data, allows users to fit models of arbitrary complexity. Model complexity is typically constrained via a process known as L1 regularization, but at present little guidance is available for setting the appropriate level of regularization, and the effects of inappropriately complex or simple models are largely unknown. In this study, we demonstrate the use of information criterion approaches to setting regularization in Maxent, and we compare models selected using information criteria to models selected using other criteria that are common in the literature. We evaluate model performance using occurrence data generated from a known \"true\" initial Maxent model, using", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1890/10-1171.1", "local_pdf": "", "api": ""}, {"title": "Relative Importance for Linear Regression in R : The Package relaimpo", "doi": "https://doi.org/10.18637/jss.v017.i01", "year": 2006, "authors": ["Ulrike Grömping"], "source": "Journal of Statistical Software", "cited": 2222, "abstract": "Relative importance is a topic that has seen a lot of interest in recent years, particularly in applied work. The R package relaimpo implements six different metrics for assessing relative importance of regressors in the linear model, two of which are recommended - averaging over orderings of regressors and a newly proposed metric (Feldman 2005) called pmvd. Apart from delivering the metrics themselves, relaimpo also provides (exploratory) bootstrap confidence intervals. This paper offers a brief tutorial introduction to the package. The methods and relaimpo's functionality are illustrated using the data set swiss that is generally available in R. The paper targets readers who have a basic understanding of multiple linear regression. For the background of more advanced aspects, references ", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v017.i01", "local_pdf": "077_Relative Importance for Linear Regressio.pdf", "api": ""}, {"title": "ModelTest-NG: A New and Scalable Tool for the Selection of DNA and Protein Evolutionary Models", "doi": "https://doi.org/10.1093/molbev/msz189", "year": 2019, "authors": ["Diego Darriba", "David Posada", "Alexey M. Kozlov", "Alexandros Stamatakis", "Benoît Morel", "Tomáš Flouri"], "source": "Molecular Biology and Evolution", "cited": 2217, "abstract": "ModelTest-NG is a reimplementation from scratch of jModelTest and ProtTest, two popular tools for selecting the best-fit nucleotide and amino acid substitution models, respectively. ModelTest-NG is one to two orders of magnitude faster than jModelTest and ProtTest but equally accurate and introduces several new features, such as ascertainment bias correction, mixture, and free-rate models, or the automatic processing of single partitions. ModelTest-NG is available under a GNU GPL3 license at https://github.com/ddarriba/modeltest , last accessed September 2, 2019.", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/37/1/291/32085561/msz189.pdf", "local_pdf": "", "api": ""}, {"title": "CPAT: Coding-Potential Assessment Tool using an alignment-free logistic regression model", "doi": "https://doi.org/10.1093/nar/gkt006", "year": 2013, "authors": ["Liguo Wang", "Hyun Jung Park", "Surendra Dasari", "Shengqin Wang", "Jean‐Pierre Kocher", "Wei Li"], "source": "Nucleic Acids Research", "cited": 2216, "abstract": "Thousands of novel transcripts have been identified using deep transcriptome sequencing. This discovery of large and 'hidden' transcriptome rejuvenates the demand for methods that can rapidly distinguish between coding and noncoding RNA. Here, we present a novel alignment-free method, Coding Potential Assessment Tool (CPAT), which rapidly recognizes coding and noncoding transcripts from a large pool of candidates. To this end, CPAT uses a logistic regression model built with four sequence features: open reading frame size, open reading frame coverage, Fickett TESTCODE statistic and hexamer usage bias. CPAT software outperformed (sensitivity: 0.96, specificity: 0.97) other state-of-the-art alignment-based software such as Coding-Potential Calculator (sensitivity: 0.99, specificity: 0.74) an", "oa": true, "pdf_url": "https://academic.oup.com/nar/article-pdf/41/6/e74/25339876/gkt006.pdf", "local_pdf": "", "api": ""}, {"title": "Logistic regression and artificial neural network classification models: a methodology review", "doi": "https://doi.org/10.1016/s1532-0464(03)00034-0", "year": 2002, "authors": ["Stephan Dreiseitl", "Lucila Ohno‐Machado"], "source": "Journal of Biomedical Informatics", "cited": 2202, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S1532046403000340/pdf", "local_pdf": "079_Statistics review 14_ Logistic regressio.pdf", "api": ""}, {"title": "A brief introduction to mixed effects modelling and multi-model inference in ecology", "doi": "https://doi.org/10.7717/peerj.4794", "year": 2018, "authors": ["Xavier A. Harrison", "Lynda Donaldson", "Maria Correa-Cano", "Julian Evans", "David N. Fisher", "Cecily Goodwin"], "source": "PeerJ", "cited": 2133, "abstract": "The use of linear mixed effects models (LMMs) is increasingly common in the analysis of biological data. Whilst LMMs offer a flexible approach to modelling a broad range of data types, ecological data are often complex and require complex model structures, and the fitting and interpretation of such models is not always straightforward. The ability to achieve robust biological inference requires that practitioners know how and when to apply these tools. Here, we provide a general overview of current methods for the application of LMMs to biological data, and highlight the typical pitfalls that can be encountered in the statistical modelling process. We tackle several issues regarding methods of model selection, with particular reference to the use of information theory and multi-model infer", "oa": true, "pdf_url": "https://doi.org/10.7717/peerj.4794", "local_pdf": "", "api": ""}, {"title": "SMS: Smart Model Selection in PhyML", "doi": "https://doi.org/10.1093/molbev/msx149", "year": 2017, "authors": ["Vincent Lefort", "Jean-Emmanuel Longueville", "Olivier Gascuel"], "source": "Molecular Biology and Evolution", "cited": 2026, "abstract": "Model selection using likelihood-based criteria (e.g., AIC) is one of the first steps in phylogenetic analysis. One must select both a substitution matrix and a model for rates across sites. A simple method is to test all combinations and select the best one. We describe heuristics to avoid these extensive calculations. Runtime is divided by ∼2 with results remaining nearly the same, and the method performs well compared with ProtTest and jModelTest2. Our software, \"Smart Model Selection\" (SMS), is implemented in the PhyML environment and available using two interfaces: command-line (to be integrated in pipelines) and a web server (http://www.atgc-montpellier.fr/phyml-sms/).", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/34/9/2422/24367179/msx149.pdf", "local_pdf": "", "api": ""}, {"title": "Model selection and psychological theory: A discussion of the differences between the Akaike information criterion (AIC) and the Bayesian information criterion (BIC).", "doi": "https://doi.org/10.1037/a0027127", "year": 2012, "authors": ["Scott Vrieze"], "source": "Psychological Methods", "cited": 2011, "abstract": "This article reviews the Akaike information criterion (AIC) and the Bayesian information criterion (BIC) in model selection and the appraisal of psychological theory. The focus is on latent variable models, given their growing use in theory testing and construction. Theoretical statistical results in regression are discussed, and more important issues are illustrated with novel simulations involving latent variable models including factor analysis, latent profile analysis, and factor mixture models. Asymptotically, the BIC is consistent, in that it will select the true model if, among other assumptions, the true model is among the candidate models considered. The AIC is not consistent under these circumstances. When the true model is not in the candidate model set the AIC is efficient, in ", "oa": true, "pdf_url": "https://doi.org/10.1037/a0027127", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Evaluating significance in linear mixed-effects models in R", "doi": "https://doi.org/10.3758/s13428-016-0809-y", "year": 2016, "authors": ["Steven G. Luke"], "source": "Behavior Research Methods", "cited": 1924, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13428-016-0809-y.pdf", "local_pdf": "045_Evaluating significance in linear mixed-.pdf", "api": ""}, {"title": "The Blinder–Oaxaca Decomposition for Linear Regression Models", "doi": "https://doi.org/10.1177/1536867x0800800401", "year": 2008, "authors": ["Ben Jann"], "source": "The Stata Journal Promoting communications on statistics and Stata", "cited": 1877, "abstract": "The counterfactual decomposition technique popularized by Blinder (1973, Journal of Human Resources, 436–455) and Oaxaca (1973, International Economic Review, 693–709) is widely used to study mean outcome differences between groups. For example, the technique is often used to analyze wage gaps by sex or race. This article summarizes the technique and addresses several complications, such as the identification of effects of categorical predictors in the detailed decomposition or the estimation of standard errors. A new command called oaxaca is introduced, and examples illustrating its usage are given.", "oa": true, "pdf_url": "https://doi.org/10.1177/1536867x0800800401", "local_pdf": "", "api": ""}, {"title": "A brief conceptual tutorial of multilevel analysis in social epidemiology: using measures of clustering in multilevel logistic regression to investigate contextual phenomena", "doi": "https://doi.org/10.1136/jech.2004.029454", "year": 2006, "authors": ["Juan Merlo", "Basile Chaix", "Henrik Ohlsson", "Anders Beckman", "Kristina Johnell", "Per Hjerpe"], "source": "Journal of Epidemiology & Community Health", "cited": 1729, "abstract": "STUDY OBJECTIVE: In social epidemiology, it is easy to compute and interpret measures of variation in multilevel linear regression, but technical difficulties exist in the case of logistic regression. The aim of this study was to present measures of variation appropriate for the logistic case in a didactic rather than a mathematical way. DESIGN AND PARTICIPANTS: Data were used from the health survey conducted in 2000 in the county of Scania, Sweden, that comprised 10 723 persons aged 18-80 years living in 60 areas. Conducting multilevel logistic regression different techniques were applied to investigate whether the individual propensity to consult private physicians was statistically dependent on the area of residence (that is, intraclass correlation (ICC), median odds ratio (MOR)), the 8", "oa": true, "pdf_url": "https://doi.org/10.1136/jech.2004.029454", "local_pdf": "", "api": ""}, {"title": "Introduction to linear regression analysis", "doi": "https://doi.org/10.1080/02664763.2013.816069", "year": 2013, "authors": ["Pieter Bastiaan Ober"], "source": "Journal of Applied Statistics", "cited": 1660, "abstract": "This is already the fifth edition of ‘Introduction to Linear Regression Analysis’. With 672 pages, it is a very comprehensive introduction to linear regression analysis, with room for more than jus...", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/pdf/10.1080/02664763.2013.816069?needAccess=true", "local_pdf": "", "api": ""}, {"title": "Prediction-Corrected Visual Predictive Checks for Diagnosing Nonlinear Mixed-Effects Models", "doi": "https://doi.org/10.1208/s12248-011-9255-z", "year": 2011, "authors": ["Martin Bergstrand", "Andrew C. Hooker", "Johan Wallin", "Mats O. Karlsson"], "source": "The AAPS Journal", "cited": 1422, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1208/s12248-011-9255-z.pdf", "local_pdf": "", "api": ""}, {"title": "Robustness of linear mixed‐effects models to violations of distributional assumptions", "doi": "https://doi.org/10.1111/2041-210x.13434", "year": 2020, "authors": ["Holger Schielzeth", "Niels J. Dingemanse", "Shinichi Nakagawa", "David F. Westneat", "Hassen Allegue", "Céline Teplitsky"], "source": "Methods in Ecology and Evolution", "cited": 1418, "abstract": "Abstract Linear mixed‐effects models are powerful tools for analysing complex datasets with repeated or clustered observations, a common data structure in ecology and evolution. Mixed‐effects models involve complex fitting procedures and make several assumptions, in particular about the distribution of residual and random effects. Violations of these assumptions are common in real datasets, yet it is not always clear how much these violations matter to accurate and unbiased estimation. Here we address the consequences of violations in distributional assumptions and the impact of missing random effect components on model estimates. In particular, we evaluate the effects of skewed, bimodal and heteroscedastic random effect and residual variances, of missing random effect terms and of correla", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/2041-210X.13434", "local_pdf": "", "api": ""}, {"title": "Power Analysis and Effect Size in Mixed Effects Models: A Tutorial", "doi": "https://doi.org/10.5334/joc.10", "year": 2018, "authors": ["Marc Brysbaert", "Michaël Stevens"], "source": "Journal of Cognition", "cited": 1408, "abstract": "In psychology, attempts to replicate published findings are less successful than expected. For properly powered studies replication rate should be around 80%, whereas in practice less than 40% of the studies selected from different areas of psychology can be replicated. Researchers in cognitive psychology are hindered in estimating the power of their studies, because the designs they use present a sample of stimulus materials to a sample of participants, a situation not covered by most power formulas. To remedy the situation, we review the literature related to the topic and introduce recent software packages, which we apply to the data of two masked priming studies with high power. We checked how we could estimate the power of each study and how much they could be reduced to remain powerf", "oa": true, "pdf_url": "http://www.journalofcognition.org/articles/10.5334/joc.10/galley/20/download/", "local_pdf": "003_Statistical power analyses using G_Power.pdf", "api": ""}, {"title": "Understanding logistic regression analysis", "doi": "https://doi.org/10.11613/bm.2014.003", "year": 2014, "authors": ["Sandro Sperandei"], "source": "Biochemia Medica", "cited": 1405, "abstract": "Logistic regression is used to obtain odds ratio in the presence of more than one explanatory variable. The procedure is quite similar to multiple linear regression, with the exception that the response variable is binomial. The result is the impact of each variable on the odds ratio of the observed event of interest. The main advantage is to avoid confounding effects by analyzing the association of all variables together. In this article, we explain the logistic regression procedure using examples to make it as simple as possible. After definition of the technique, the basic interpretation of the results is highlighted and then some special issues are discussed.", "oa": true, "pdf_url": "https://www.biochemia-medica.com/assets/images/upload/xml_tif/Sperandei_S_Logistic_regression_analysis.pdf", "local_pdf": "052_Understanding logistic regression analys.pdf", "api": ""}, {"title": "Smoothing Parameter and Model Selection for General Smooth Models", "doi": "https://doi.org/10.1080/01621459.2016.1180986", "year": 2016, "authors": ["Simon N. Wood", "Natalya Pya", "Benjamin Säfken"], "source": "Journal of the American Statistical Association", "cited": 1360, "abstract": "This article discusses a general framework for smoothing parameter estimation for models with regular likelihoods constructed in terms of unknown smooth functions of covariates. Gaussian random effects and parametric terms may also be present. By construction the method is numerically stable and convergent, and enables smoothing parameter uncertainty to be quantified. The latter enables us to fix a well known problem with AIC for such models, thereby improving the range of model selection tools available. The smooth functions are represented by reduced rank spline like smoothers, with associated quadratic penalties measuring function smoothness. Model estimation is by penalized likelihood maximization, where the smoothing parameters controlling the extent of penalization are estimated by L", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/pdf/10.1080/01621459.2016.1180986?needAccess=true", "local_pdf": "", "api": ""}, {"title": "Some Aspects of Measurement Error in Linear Regression of Astronomical Data", "doi": "https://doi.org/10.1086/519947", "year": 2007, "authors": ["Brandon C. Kelly"], "source": "The Astrophysical Journal", "cited": 1342, "abstract": "I describe a Bayesian method to account for measurement errors in linear regression of astronomical data. The method allows for heteroscedastic and possibly correlated measurement errors and intrinsic scatter in the regression relationship. The method is based on deriving a likelihood function for the measured data, and I focus on the case when the intrinsic distribution of the independent variables can be approximated using a mixture of Gaussian functions. I generalize the method to incorporate multiple independent variables, nondetections, and selection effects (e.g., Malmquist bias). A Gibbs sampler is described for simulating random draws from the probability distribution of the parameters, given the observed data. I use simulation to compare the method with other common estimators. Th", "oa": true, "pdf_url": "https://iopscience.iop.org/article/10.1086/519947/pdf", "local_pdf": "", "api": ""}, {"title": "Logistic Regression Diagnostics", "doi": "https://doi.org/10.1214/aos/1176345513", "year": 1981, "authors": ["Daryl Pregibon"], "source": "The Annals of Statistics", "cited": 1307, "abstract": "A maximum likelihood fit of a logistic regression model (and other similar models) is extremely sensitive to outlying responses and extreme points in the design space. We develop diagnostic measures to aid the analyst in detecting such observations and in quantifying their effect on various aspects of the maximum likelihood fit. The elements of the fitting process which constitute the usual output (parameter estimates, standard errors, residuals, etc.) will be used for this purpose. With a properly designed computing package for fitting the usual maximum-likelihood model, the diagnostics are essentially \"free for the asking.\" In particular, good data analysis for logistic regression models need not be expensive or time-consuming.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-9/issue-4/Logistic-Regression-Diagnostics/10.1214/aos/1176345513.pdf", "local_pdf": "079_Statistics review 14_ Logistic regressio.pdf", "api": ""}, {"title": "A Review on Linear Regression Comprehensive in Machine Learning", "doi": "https://doi.org/10.38094/jastt1457", "year": 2020, "authors": ["Dastan Hussen Maulud", "Adnan Mohsin Abdulazeez"], "source": "Journal of Applied Science and Technology Trends", "cited": 1261, "abstract": "Perhaps one of the most common and comprehensive statistical and machine learning algorithms are linear regression. Linear regression is used to find a linear relationship between one or more predictors. The linear regression has two types: simple regression and multiple regression (MLR). This paper discusses various works by different researchers on linear regression and polynomial regression and compares their performance using the best approach to optimize prediction and precision. Almost all of the articles analyzed in this review is focused on datasets; in order to determine a model's efficiency, it must be correlated with the actual values obtained for the explanatory variables.", "oa": true, "pdf_url": "https://jastt.org/index.php/jasttpath/article/download/57/20", "local_pdf": "056_A Review on Linear Regression Comprehens.pdf", "api": ""}, {"title": "glmulti : An R Package for Easy Automated Model Selection with (Generalized) Linear Models", "doi": "https://doi.org/10.18637/jss.v034.i12", "year": 2010, "authors": ["Vincent Calcagno", "Claire de Mazancourt"], "source": "Journal of Statistical Software", "cited": 1215, "abstract": "We introduce glmulti, an R package for automated model selection and multi-model inference with glm and related functions. From a list of explanatory variables, the provided function glmulti builds all possible unique models involving these variables and, optionally, their pairwise interactions. Restrictions can be specified for candidate models, by excluding specific terms, enforcing marginality, or controlling model complexity. Models are fitted with standard R functions like glm. The n best models and their support (e.g., (Q)AIC, (Q)AICc, or BIC) are returned, allowing model selection and multi-model inference through standard R functions. The package is optimized for large candidate sets by avoiding memory limitation, facilitating parallelization and providing, in addition to exhaustiv", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v034.i12", "local_pdf": "", "api": ""}, {"title": "Logistic Regression", "doi": "https://doi.org/10.1161/circulationaha.106.682658", "year": 2008, "authors": ["Michael P. LaValley"], "source": "Circulation", "cited": 1112, "abstract": "", "oa": true, "pdf_url": "https://www.ahajournals.org/doi/pdf/10.1161/CIRCULATIONAHA.106.682658", "local_pdf": "079_Statistics review 14_ Logistic regressio.pdf", "api": ""}, {"title": "Correlation and Simple Linear Regression", "doi": "https://doi.org/10.1148/radiol.2273011499", "year": 2003, "authors": ["Kelly H. Zou", "Kemal Tuncali", "Stuart G. Silverman"], "source": "Radiology", "cited": 1089, "abstract": "In this tutorial article, the concepts of correlation and regression are reviewed and demonstrated. The authors review and compare two correlation coefficients, the Pearson correlation coefficient and the Spearman rho, for measuring linear and nonlinear relationships between two continuous variables. In the case of measuring the linear relationship between a predictor and an outcome variable, simple linear regression analysis is conducted. These statistical concepts are illustrated by using a data set from published literature to assess a computed tomography-guided interventional technique. These statistical methods are important for exploring the relationships between variables and can be applied to many radiologic studies.", "oa": true, "pdf_url": "https://doi.org/10.1148/radiol.2273011499", "local_pdf": "", "api": ""}, {"title": "strucchange : An R Package for Testing for Structural Change in Linear Regression Models", "doi": "https://doi.org/10.18637/jss.v007.i02", "year": 2002, "authors": ["Achim Zeileis", "Friedrich Leisch", "Kurt Hornik", "Christian Kleiber"], "source": "Journal of Statistical Software", "cited": 1070, "abstract": "This paper reviews tests for structural change in linear regression models from the generalized fluctuation test framework as well as from the F test (Chow test) framework. It introduces a unified approach for implementing these tests and presents how these ideas have been realized in an R package called strucchange. Enhancing the standard significance test approach the package contains methods to fit, plot and test empirical fluctuation processes (like CUSUM, MOSUM and estimates-based processes) and to compute, plot and test sequences of F statistics with the supF , aveF and expF test. Thus, it makes powerful tools available to display information about structural changes in regression relationships and to assess their significance. Furthermore, it is described how incoming data can be mo", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v007.i02", "local_pdf": "", "api": ""}, {"title": "The number of subjects per variable required in linear regression analyses", "doi": "https://doi.org/10.1016/j.jclinepi.2014.12.014", "year": 2015, "authors": ["Peter C. Austin", "Ewout W. Steyerberg"], "source": "Journal of Clinical Epidemiology", "cited": 1068, "abstract": "OBJECTIVES: To determine the number of independent variables that can be included in a linear regression model. STUDY DESIGN AND SETTING: We used a series of Monte Carlo simulations to examine the impact of the number of subjects per variable (SPV) on the accuracy of estimated regression coefficients and standard errors, on the empirical coverage of estimated confidence intervals, and on the accuracy of the estimated R(2) of the fitted model. RESULTS: A minimum of approximately two SPV tended to result in estimation of regression coefficients with relative bias of less than 10%. Furthermore, with this minimum number of SPV, the standard errors of the regression coefficients were accurately estimated and estimated confidence intervals had approximately the advertised coverage rates. A much ", "oa": true, "pdf_url": "http://www.jclinepi.com/article/S0895435615000141/pdf", "local_pdf": "", "api": ""}, {"title": "Information criteria for astrophysical model selection", "doi": "https://doi.org/10.1111/j.1745-3933.2007.00306.x", "year": 2007, "authors": ["Andrew R. Liddle"], "source": "Monthly Notices of the Royal Astronomical Society Letters", "cited": 1030, "abstract": "Abstract Model selection is the problem of distinguishing competing models, perhaps featuring different numbers of parameters. The statistics literature contains two distinct sets of tools, those based on information theory such as the Akaike Information Criterion (AIC), and those on Bayesian inference such as the Bayesian evidence and Bayesian Information Criterion (BIC). The Deviance Information Criterion combines ideas from both heritages; it is readily computed from Monte Carlo posterior samples and, unlike the AIC and BIC, allows for parameter degeneracy. I describe the properties of the information criteria, and as an example compute them from Wilkinson Microwave Anisotropy Probe 3-yr data for several cosmological models. I find that at present the information theory and Bayesian app", "oa": true, "pdf_url": "https://doi.org/10.1111/j.1745-3933.2007.00306.x", "local_pdf": "", "api": ""}, {"title": "Phylogenetic signal and linear regression on species data", "doi": "https://doi.org/10.1111/j.2041-210x.2010.00044.x", "year": 2010, "authors": ["Liam J. Revell"], "source": "Methods in Ecology and Evolution", "cited": 981, "abstract": "1. A common procedure in the regression analysis of interspecies data is to first test the independent and dependent variables X and Y for phylogenetic signal, and then use the presence of signal in one or both traits to justify regression analysis using phylogenetic methods such as independent contrasts or phylogenetic generalized least squares. 2. This is incorrect, because phylogenetic regression assumes that the residual error in the regression model (not in the original traits) is distributed according to a multivariate normal distribution with variances and covariances proportional to the historical relations of the species in the sample. 3. Here, I examine the consequences of justifying and applying the phylogenetic regression incorrectly. I find that when used improperly the phylog", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.2041-210X.2010.00044.x", "local_pdf": "", "api": ""}, {"title": "On the “degrees of freedom” of the lasso", "doi": "https://doi.org/10.1214/009053607000000127", "year": 2007, "authors": ["Hui Zou", "Trevor Hastie", "Robert Tibshirani"], "source": "The Annals of Statistics", "cited": 973, "abstract": "We study the effective degrees of freedom of the lasso in the framework of Stein’s unbiased risk estimation (SURE). We show that the number of nonzero coefficients is an unbiased estimate for the degrees of freedom of the lasso—a conclusion that requires no special assumption on the predictors. In addition, the unbiased estimator is shown to be asymptotically consistent. With these results on hand, various model selection criteria—Cp, AIC and BIC—are available, which, along with the LARS algorithm, provide a principled and efficient approach to obtaining the optimal lasso fit with the computational effort of a single ordinary least-squares fit.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-35/issue-5/On-the-degrees-of-freedom-of-the-lasso/10.1214/009053607000000127.pdf", "local_pdf": "", "api": ""}, {"title": "Appropriate Assessment of Neighborhood Effects on Individual Health: Integrating Random and Fixed Effects in Multilevel Logistic Regression", "doi": "https://doi.org/10.1093/aje/kwi017", "year": 2004, "authors": ["K. Larsen"], "source": "American Journal of Epidemiology", "cited": 965, "abstract": "The logistic regression model is frequently used in epidemiologic studies, yielding odds ratio or relative risk interpretations. Inspired by the theory of linear normal models, the logistic regression model has been extended to allow for correlated responses by introducing random effects. However, the model does not inherit the interpretational features of the normal model. In this paper, the authors argue that the existing measures are unsatisfactory (and some of them are even improper) when quantifying results from multilevel logistic regression analyses. The authors suggest a measure of heterogeneity, the median odds ratio, that quantifies cluster heterogeneity and facilitates a direct comparison between covariate effects and the magnitude of heterogeneity in terms of well-known odds ra", "oa": true, "pdf_url": "https://academic.oup.com/aje/article-pdf/161/1/81/165535/kwi017.pdf", "local_pdf": "", "api": ""}, {"title": "Local Linear Regression Smoothers and Their Minimax Efficiencies", "doi": "https://doi.org/10.1214/aos/1176349022", "year": 1993, "authors": ["Jianqing Fan"], "source": "The Annals of Statistics", "cited": 908, "abstract": "In this paper we introduce a smooth version of local linear regression estimators and address their advantages. The MSE and MISE of the estimators are computed explicitly. It turns out that the local linear regression smoothers have nice sampling properties and high minimax efficiency-they are not only efficient in rates but also nearly efficient in constant factors. In the nonparametric regression context, the asymptotic minimax lower bound is developed via the heuristic of the \"hardest onedimensional subproblem\" of Donoho and Liu. Connections of the minimax risk with the modulus of continuity are made. The lower bound is also applicable for estimating conditional mean (regression) and conditional quantiles for both fixed and random design regression problems.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-21/issue-1/Local-Linear-Regression-Smoothers-and-Their-Minimax-Efficiencies/10.1214/aos/1176349022.pdf", "local_pdf": "", "api": ""}, {"title": "Classification and regression tree analysis in public health: Methodological review and comparison with logistic regression", "doi": "https://doi.org/10.1207/s15324796abm2603_02", "year": 2003, "authors": ["Stephenie C. Lemon", "Jason Roy", "Melissa A. Clark", "Peter D. Friedmann", "William Rakowski"], "source": "Annals of Behavioral Medicine", "cited": 908, "abstract": "BACKGROUND: Audience segmentation strategies are of increasing interest to public health professionals who wish to identify easily defined, mutually exclusive population subgroups whose members share similar characteristics that help determine participation in a health-related behavior as a basis for targeted interventions. Classification and regression tree (C&RT) analysis is a nonparametric decision tree methodology that has the ability to efficiently segment populations into meaningful subgroups. However, it is not commonly used in public health. PURPOSE: This study provides a methodological overview of C&RT analysis for persons unfamiliar with the procedure. METHODS AND RESULTS: An example of a C&RT analysis is provided and interpretation of results is discussed. Results are validated ", "oa": true, "pdf_url": "https://academic.oup.com/abm/article-pdf/26/3/172/22711439/12160_2008_article_263172.pdf", "local_pdf": "", "api": ""}, {"title": "Covariance regularization by thresholding", "doi": "https://doi.org/10.1214/08-aos600", "year": 2008, "authors": ["Peter J. Bickel", "Elizaveta Levina"], "source": "The Annals of Statistics", "cited": 899, "abstract": "This paper considers regularizing a covariance matrix of p variables estimated from n observations, by hard thresholding. We show that the thresholded estimate is consistent in the operator norm as long as the true covariance matrix is sparse in a suitable sense, the variables are Gaussian or sub-Gaussian, and (log p)/n→0, and obtain explicit rates. The results are uniform over families of covariance matrices which satisfy a fairly natural notion of sparsity. We discuss an intuitive resampling scheme for threshold selection and prove a general cross-validation result that justifies this approach. We also compare thresholding to other covariance estimators in simulations and on an example from climate data.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-36/issue-6/Covariance-regularization-by-thresholding/10.1214/08-AOS600.pdf", "local_pdf": "", "api": ""}, {"title": "Random forest versus logistic regression: a large-scale benchmark experiment", "doi": "https://doi.org/10.1186/s12859-018-2264-5", "year": 2018, "authors": ["Raphaël Couronné", "Philipp Probst", "Anne‐Laure Boulesteix"], "source": "BMC Bioinformatics", "cited": 892, "abstract": "BACKGROUND AND GOAL: The Random Forest (RF) algorithm for regression and classification has considerably gained popularity since its introduction in 2001. Meanwhile, it has grown to a standard classification approach competing with logistic regression in many innovation-friendly scientific fields. RESULTS: In this context, we present a large scale benchmarking experiment based on 243 real datasets comparing the prediction performance of the original version of RF with default parameters and LR as binary classification tools. Most importantly, the design of our benchmark experiment is inspired from clinical trial methodology, thus avoiding common pitfalls and major sources of biases. CONCLUSION: RF performed better than LR according to the considered accuracy measured in approximately 69% o", "oa": true, "pdf_url": "https://bmcbioinformatics.biomedcentral.com/track/pdf/10.1186/s12859-018-2264-5", "local_pdf": "069_Random forest versus logistic regression.pdf", "api": ""}, {"title": "Influential Observations, High Leverage Points, and Outliers in Linear Regression", "doi": "https://doi.org/10.1214/ss/1177013622", "year": 1986, "authors": ["Samprit Chatterjee", "Ali S. Hadi"], "source": "Statistical Science", "cited": 847, "abstract": "A bewilderingly large number of statistical quantities have been proposed to study outliers and influence of individual observations in regression analysis. In this article we describe the inter-relationships which exist among the proposed measures. An examination of these relationships leads us to conclude that only three of these measures along with some graphical displays can provide an analyst a complete picture of outliers (major discrepant points) and points which excessively influence the fitted regression equation. Illustrative examples based on real data are presented.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-1/issue-3/Influential-Observations-High-Leverage-Points-and-Outliers-in-Linear-Regression/10.1214/ss/1177013622.pdf", "local_pdf": "", "api": ""}, {"title": "Genome-wide association analysis by lasso penalized logistic regression", "doi": "https://doi.org/10.1093/bioinformatics/btp041", "year": 2009, "authors": ["Tong Tong Wu", "Yi Fang Chen", "Trevor Hastie", "Eric M. Sobel", "Kenneth Lange"], "source": "Bioinformatics", "cited": 832, "abstract": "MOTIVATION: In ordinary regression, imposition of a lasso penalty makes continuous model selection straightforward. Lasso penalized regression is particularly advantageous when the number of predictors far exceeds the number of observations. METHOD: The present article evaluates the performance of lasso penalized logistic regression in case-control disease gene mapping with a large number of SNPs (single nucleotide polymorphisms) predictors. The strength of the lasso penalty can be tuned to select a predetermined number of the most relevant SNPs and other predictors. For a given value of the tuning constant, the penalized likelihood is quickly maximized by cyclic coordinate ascent. Once the most potent marginal predictors are identified, their two-way and higher order interactions can also", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/25/6/714/16891845/btp041.pdf", "local_pdf": "", "api": ""}, {"title": "Random effects structure for testing interactions in linear mixed-effects models", "doi": "https://doi.org/10.3389/fpsyg.2013.00328", "year": 2013, "authors": ["Dale J. Barr"], "source": "Frontiers in Psychology", "cited": 818, "abstract": "OPINION article Front. Psychol., 05 June 2013Sec. Quantitative Psychology and Measurement https://doi.org/10.3389/fpsyg.2013.00328", "oa": true, "pdf_url": "https://www.frontiersin.org/articles/10.3389/fpsyg.2013.00328/pdf", "local_pdf": "072_Random effects structure for testing int.pdf", "api": ""}, {"title": "Influential Observations in Linear Regression", "doi": "https://doi.org/10.1080/01621459.1979.10481634", "year": 1979, "authors": ["R. Dennis Cook"], "source": "Journal of the American Statistical Association", "cited": 786, "abstract": "Characteristics of observations which cause them to be influential in a least squares analysis are investigated and related to residual variances, residual correlations, and the convex hull of the observed values of the independent variables. It is shown how deleting an observation can substantially alter an analysis by changing the partial F-tests, the studentized residuals, the residual variances, the convex hull of the independent variables, and the estimated parameter vector. Outliers are discussed briefly, and an example is presented.", "oa": true, "pdf_url": "https://doi.org/10.1080/01621459.1979.10481634", "local_pdf": "", "api": ""}, {"title": "Properties of Tests for Spatial Dependence in Linear Regression Models", "doi": "https://doi.org/10.1111/j.1538-4632.1991.tb00228.x", "year": 1991, "authors": ["Luc Anselin", "Sergio J. Rey"], "source": "Geographical Analysis", "cited": 783, "abstract": "Based on a large number of Monte Carlo simulation experiments on a regular lattice, we compare the properties of Moran's I and Lagrange multiplier tests for spatial dependence, that is, for both spatial error autocorrelation and for a spatially lagged dependent variable. We consider both bias and power of the tests for six sample sizes, ranging from twenty‐five to 225 observations, for different structures of the spatial weights matrix, for several underlying error distributions, for misspecified weights matrices, and for the situation where boundary effects are present. The results provide an indication of the sample sizes for which the asymptotic properties of the tests can be considered to hold. They also illustrate the power of the Lagrange multiplier tests to distinguish between subst", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1538-4632.1991.tb00228.x", "local_pdf": "", "api": ""}, {"title": "Estimating predicted probabilities from logistic regression: different methods correspond to different target populations", "doi": "https://doi.org/10.1093/ije/dyu029", "year": 2014, "authors": ["Clemma Muller", "Richard F. MacLehose"], "source": "International Journal of Epidemiology", "cited": 766, "abstract": "BACKGROUND: We review three common methods to estimate predicted probabilities following confounder-adjusted logistic regression: marginal standardization (predicted probabilities summed to a weighted average reflecting the confounder distribution in the target population); prediction at the modes (conditional predicted probabilities calculated by setting each confounder to its modal value); and prediction at the means (predicted probabilities calculated by setting each confounder to its mean value). That each method corresponds to a different target population is underappreciated in practice. Specifically, prediction at the means is often incorrectly interpreted as estimating average probabilities for the overall study population, and furthermore yields nonsensical estimates in the presen", "oa": true, "pdf_url": "https://academic.oup.com/ije/article-pdf/43/3/962/14152868/dyu029.pdf", "local_pdf": "", "api": ""}, {"title": "robustlmm : An R Package for Robust Estimation of Linear Mixed-Effects Models", "doi": "https://doi.org/10.18637/jss.v075.i06", "year": 2016, "authors": ["Manuel Koller"], "source": "Journal of Statistical Software", "cited": 736, "abstract": "As any real-life data, data modeled by linear mixed-effects models often contain outliers or other contamination. Even little contamination can drive the classic estimates far away from what they would be without the contamination. At the same time, datasets that require mixed-effects modeling are often complex and large. This makes it difficult to spot contamination. Robust estimation methods aim to solve both problems: to provide estimates where contamination has only little influence and to detect and flag contamination. We introduce an R package, robustlmm, to robustly fit linear mixed-effects models. The package's functions and methods are designed to closely equal those offered by lme4, the R package that implements classic linear mixed-effects model estimation in R. The robust estim", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v075i06/v75i06.pdf", "local_pdf": "076_robustlmm _ An R Package for Robust Esti.pdf", "api": ""}, {"title": "Relative Importance for Linear Regression in R: The Package relaimpo", "doi": null, "year": 2006, "authors": ["Ulrike Groemping"], "source": "RePEc: Research Papers in Economics", "cited": 726, "abstract": "Relative importance is a topic that has seen a lot of interest in recent years, particularly in applied work. The R package relaimpo implements six different metrics for assessing relative importance of regressors in the linear model, two of which are recommended - averaging over orderings of regressors and a newly proposed metric (Feldman 2005) called pmvd. Apart from delivering the metrics themselves, relaimpo also provides (exploratory) bootstrap confidence intervals. This paper offers a brief tutorial introduction to the package. The methods and relaimpo's functionality are illustrated using the data set swiss that is generally available in R. The paper targets readers who have a basic understanding of multiple linear regression. For the background of more advanced aspects, references ", "oa": true, "pdf_url": "http://www.jstatsoft.org/v17/i01/paper", "local_pdf": "077_Relative Importance for Linear Regressio.pdf", "api": ""}, {"title": "Functional linear regression analysis for longitudinal data", "doi": "https://doi.org/10.1214/009053605000000660", "year": 2005, "authors": ["Fang Yao", "Hans‐Georg Müller", "Jane-Ling Wang"], "source": "The Annals of Statistics", "cited": 716, "abstract": "We propose nonparametric methods for functional linear regression which are designed for sparse longitudinal data, where both the predictor and response are functions of a covariate such as time. Predictor and response processes have smooth random trajectories, and the data consist of a small number of noisy repeated measurements made at irregular times for a sample of subjects. In longitudinal studies, the number of repeated measurements per subject is often small and may be modeled as a discrete random number and, accordingly, only a finite and asymptotically nonincreasing number of measurements are available for each subject or experimental unit. We propose a functional regression approach for this situation, using functional principal component analysis, where we estimate the functiona", "oa": true, "pdf_url": "https://doi.org/10.1214/009053605000000660", "local_pdf": "", "api": ""}, {"title": "Statistics review 14: Logistic regression.", "doi": "https://doi.org/10.1186/cc3045", "year": 2005, "authors": ["Viv Bewick", "Liz Cheek", "Jonathan Ball"], "source": "Critical Care", "cited": 713, "abstract": "This review introduces logistic regression, which is a method for modelling the dependence of a binary response variable on one or more explanatory variables. Continuous and categorical explanatory variables are considered.", "oa": true, "pdf_url": "https://ccforum.biomedcentral.com/counter/pdf/10.1186/cc3045", "local_pdf": "079_Statistics review 14_ Logistic regressio.pdf", "api": ""}, {"title": "Best practice guidance for linear mixed-effects models in psychological science", "doi": "https://doi.org/10.1016/j.jml.2020.104092", "year": 2020, "authors": ["Lotte Meteyard", "Robert Davies"], "source": "Journal of Memory and Language", "cited": 710, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jml.2020.104092", "local_pdf": "", "api": ""}, {"title": "Linear regression and the normality assumption", "doi": "https://doi.org/10.1016/j.jclinepi.2017.12.006", "year": 2017, "authors": ["Amand F. Schmidt", "Chris Finan"], "source": "Journal of Clinical Epidemiology", "cited": 700, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jclinepi.2017.12.006", "local_pdf": "056_A Review on Linear Regression Comprehens.pdf", "api": ""}, {"title": "Logistic Regression, AdaBoost and Bregman Distances", "doi": "https://doi.org/10.1023/a:1013912006537", "year": 2002, "authors": ["Michael Collins", "Robert E. Schapire", "Yoram Singer"], "source": "Machine Learning", "cited": 691, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1023/A:1013912006537.pdf", "local_pdf": "082_Logistic Regression, AdaBoost and Bregma.pdf", "api": ""}, {"title": "Intermediate and advanced topics in multilevel logistic regression analysis", "doi": "https://doi.org/10.1002/sim.7336", "year": 2017, "authors": ["Peter C. Austin", "Juan Merlo"], "source": "Statistics in Medicine", "cited": 678, "abstract": "Multilevel data occur frequently in health services, population and public health, and epidemiologic research. In such research, binary outcomes are common. Multilevel logistic regression models allow one to account for the clustering of subjects within clusters of higher-level units when estimating the effect of subject and cluster characteristics on subject outcomes. A search of the PubMed database demonstrated that the use of multilevel or hierarchical regression models is increasing rapidly. However, our impression is that many analysts simply use multilevel regression models to account for the nuisance of within-cluster homogeneity that is induced by clustering. In this article, we describe a suite of analyses that can complement the fitting of multilevel logistic regression models. T", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/sim.7336", "local_pdf": "", "api": ""}, {"title": "Common pitfalls in statistical analysis: Logistic regression", "doi": "https://doi.org/10.4103/picr.picr_87_17", "year": 2017, "authors": ["Priya Ranganathan", "C.S. Pramesh", "Rakesh Aggarwal"], "source": "Perspectives in Clinical Research", "cited": 669, "abstract": "Logistic regression analysis is a statistical technique to evaluate the relationship between various predictor variables (either categorical or continuous) and an outcome which is binary (dichotomous). In this article, we discuss logistic regression analysis and the limitations of this technique.", "oa": true, "pdf_url": "https://doi.org/10.4103/picr.picr_87_17", "local_pdf": "", "api": ""}, {"title": "Elastic Net Regularization Paths for All Generalized Linear Models", "doi": "https://doi.org/10.18637/jss.v106.i01", "year": 2023, "authors": ["J. Kenneth Tay", "Balasubramanian Narasimhan", "Trevor Hastie"], "source": "Journal of Statistical Software", "cited": 667, "abstract": "The lasso and elastic net are popular regularized regression models for supervised learning. Friedman, Hastie, and Tibshirani (2010) introduced a computationally efficient algorithm for computing the elastic net regularization path for ordinary least squares regression, logistic regression and multinomial logistic regression, while Simon, Friedman, Hastie, and Tibshirani (2011) extended this work to Cox models for right-censored data. We further extend the reach of the elastic net-regularized regression to all generalized linear model families, Cox models with (start, stop] data and strata, and a simplified version of the relaxed lasso. We also discuss convenient utility functions for measuring the performance of these fitted models.", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/download/v106i01/4459", "local_pdf": "085_Elastic Net Regularization Paths for All.pdf", "api": ""}, {"title": "Variable Bandwidth and Local Linear Regression Smoothers", "doi": "https://doi.org/10.1214/aos/1176348900", "year": 1992, "authors": ["Jianqing Fan", "Irène Gijbels"], "source": "The Annals of Statistics", "cited": 643, "abstract": "In this paper we introduce an appealing nonparametric method for estimating the mean regression function. The proposed method combines the ideas of local linear smoothers and variable bandwidth. Hence, it also inherits the advantages of both approaches. We give expressions for the conditional MSE and MISE of the estimator. Minimization of the MISE leads to an explicit formula for an optimal choice of the variable bandwidth. Moreover, the merits of considering a variable bandwidth are discussed. In addition, we show that the estimator does not have boundary effects, and hence does not require modifications at the boundary. The performance of a corresponding plug-in estimator is investigated. Simulations illustrate the proposed estimation method.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-20/issue-4/Variable-Bandwidth-and-Local-Linear-Regression-Smoothers/10.1214/aos/1176348900.pdf", "local_pdf": "", "api": ""}, {"title": "Linear regression", "doi": "https://doi.org/10.1002/wics.1198", "year": 2012, "authors": ["Xiaogang Su", "Xin Yan", "Chih‐Ling Tsai"], "source": "Wiley Interdisciplinary Reviews Computational Statistics", "cited": 639, "abstract": "Abstract Linear regression plays a fundamental role in statistical modeling. This article provides a step‐by‐step coverage of linear models in the order of model specification, model estimation, statistical inference, variable selection, model diagnosis, and prediction. Computation issues in linear regression and intimately relevant extensions of linear models are also discussed. WIREs Comput Stat 2012, 4:275–294. doi: 10.1002/wics.1198 This article is categorized under: Statistical Models > Linear Models Algorithms and Computational Methods > Least Squares", "oa": true, "pdf_url": "https://doi.org/10.1002/wics.1198", "local_pdf": "056_A Review on Linear Regression Comprehens.pdf", "api": ""}, {"title": "Beyond t test and ANOVA: applications of mixed-effects models for more rigorous statistical analysis in neuroscience research", "doi": "https://doi.org/10.1016/j.neuron.2021.10.030", "year": 2021, "authors": ["Zhaoxia Yu", "Michele Guindani", "Steven F. Grieco", "Lujia Chen", "Todd C. Holmes", "Xiangmin Xu"], "source": "Neuron", "cited": 604, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.neuron.2021.10.030", "local_pdf": "", "api": ""}, {"title": "The AIC model selection method applied to path analytic models compared using a d‐separation test", "doi": "https://doi.org/10.1890/12-0976.1", "year": 2012, "authors": ["Bill Shipley"], "source": "Ecology", "cited": 603, "abstract": "Classical path analysis is a statistical technique used to test causal hypotheses involving multiple variables without latent variables, assuming linearity, multivariate normality, and a sufficient sample size. The d-separation (d-sep) test is a generalization of path analysis that relaxes these assumptions. Although model selection using Akaike's information criterion (AIC) is well established for classical path analysis, this model selection technique has not yet been developed for d-sep tests. In this paper, I explain how to use the AIC statistic for d-sep tests, give a worked example, and include instructions (supplemental material) to implement the analysis in the R computing language.", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1890/12-0976.1", "local_pdf": "", "api": ""}, {"title": "Prediction in functional linear regression", "doi": "https://doi.org/10.1214/009053606000000830", "year": 2006, "authors": ["Tommaso Cai", "Peter Hall"], "source": "The Annals of Statistics", "cited": 585, "abstract": "There has been substantial recent work on methods for estimating the slope function in linear regression for functional data analysis. However, as in the case of more conventional finite-dimensional regression, much of the practical interest in the slope centers on its application for the purpose of prediction, rather than on its significance in its own right. We show that the problems of slope-function estimation, and of prediction from an estimator of the slope function, have very different characteristics. While the former is intrinsically nonparametric, the latter can be either nonparametric or semiparametric. In particular, the optimal mean-square convergence rate of predictors is n−1, where n denotes sample size, if the predictand is a sufficiently smooth function. In other cases, co", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-34/issue-5/Prediction-in-functional-linear-regression/10.1214/009053606000000830.pdf", "local_pdf": "", "api": ""}, {"title": "An Introduction to Linear Mixed-Effects Modeling in R", "doi": "https://doi.org/10.1177/2515245920960351", "year": 2021, "authors": ["Violet A. Brown"], "source": "Advances in Methods and Practices in Psychological Science", "cited": 576, "abstract": "This Tutorial serves as both an approachable theoretical introduction to mixed-effects modeling and a practical introduction to how to implement mixed-effects models in R. The intended audience is researchers who have some basic statistical knowledge, but little or no experience implementing mixed-effects models in R using their own data. In an attempt to increase the accessibility of this Tutorial, I deliberately avoid using mathematical terminology beyond what a student would learn in a standard graduate-level statistics course, but I reference articles and textbooks that provide more detail for interested readers. This Tutorial includes snippets of R code throughout; the data and R script used to build the models described in the text are available via OSF at https://osf.io/v6qag/ , so ", "oa": true, "pdf_url": "https://doi.org/10.1177/2515245920960351", "local_pdf": "", "api": ""}, {"title": "Model selection and model averaging in behavioural ecology: the utility of the IT-AIC framework", "doi": "https://doi.org/10.1007/s00265-010-1035-8", "year": 2010, "authors": ["Shane A. Richards", "Mark J. Whittingham", "Philip A. Stephens"], "source": "Behavioral Ecology and Sociobiology", "cited": 572, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/s00265-010-1035-8", "local_pdf": "033_AIC model selection using Akaike weights.pdf", "api": ""}, {"title": "Distributed Sparse Linear Regression", "doi": "https://doi.org/10.1109/tsp.2010.2055862", "year": 2010, "authors": ["Gonzalo Mateos", "Juan Andrés Bazerque", "Georgios B. Giannakis"], "source": "IEEE Transactions on Signal Processing", "cited": 565, "abstract": "The Lasso is a popular technique for joint estimation and continuous variable selection, especially well-suited for sparse and possibly under-determined linear regression problems. This paper develops algorithms to estimate the regression coefficients via Lasso when the training data are distributed across different agents, and their communication to a central processing unit is prohibited for e.g., communication cost or privacy reasons. A motivating application is explored in the context of wireless communications, whereby sensing cognitive radios collaborate to estimate the radio-frequency power spectrum density. Attaining different tradeoffs between complexity and convergence speed, three novel algorithms are obtained after reformulating the Lasso into a separable form, which is iterati", "oa": true, "pdf_url": "https://doi.org/10.1109/tsp.2010.2055862", "local_pdf": "", "api": ""}, {"title": "Weighted averaging, logistic regression and the Gaussian response model", "doi": "https://doi.org/10.1007/bf00032121", "year": 1986, "authors": ["Cajo J. F. ter Braak", "Caspar W. N. Looman"], "source": "Plant Ecology", "cited": 562, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/bf00032121", "local_pdf": "", "api": ""}, {"title": "Linear Regression Analysis", "doi": "https://doi.org/10.1142/6986", "year": 2009, "authors": ["Xin Yan", "Xiao Su"], "source": "WORLD SCIENTIFIC eBooks", "cited": 558, "abstract": "This volume presents in detail the fundamental theories of linear regression analysis and diagnosis, as well as the relevant statistical computing techniques so that readers are able to actually model the data using the methods and techniques described in the book. It covers the fundamental theories in linear regression analysis and is extremely useful for future research in this area. The examples of regression analysis using the Statistical Application System (SAS) are also included. This book is suitable for graduate students who are either majoring in statistics/biostatistics or using linear regression analysis substantially in their subject fields.", "oa": true, "pdf_url": "https://doi.org/10.1142/6986", "local_pdf": "056_A Review on Linear Regression Comprehens.pdf", "api": ""}, {"title": "Smoothing Parameter and Model Selection for General Smooth Models", "doi": "https://doi.org/10.6084/m9.figshare.3405673", "year": 2017, "authors": ["Simon N. Wood", "Natalya Pya", "Benjamin Säfken"], "source": "Figshare", "cited": 534, "abstract": "This article discusses a general framework for smoothing parameter estimation for models with regular likelihoods constructed in terms of unknown smooth functions of covariates. Gaussian random effects and parametric terms may also be present. By construction the method is numerically stable and convergent, and enables smoothing parameter uncertainty to be quantified. The latter enables us to fix a well known problem with AIC for such models, thereby improving the range of model selection tools available. The smooth functions are represented by reduced rank spline like smoothers, with associated quadratic penalties measuring function smoothness. Model estimation is by penalized likelihood maximization, where the smoothing parameters controlling the extent of penalization are estimated by L", "oa": true, "pdf_url": "https://figshare.com/articles/journal_contribution/Smoothing_parameter_and_model_selection_for_general_smooth_models/3405673", "local_pdf": "", "api": ""}, {"title": "The AIC model selection method applied to path analytic models compared using a d‐separation test", "doi": "10.1890/12-0976.1", "year": 2013, "authors": ["Bill Shipley"], "source": "Ecology", "cited": 532, "abstract": " Classical path analysis is a statistical technique used to test causal hypotheses involving multiple variables without latent variables, assuming linearity, multivariate normality, and a sufficient sample size. The d‐separation (d‐sep) test is a generalization of path analysis that relaxes these assumptions. Although model selection using Akaike's information criterion (AIC) is well established for classical path analysis, this model selection technique has not yet been developed for d‐sep tests. In this paper, I explain how to use the AIC statistic for d‐sep tests, give a worked example, and include instructions (supplemental material) to implement the analysis in the R computing language. ", "oa": false, "pdf_url": "", "local_pdf": "", "api": "crossref"}, {"title": "Linear regression analysis", "doi": "https://doi.org/10.5455/jmood.20130624120840", "year": 2013, "authors": ["Selim Kılıç"], "source": "Journal of Mood Disorders", "cited": 531, "abstract": "Linear regression is an approach to modeling the association between a numeric dependent variable y and one or more independent variables denoted X. The case of one explanatory variable in regression model is called simple linear regression. For more than one explanatory variable, then the model is called multiple linear regression. The dependent variable should be a numeric variable in linear regression. It is recommended at least 10 times as many cases as the number of independent variables in regression model. And a statistically significant regression analysis does not imply causal relationship between independent and dependent variables. [PBS 2013; 3(2.000): 90-2]", "oa": true, "pdf_url": "https://doi.org/10.5455/jmood.20130624120840", "local_pdf": "056_A Review on Linear Regression Comprehens.pdf", "api": ""}, {"title": "Diagnosing Multicollinearity of Logistic Regression Model", "doi": "https://doi.org/10.9734/ajpas/2019/v5i230132", "year": 2019, "authors": ["N. A. M. R. Senaviratna", "T.M.J.A. Cooray"], "source": "Asian Journal of Probability and Statistics", "cited": 524, "abstract": "One of the key problems arises in binary logistic regression model is that explanatory variables being considered for the logistic regression model are highly correlated among themselves. Multicollinearity will cause unstable estimates and inaccurate variances that affects confidence intervals and hypothesis tests. Aim of this was to discuss some diagnostic measurements to detect multicollinearity namely tolerance, Variance Inflation Factor (VIF), condition index and variance proportions. The adapted diagnostics are illustrated with data based on a study of road accidents. Secondary data used from 2014 to 2016 in this study were acquired from the Traffic Police headquarters, Colombo in Sri Lanka. The response variable is accident severity that consists of two levels particularly grievous a", "oa": true, "pdf_url": "https://doi.org/10.9734/ajpas/2019/v5i230132", "local_pdf": "", "api": ""}]}, "design_of_experiments": {"cn": "试验设计", "items": [{"title": "Fitting Linear Mixed-Effects Models Using lme4", "doi": "https://doi.org/10.18637/jss.v067.i01", "year": 2015, "authors": ["Douglas M. Bates", "Martin Mächler", "Benjamin M. Bolker", "Steve Walker"], "source": "Journal of Statistical Software", "cited": 88651, "abstract": "Maximum likelihood or restricted maximum likelihood (REML) estimates of the parameters in linear mixed-effects models can be determined using the lmer function in the lme4 package for R. As for most model-fitting functions in R, the model is described in an lmer call by a formula, in this case including both fixed- and random-effects terms. The formula and data together determine a numerical representation of the model from which the profiled deviance or the profiled REML criterion can be evaluated as a function of some of the model parameters. The appropriate criterion is optimized, using one of the constrained optimization functions in R, to provide the parameter estimates. We describe the structure of the model, the steps in evaluating the profiled deviance or REML criterion, and the st", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v067i01/v67i01.pdf", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "G*Power 3: A flexible statistical power analysis program for the social, behavioral, and biomedical sciences", "doi": "https://doi.org/10.3758/bf03193146", "year": 2007, "authors": ["Franz Faul", "Edgar Erdfelder", "Albert-Georg Lang", "Axel Buchner"], "source": "Behavior Research Methods", "cited": 65949, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758%2FBF03193146.pdf", "local_pdf": "001_G_Power 3_ A flexible statistical power .pdf", "api": ""}, {"title": "lmerTest Package: Tests in Linear Mixed Effects Models", "doi": "https://doi.org/10.18637/jss.v082.i13", "year": 2017, "authors": ["Alexandra Kuznetsova", "Per B. Brockhoff", "Rune Haubo Bojesen Christensen"], "source": "Journal of Statistical Software", "cited": 24483, "abstract": "One of the frequent questions by users of the mixed model function lmer of the lme4 package has been: How can I get p values for the F and t tests for objects returned by lmer? The lmerTest package extends the 'lmerMod' class of the lme4 package, by overloading the anova and summary functions by providing p values for tests for fixed effects. We have implemented the Satterthwaite's method for approximating degrees of freedom for the t and F tests. We have also implemented the construction of Type I - III ANOVA tables. Furthermore, one may also obtain the summary as well as the anova table using the Kenward-Roger approximation for denominator degrees of freedom (based on the KRmodcomp function from the pbkrtest package). Some other convenient mixed model analysis tools such as a step method", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v082i13/v82i13.pdf", "local_pdf": "002_lmerTest Package_ Tests in Linear Mixed .pdf", "api": ""}, {"title": "Risks and Benefits of Estrogen Plus Progestin in Healthy Postmenopausal Women: Principal Results From the Women's Health Initiative Randomized Controlled Trial", "doi": "https://doi.org/10.1001/jama.288.3.321", "year": 2002, "authors": ["Writing Group for the Women's Health Initiative Investigators"], "source": "JAMA", "cited": 15932, "abstract": "CONTEXT: Despite decades of accumulated observational evidence, the balance of risks and benefits for hormone use in healthy postmenopausal women remains uncertain. OBJECTIVE: To assess the major health benefits and risks of the most commonly used combined hormone preparation in the United States. DESIGN: Estrogen plus progestin component of the Women's Health Initiative, a randomized controlled primary prevention trial (planned duration, 8.5 years) in which 16608 postmenopausal women aged 50-79 years with an intact uterus at baseline were recruited by 40 US clinical centers in 1993-1998. INTERVENTIONS: Participants received conjugated equine estrogens, 0.625 mg/d, plus medroxyprogesterone acetate, 2.5 mg/d, in 1 tablet (n = 8506) or placebo (n = 8102). MAIN OUTCOMES MEASURES: The primary ", "oa": true, "pdf_url": "https://jamanetwork.com/journals/jama/articlepdf/195120/joc21036.pdf", "local_pdf": "", "api": ""}, {"title": "An Overview of CMIP5 and the Experiment Design", "doi": "https://doi.org/10.1175/bams-d-11-00094.1", "year": 2011, "authors": ["Karl E. Taylor", "Ronald J. Stouffer", "Gerald A. Meehl"], "source": "Bulletin of the American Meteorological Society", "cited": 14821, "abstract": "The fifth phase of the Coupled Model Intercomparison Project (CMIP5) will produce a state-of-the- art multimodel dataset designed to advance our knowledge of climate variability and climate change. Researchers worldwide are analyzing the model output and will produce results likely to underlie the forthcoming Fifth Assessment Report by the Intergovernmental Panel on Climate Change. Unprecedented in scale and attracting interest from all major climate modeling groups, CMIP5 includes “long term” simulations of twentieth-century climate and projections for the twenty-first century and beyond. Conventional atmosphere–ocean global climate models and Earth system models of intermediate complexity are for the first time being joined by more recently developed Earth system models under an experime", "oa": true, "pdf_url": "https://journals.ametsoc.org/downloadpdf/journals/bams/93/4/bams-d-11-00094.1.pdf", "local_pdf": "", "api": ""}, {"title": "Combining theory and experiment in electrocatalysis: Insights into materials design", "doi": "https://doi.org/10.1126/science.aad4998", "year": 2017, "authors": ["Zhi Wei Seh", "Jakob Kibsgaard", "Colin F. Dickens", "Ib Chorkendorff", "Jens K. Nørskov", "Thomas F. Jaramillo"], "source": "Science", "cited": 12084, "abstract": "Electrocatalysis plays a central role in clean energy conversion, enabling a number of sustainable processes for future technologies. This review discusses design strategies for state-of-the-art heterogeneous electrocatalysts and associated materials for several different electrochemical transformations involving water, hydrogen, and oxygen, using theory as a means to rationalize catalyst performance. By examining the common principles that govern catalysis for different electrochemical reactions, we describe a systematic framework that clarifies trends in catalyzing these reactions, serving as a guide to new catalyst development while highlighting key gaps that need to be addressed. We conclude by extending this framework to emerging clean energy reactions such as hydrogen peroxide produc", "oa": true, "pdf_url": "https://doi.org/10.1126/science.aad4998", "local_pdf": "", "api": ""}, {"title": "Calculating and reporting effect sizes to facilitate cumulative science: a practical primer for t-tests and ANOVAs", "doi": "https://doi.org/10.3389/fpsyg.2013.00863", "year": 2013, "authors": ["Daniël Lakens"], "source": "Frontiers in Psychology", "cited": 10388, "abstract": "Effect sizes are the most important outcome of empirical studies. Most articles on effect sizes highlight their importance to communicate the practical significance of results. For scientists themselves, effect sizes are most useful because they facilitate cumulative science. Effect sizes can be used to determine the sample size for follow-up studies, or examining effects across studies. This article aims to provide a practical primer on how to calculate and report effect sizes for t-tests and ANOVA's such that effect sizes can be used in a-priori power analyses and meta-analyses. Whereas many articles about effect sizes focus on between-subjects designs and address within-subjects designs only briefly, I provide a detailed overview of the similarities and differences between within- and b", "oa": true, "pdf_url": "https://www.frontiersin.org/articles/10.3389/fpsyg.2013.00863/pdf", "local_pdf": "006_Calculating and reporting effect sizes t.pdf", "api": ""}, {"title": "z-Tree: Zurich toolbox for ready-made economic experiments", "doi": "https://doi.org/10.1007/s10683-006-9159-4", "year": 2007, "authors": ["Urs Fischbacher"], "source": "Experimental Economics", "cited": 9988, "abstract": "Abstract z-Tree (Zurich Toolbox for Ready-made Economic Experiments) is a software for developing and conducting economic experiments. The software is stable and allows programming almost any kind of experiments in a short time. In this article, I present the guiding principles behind the software design, its features, and its limitations.", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/s10683-006-9159-4.pdf", "local_pdf": "007_z-Tree_ Zurich toolbox for ready-made ec.pdf", "api": ""}, {"title": "Applied Linear Statistical Models", "doi": "https://doi.org/10.1080/00401706.1997.10485141", "year": 1997, "authors": ["Michael Kutner", "Nachtsheim, Christopher J.", "Neter, John", "Li, William"], "source": "Technometrics", "cited": 7266, "abstract": "Applied Linear Statistical Models 5e is the long established leading authoritative text and reference on statistical modeling. The text includes brief introductory and review material, and then proceeds through regression and modeling for the first half, and through ANOVA and Experimental Design in the second half. All topics are presented in a precise and clear style supported with solved examples, numbered formulae, graphic illustrations, and Notes to provide depth and statistical accuracy and precision. The Fifth edition provides an increased use of computing and graphical analysis throughout, without sacrificing concepts or rigor. In general, the 5e uses larger data sets in examples and exercises, and where methods can be automated within software without loss of understanding, it is s", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/abs/10.1080/00401706.1997.10485141", "local_pdf": "", "api": ""}, {"title": "Design and Analysis of Computer Experiments", "doi": "https://doi.org/10.1214/ss/1177012413", "year": 1989, "authors": ["Jerome Sacks", "William J. Welch", "Toby J. Mitchell", "Henry P. Wynn"], "source": "Statistical Science", "cited": 7012, "abstract": "Many scientific phenomena are now investigated by complex computer models or codes. A computer experiment is a number of runs of the code with various inputs. A feature of many computer experiments is that the output is deterministic--rerunning the code with the same inputs gives identical observations. Often, the codes are computationally expensive to run, and a common objective of an experiment is to fit a cheaper predictor of the output to the data. Our approach is to model the deterministic output as the realization of a stochastic process, thereby providing a statistical basis for designing experiments (choosing the inputs) for efficient prediction. With this model, estimates of uncertainty of predictions are also available. Recent work in this area is reviewed, a number of applicatio", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-4/issue-4/Design-and-Analysis-of-Computer-Experiments/10.1214/ss/1177012413.pdf", "local_pdf": "", "api": ""}, {"title": "A Randomized Trial of Intensive versus Standard Blood-Pressure Control", "doi": "https://doi.org/10.1056/nejmoa1511939", "year": 2015, "authors": ["The SPRINT Research Group"], "source": "New England Journal of Medicine", "cited": 6341, "abstract": "BACKGROUND: The most appropriate targets for systolic blood pressure to reduce cardiovascular morbidity and mortality among persons without diabetes remain uncertain. METHODS: We randomly assigned 9361 persons with a systolic blood pressure of 130 mm Hg or higher and an increased cardiovascular risk, but without diabetes, to a systolic blood-pressure target of less than 120 mm Hg (intensive treatment) or a target of less than 140 mm Hg (standard treatment). The primary composite outcome was myocardial infarction, other acute coronary syndromes, stroke, heart failure, or death from cardiovascular causes. RESULTS: At 1 year, the mean systolic blood pressure was 121.4 mm Hg in the intensive-treatment group and 136.2 mm Hg in the standard-treatment group. The intervention was stopped early aft", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJMoa1511939?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Reliability of the PEDro Scale for Rating Quality of Randomized Controlled Trials", "doi": "https://doi.org/10.1093/ptj/83.8.713", "year": 2003, "authors": ["Christopher G. Maher", "Catherine Sherrington", "Rob Herbert", "Anne M. Moseley", "Mark R. Elkins"], "source": "Physical Therapy", "cited": 4827, "abstract": "BACKGROUND AND PURPOSE: Assessment of the quality of randomized controlled trials (RCTs) is common practice in systematic reviews. However, the reliability of data obtained with most quality assessment scales has not been established. This report describes 2 studies designed to investigate the reliability of data obtained with the Physiotherapy Evidence Database (PEDro) scale developed to rate the quality of RCTs evaluating physical therapist interventions. METHOD: In the first study, 11 raters independently rated 25 RCTs randomly selected from the PEDro database. In the second study, 2 raters rated 120 RCTs randomly selected from the PEDro database, and disagreements were resolved by a third rater; this generated a set of individual rater and consensus ratings. The process was repeated by", "oa": true, "pdf_url": "https://academic.oup.com/ptj/article-pdf/83/8/713/31666439/ptj0713.pdf", "local_pdf": "", "api": ""}, {"title": "Design of Experiments", "doi": "https://doi.org/10.1136/bmj.1.3923.554-a", "year": 1936, "authors": ["Ronald Aylmer Fisher"], "source": "BMJ", "cited": 4221, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1136/bmj.1.3923.554-a", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Randomized, Controlled Trials, Observational Studies, and the Hierarchy of Research Designs", "doi": "https://doi.org/10.1056/nejm200006223422507", "year": 2000, "authors": ["John Concato", "Nirav R. Shah", "Ralph I. Horwitz"], "source": "New England Journal of Medicine", "cited": 3571, "abstract": "BACKGROUND: In the hierarchy of research designs, the results of randomized, controlled trials are considered to be evidence of the highest grade, whereas observational studies are viewed as having less validity because they reportedly overestimate treatment effects. We used published meta-analyses to identify randomized clinical trials and observational studies that examined the same clinical topics. We then compared the results of the original reports according to the type of research design. METHODS: A search of the Medline data base for articles published in five major medical journals from 1991 to 1995 identified meta-analyses of randomized, controlled trials and meta-analyses of either cohort or case-control studies that assessed the same intervention. For each of five topics, summar", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJM200006223422507?articleTools=true", "local_pdf": "", "api": ""}, {"title": "A Randomized Controlled Trial of Surgery for Temporal Lobe Epilepsy", "doi": "https://doi.org/10.1056/nejm200108023450501", "year": 2001, "authors": ["Samuel Wiebe", "Warren T. Blume", "John P. Girvin", "Michael Eliasziw"], "source": "New England Journal of Medicine", "cited": 3540, "abstract": "BACKGROUND: Randomized trials of surgery for epilepsy have not been conducted, because of the difficulties involved in designing and implementing feasible studies. The lack of data supporting the therapeutic usefulness of surgery precludes making strong recommendations for patients with epilepsy. We conducted a randomized, controlled trial to assess the efficacy and safety of surgery for temporal-lobe epilepsy. METHODS: Eighty patients with temporal-lobe epilepsy were randomly assigned to surgery (40 patients) or treatment with antiepileptic drugs for one year (40 patients). Optimal medical therapy and primary outcomes were assessed by epileptologists who were unaware of the patients' treatment assignments. The primary outcome was freedom from seizures that impair awareness of self and sur", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJM200108023450501?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Cognitive Stimulation in Patients with Dementia: Randomized Controlled Trial", "doi": "https://doi.org/10.1159/000353457", "year": 2013, "authors": ["Daniela Mapelli", "Elisa Di Rosa", "Rosaria Nocita", "Donatella Sava"], "source": "Dementia and Geriatric Cognitive Disorders Extra", "cited": 3466, "abstract": "A new Geriatric Depression Scale (GDS) designed specifically for rating depression in the elderly was tested for reliability and validity and compared with the Hamilton Rating Scale for Depression (HRS-D) and the Zung Self-Rating Depression Scale (SDS). In constructing the GDS a 100-item questionnaire was administered to normal and severely depressed subjects. The 30 questions most highly correlated with the total scores were then selected and readministered to new groups of elderly subjects. These subjects were classified as normal, mildly depressed or severely depressed on the basis of Research Diagnostic Criteria (RDC) for depression. The GDS, HRS-D and SDS were all found to be internally consistent measures, and each of the scales was correlated with the subject's number of RDC symptom", "oa": true, "pdf_url": "https://www.karger.com/Article/Pdf/353457", "local_pdf": "", "api": ""}, {"title": "Design and Analysis of Experiments", "doi": "https://doi.org/10.1007/978-3-319-52250-0", "year": 2017, "authors": ["Angela Dean", "Daniel Voss", "Danel Draguljić"], "source": "Springer texts in statistics", "cited": 2936, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/978-3-319-52250-0", "local_pdf": "", "api": ""}, {"title": "Delivering Cognitive Behavior Therapy to Young Adults With Symptoms of Depression and Anxiety Using a Fully Automated Conversational Agent (Woebot): A Randomized Controlled Trial", "doi": "https://doi.org/10.2196/mental.7785", "year": 2017, "authors": ["Kathleen Kara Fitzpatrick", "Alison Darcy", "Molly Vierhile"], "source": "JMIR Mental Health", "cited": 2780, "abstract": "Background Web-based cognitive-behavioral therapeutic (CBT) apps have demonstrated efficacy but are characterized by poor adherence. Conversational agents may offer a convenient, engaging way of getting support at any time. Objective The objective of the study was to determine the feasibility, acceptability, and preliminary efficacy of a fully automated conversational agent to deliver a self-help program for college students who self-identify as having symptoms of anxiety and depression. Methods In an unblinded trial, 70 individuals age 18-28 years were recruited online from a university community social media site and were randomized to receive either 2 weeks (up to 20 sessions) of self-help content derived from CBT principles in a conversational format with a text-based conversational ag", "oa": true, "pdf_url": "https://mental.jmir.org/2017/2/e19/PDF", "local_pdf": "", "api": ""}, {"title": "A Randomized, Controlled Trial of Methylprednisolone or Naloxone in the Treatment of Acute Spinal-Cord Injury", "doi": "https://doi.org/10.1056/nejm199005173222001", "year": 1990, "authors": ["Michael B. Bracken", "M J Shepard", "William F. Collins", "Theodore R. Holford", "Wise Young", "David S. Baskin"], "source": "New England Journal of Medicine", "cited": 2760, "abstract": "Studies in animals indicate that methylprednisolone and naloxone are both potentially beneficial in acute spinal-cord injury, but whether any treatment is clinically effective remains uncertain. We evaluated the efficacy and safety of methylprednisolone and naloxone in a multicenter randomized, double-blind, placebo-controlled trial in patients with acute spinal-cord injury, 95 percent of whom were treated within 14 hours of injury. Methylprednisolone was given to 162 patients as a bolus of 30 mg per kilogram of body weight, followed by infusion at 5.4 mg per kilogram per hour for 23 hours. Naloxone was given to 154 patients as a bolus of 5.4 mg per kilogram, followed by infusion at 4.0 mg per kilogram per hour for 23 hours. Placebos were given to 171 patients by bolus and infusion. Motor ", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJM199005173222001?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Symptom Monitoring With Patient-Reported Outcomes During Routine Cancer Treatment: A Randomized Controlled Trial", "doi": "https://doi.org/10.1200/jco.2015.63.0830", "year": 2015, "authors": ["Ethan Basch", "Allison M. Deal", "Mark G. Kris", "Howard I. Scher", "Clifford A. Hudis", "Paul Sabbatini"], "source": "Journal of Clinical Oncology", "cited": 2710, "abstract": "PURPOSE: There is growing interest to enhance symptom monitoring during routine cancer care using patient-reported outcomes, but evidence of impact on clinical outcomes is limited. METHODS: We randomly assigned patients receiving routine outpatient chemotherapy for advanced solid tumors at Memorial Sloan Kettering Cancer Center to report 12 common symptoms via tablet computers or to receive usual care consisting of symptom monitoring at the discretion of clinicians. Those with home computers received weekly e-mail prompts to report between visits. Treating physicians received symptom printouts at visits, and nurses received e-mail alerts when participants reported severe or worsening symptoms. The primary outcome was change in health-related quality of life (HRQL) at 6 months compared with", "oa": true, "pdf_url": "https://doi.org/10.1200/jco.2015.63.0830", "local_pdf": "", "api": ""}, {"title": "A Randomized, Controlled Trial of 3.0 mg of Liraglutide in Weight Management", "doi": "https://doi.org/10.1056/nejmoa1411892", "year": 2015, "authors": ["F. Xavier Pi‐Sunyer", "Arne Astrup", "Ken Fujioka", "Frank L. Greenway", "Alfredo Halpern", "Michel Krempf"], "source": "New England Journal of Medicine", "cited": 2684, "abstract": "BACKGROUND: Obesity is a chronic disease with serious health consequences, but weight loss is difficult to maintain through lifestyle intervention alone. Liraglutide, a glucagon-like peptide-1 analogue, has been shown to have potential benefit for weight management at a once-daily dose of 3.0 mg, injected subcutaneously. METHODS: We conducted a 56-week, double-blind trial involving 3731 patients who did not have type 2 diabetes and who had a body-mass index (BMI; the weight in kilograms divided by the square of the height in meters) of at least 30 or a BMI of at least 27 if they had treated or untreated dyslipidemia or hypertension. We randomly assigned patients in a 2:1 ratio to receive once-daily subcutaneous injections of liraglutide at a dose of 3.0 mg (2487 patients) or placebo (1244 ", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJMoa1411892?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Randomized controlled trial of transarterial lipiodol chemoembolization for unresectable hepatocellular carcinoma", "doi": "https://doi.org/10.1053/jhep.2002.33156", "year": 2002, "authors": ["Chung‐Mau Lo", "Hys Ngan", "Wai‐Kuen Tso", "Chi‐Leung Liu", "Chi‐Ming Lam", "Ronnie Tung‐Ping Poon"], "source": "Hepatology", "cited": 2639, "abstract": "This randomized, controlled trial assessed the efficacy of transarterial Lipiodol (Lipiodol Ultrafluide, Laboratoire Guerbet, Aulnay-Sous-Bois, France) chemoembolization in patients with unresectable hepatocellular carcinoma. From March 1996 to October 1997, 80 out of 279 Asian patients with newly diagnosed unresectable hepatocellular carcinoma fulfilled the entry criteria and randomly were assigned to treatment with chemoembolization using a variable dose of an emulsion of cisplatin in Lipiodol and gelatin-sponge particles injected through the hepatic artery (chemoembolization group, 40 patients) or symptomatic treatment (control group, 40 patients). One patient assigned to the control group secondarily was excluded because of unrecognized systemic metastasis. Chemoembolization was repeat", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1053/jhep.2002.33156", "local_pdf": "", "api": ""}, {"title": "Randomized, Controlled Trial of an Intervention for Toddlers With Autism: The Early Start Denver Model", "doi": "https://doi.org/10.1542/peds.2009-0958", "year": 2009, "authors": ["Géraldine Dawson", "Sally J. Rogers", "Jeffrey Munson", "Milani Smith", "Jamie Winter", "Jessica Greenson"], "source": "PEDIATRICS", "cited": 2609, "abstract": "OBJECTIVE: To conduct a randomized, controlled trial to evaluate the efficacy of the Early Start Denver Model (ESDM), a comprehensive developmental behavioral intervention, for improving outcomes of toddlers diagnosed with autism spectrum disorder (ASD). METHODS: Forty-eight children diagnosed with ASD between 18 and 30 months of age were randomly assigned to 1 of 2 groups: (1) ESDM intervention, which is based on developmental and applied behavioral analytic principles and delivered by trained therapists and parents for 2 years; or (2) referral to community providers for intervention commonly available in the community. RESULTS: Compared with children who received community-intervention, children who received ESDM showed significant improvements in IQ, adaptive behavior, and autism diagno", "oa": true, "pdf_url": "https://doi.org/10.1542/peds.2009-0958", "local_pdf": "", "api": ""}, {"title": "Some aspects of the sequential design of experiments", "doi": "https://doi.org/10.1090/s0002-9904-1952-09620-8", "year": 1952, "authors": ["Herbert Robbins"], "source": "Bulletin of the American Mathematical Society", "cited": 2239, "abstract": "Introduction.Until recently, statistical theory has been restricted to the design and analysis of sampling experiments in which the size and composition of the samples are completely determined before the experimentation begins.The reasons for this are partly historical, dating back to the time when the statistician was consulted, if at all, only after the experiment was over, and partly intrinsic in the mathematical difficulty of working with anything but a fixed number of independent random variables.A major advance now appears to be in the making with the creation of a theory of the sequential design of experiments, in which the size and composition of the samples are not fixed in advance but are functions of the observations themselves.The first important departure from fixed sample si", "oa": true, "pdf_url": "https://www.ams.org/bull/1952-58-05/S0002-9904-1952-09620-8/S0002-9904-1952-09620-8.pdf", "local_pdf": "", "api": ""}, {"title": "A Phase 3, Randomized, Controlled Trial of Resmetirom in NASH with Liver Fibrosis", "doi": "https://doi.org/10.1056/nejmoa2309000", "year": 2024, "authors": ["Stephen A. Harrison", "Pierre Bédossa", "Cynthia D. Guy", "Jörn M. Schattenberg", "Rohit Loomba", "Rebecca Taub"], "source": "New England Journal of Medicine", "cited": 1935, "abstract": "BACKGROUND: Nonalcoholic steatohepatitis (NASH) is a progressive liver disease with no approved treatment. Resmetirom is an oral, liver-directed, thyroid hormone receptor beta-selective agonist in development for the treatment of NASH with liver fibrosis. METHODS: We are conducting an ongoing phase 3 trial involving adults with biopsy-confirmed NASH and a fibrosis stage of F1B, F2, or F3 (stages range from F0 [no fibrosis] to F4 [cirrhosis]). Patients were randomly assigned in a 1:1:1 ratio to receive once-daily resmetirom at a dose of 80 mg or 100 mg or placebo. The two primary end points at week 52 were NASH resolution (including a reduction in the nonalcoholic fatty liver disease [NAFLD] activity score by ≥2 points; scores range from 0 to 8, with higher scores indicating more severe dis", "oa": true, "pdf_url": "https://doi.org/10.1056/nejmoa2309000", "local_pdf": "", "api": ""}, {"title": "Understanding and misunderstanding randomized controlled trials", "doi": "https://doi.org/10.1016/j.socscimed.2017.12.005", "year": 2017, "authors": ["Angus Deaton", "Nancy Cartwright"], "source": "Social Science & Medicine", "cited": 1868, "abstract": "Randomized Controlled Trials (RCTs) are increasingly popular in the social sciences, not only in medicine. We argue that the lay public, and sometimes researchers, put too much trust in RCTs over other methods of investigation. Contrary to frequent claims in the applied literature, randomization does not equalize everything other than the treatment in the treatment and control groups, it does not automatically deliver a precise estimate of the average treatment effect (ATE), and it does not relieve us of the need to think about (observed or unobserved) covariates. Finding out whether an estimate was generated by chance is more difficult than commonly believed. At best, an RCT yields an unbiased estimate, but this property is of limited practical value. Even then, estimates apply only to th", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/am/pii/S0277953617307359?via%3Dihub", "local_pdf": "", "api": ""}, {"title": "Statistical design and analysis for a 'biological effects' study", "doi": "https://doi.org/10.3354/meps046213", "year": 1988, "authors": ["KR Clarke", "RH Green"], "source": "Marine Ecology Progress Series", "cited": 1781, "abstract": "Statistical aspects of 'biological effects' field surveys are discussed, with particular reference to the GEEP Workshop.Recommendations are made on design criteria, for example, selection of sites and samples, and replication strategies (including formulae for sample size determination) The role of transforinations is discussed, both for univariate sub-lethal response data and the mulbvariate data arising from benthic community studies.Statistical analysis is categorised into testing methods, for establishing biological differences between field sites, and descriptive techniques, for representation of those differences.The former includes a non-parametric randomisation test for use with site-species arrays and the latter a survey of various multivariate ordination and clustering methods A ", "oa": true, "pdf_url": "https://doi.org/10.3354/meps046213", "local_pdf": "001_G_Power 3_ A flexible statistical power .pdf", "api": ""}, {"title": "Aerobic Exercise and Neurocognitive Performance: A Meta-Analytic Review of Randomized Controlled Trials", "doi": "https://doi.org/10.1097/psy.0b013e3181d14633", "year": 2010, "authors": ["Patrick J. Smith", "James A. Blumenthal", "Benson M. Hoffman", "Harris Cooper", "Timothy A. Strauman", "Kathleen A. Welsh‐Bohmer"], "source": "Psychosomatic Medicine", "cited": 1723, "abstract": "OBJECTIVES: To assess the effects of aerobic exercise training on neurocognitive performance. Although the effects of exercise on neurocognition have been the subject of several previous reviews and meta-analyses, they have been hampered by methodological shortcomings and are now outdated as a result of the recent publication of several large-scale, randomized, controlled trials (RCTs). METHODS: We conducted a systematic literature review of RCTs examining the association between aerobic exercise training on neurocognitive performance between January 1966 and July 2009. Suitable studies were selected for inclusion according to the following criteria: randomized treatment allocation; mean age > or =18 years of age; duration of treatment >1 month; incorporated aerobic exercise components; su", "oa": true, "pdf_url": "https://doi.org/10.1097/psy.0b013e3181d14633", "local_pdf": "", "api": ""}, {"title": "Evaluating Amazon's Mechanical Turk as a Tool for Experimental Behavioral Research", "doi": "https://doi.org/10.1371/journal.pone.0057410", "year": 2013, "authors": ["Matthew J. C. Crump", "John V. McDonnell", "Todd M. Gureckis"], "source": "PLoS ONE", "cited": 1695, "abstract": "Amazon Mechanical Turk (AMT) is an online crowdsourcing service where anonymous online workers complete web-based tasks for small sums of money. The service has attracted attention from experimental psychologists interested in gathering human subject data more efficiently. However, relative to traditional laboratory studies, many aspects of the testing environment are not under the experimenter's control. In this paper, we attempt to empirically evaluate the fidelity of the AMT system for use in cognitive behavioral experiments. These types of experiment differ from simple surveys in that they require multiple trials, sustained attention from participants, comprehension of complex instructions, and millisecond accuracy for response recording and stimulus presentation. We replicate a divers", "oa": true, "pdf_url": "https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0057410&type=printable", "local_pdf": "028_Evaluating Amazon's Mechanical Turk as a.pdf", "api": ""}, {"title": "SARS-CoV-2 mRNA vaccine design enabled by prototype pathogen preparedness", "doi": "https://doi.org/10.1038/s41586-020-2622-0", "year": 2020, "authors": ["Kizzmekia S. Corbett", "Darin K. Edwards", "Sarah R. Leist", "Olubukola M. Abiona", "Seyhan Boyoglu-Barnum", "Rebecca A. Gillespie"], "source": "Nature", "cited": 1689, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/s41586-020-2622-0.pdf", "local_pdf": "029_SARS-CoV-2 mRNA vaccine design enabled b.pdf", "api": ""}, {"title": "Design and validation of a tool for neurite tracing and analysis in fluorescence microscopy images", "doi": "https://doi.org/10.1002/cyto.a.20022", "year": 2004, "authors": ["Erik Meijering", "Mathews Jacob", "J.‐C. Floyd Sarria", "Pascal Steiner", "Harald Hirling", "Michaël Unser"], "source": "Cytometry Part A", "cited": 1687, "abstract": "BACKGROUND: For the investigation of the molecular mechanisms involved in neurite outgrowth and differentiation, accurate and reproducible segmentation and quantification of neuronal processes are a prerequisite. To facilitate this task, we developed a semiautomatic neurite tracing technique. This article describes the design and validation of the technique. METHODS: The technique was compared to fully manual delineation. Four observers repeatedly traced selected neurites in 20 fluorescence microscopy images of cells in culture, using both methods. Accuracy and reproducibility were determined by comparing the tracings to high-resolution reference tracings, using two error measures. Labor intensiveness was measured in numbers of mouse clicks required. The significance of the results was det", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/cyto.a.20022", "local_pdf": "", "api": ""}, {"title": "A Randomized, Controlled Trial of Ebola Virus Disease Therapeutics", "doi": "https://doi.org/10.1056/nejmoa1910993", "year": 2019, "authors": ["Sabué Mulangu", "Lori E. Dodd", "Richard T. Davey", "Olivier Tshiani Mbaya", "Michael A. Proschan", "Daniel Mukadi‐Bamuleka"], "source": "New England Journal of Medicine", "cited": 1656, "abstract": "BACKGROUND: Although several experimental therapeutics for Ebola virus disease (EVD) have been developed, the safety and efficacy of the most promising therapies need to be assessed in the context of a randomized, controlled trial. METHODS: We conducted a trial of four investigational therapies for EVD in the Democratic Republic of Congo, where an outbreak began in August 2018. Patients of any age who had a positive result for Ebola virus RNA on reverse-transcriptase-polymerase-chain-reaction assay were enrolled. All patients received standard care and were randomly assigned in a 1:1:1:1 ratio to intravenous administration of the triple monoclonal antibody ZMapp (the control group), the antiviral agent remdesivir, the single monoclonal antibody MAb114, or the triple monoclonal antibody REG", "oa": true, "pdf_url": "https://doi.org/10.1056/nejmoa1910993", "local_pdf": "", "api": ""}, {"title": "A Randomized Controlled Trial of the Tumor Necrosis Factor Antagonist Infliximab for Treatment-Resistant Depression", "doi": "https://doi.org/10.1001/2013.jamapsychiatry.4", "year": 2012, "authors": ["Charles L. Raison", "Robin E. Rutherford", "Bobbi J. Woolwine", "Shuo Chen", "Pamela J. Schettler", "Daniel Drake"], "source": "JAMA Psychiatry", "cited": 1610, "abstract": "CONTEXT: Increased concentrations of inflammatory biomarkers predict antidepressant nonresponse, and inflammatory cytokines can sabotage and circumvent the mechanisms of action of conventional antidepressants. OBJECTIVES: To determine whether inhibition of the inflammatory cytokine tumor necrosis factor (TNF) reduces depressive symptoms in patients with treatment-resistant depression and whether an increase in baseline plasma inflammatory biomarkers, including high-sensitivity C-reactive protein (hs-CRP), TNF, and its soluble receptors, predicts treatment response. DESIGN: Double-blind, placebo-controlled, randomized clinical trial. SETTING: Outpatient infusion center at Emory University in Atlanta, Georgia. PARTICIPANTS: A total of 60 medically stable outpatients with major depression who", "oa": true, "pdf_url": "https://doi.org/10.1001/2013.jamapsychiatry.4", "local_pdf": "", "api": ""}, {"title": "Non-normal data: Is ANOVA still a valid option?", "doi": "https://doi.org/10.7334/psicothema2016.383", "year": 2017, "authors": ["María J. Blanca", "Rafael Alarcón", "Jaume Arnau", "Roser Bono", "Rebecca Bendayan"], "source": "Psicothema", "cited": 1594, "abstract": "BACKGROUND: The robustness of F-test to non-normality has been studied from the 1930s through to the present day. However, this extensive body of research has yielded contradictory results, there being evidence both for and against its robustness. This study provides a systematic examination of F-test robustness to violations of normality in terms of Type I error, considering a wide variety of distributions commonly found in the health and social sciences. METHOD: We conducted a Monte Carlo simulation study involving a design with three groups and several known and unknown distributions. The manipulated variables were: Equal and unequal group sample sizes; group sample size and total sample size; coefficient of sample size variation; shape of the distribution and equal or unequal shapes of", "oa": true, "pdf_url": "https://doi.org/10.7334/psicothema2016.383", "local_pdf": "", "api": ""}, {"title": "GENES - a software package for analysis in experimental statistics and quantitative genetics - doi: 10.4025/actasciagron.v35i3.21251", "doi": "https://doi.org/10.4025/actasciagron.v35i3.21251", "year": 2013, "authors": ["Cosme Damião Cruz"], "source": "Acta Scientiarum Agronomy", "cited": 1574, "abstract": "GENES is a software package used for data analysis and processing with different biometric models and is essential in genetic studies applied to plant and animal breeding.It allows parameter estimation to analyze biological phenomena and is fundamental for the decision-making process and predictions of success and viability of selection strategies.The program can be downloaded from the Internet (http://www.ufv.br/dbg/genes/genes.htm or http://www.ufv.br/dbg/biodata.htm)and is available in Portuguese, English and Spanish.Specific literature (http://www.livraria.ufv.br/) and a set of sample files are also provided, making GENES easy to use.The software is integrated into the programs MS Word, MS Excel and Paint, ensuring simplicity and effectiveness in data import and export of results, figu", "oa": true, "pdf_url": "https://periodicos.uem.br/ojs/index.php/ActaSciAgron/article/download/21251/pdf", "local_pdf": "", "api": ""}, {"title": "A Randomized, Controlled Trial of the Use of Pulmonary-Artery Catheters in High-Risk Surgical Patients", "doi": "https://doi.org/10.1056/nejmoa021108", "year": 2003, "authors": ["J. Dean Sandham", "Russell D. Hull", "Rollin Brant", "Linda Knox", "Graham F. Pineo", "Christopher Doig"], "source": "New England Journal of Medicine", "cited": 1538, "abstract": "BACKGROUND: Some observational studies suggest that the use of pulmonary-artery catheters to guide therapy is associated with increased mortality. METHODS: We performed a randomized trial comparing goal-directed therapy guided by a pulmonary-artery catheter with standard care without the use of a pulmonary-artery catheter. The subjects were high-risk patients 60 years of age or older, with American Society of Anesthesiologists (ASA) class III or IV risk, who were scheduled for urgent or elective major surgery, followed by a stay in an intensive care unit. Outcomes were adjudicated by observers who were unaware of the treatment-group assignments. The primary outcome was in-hospital mortality from any cause. RESULTS: Of 3803 eligible patients, 1994 (52.4 percent) underwent randomization. The", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJMoa021108?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Fecal Microbiota Transplantation Induces Remission in Patients With Active Ulcerative Colitis in a Randomized Controlled Trial", "doi": "https://doi.org/10.1053/j.gastro.2015.04.001", "year": 2015, "authors": ["Paul Moayyedi", "Michael G. Surette", "Peter T. Kim", "Josie Libertucci", "Melanie Wolfe", "Catherine Onischi"], "source": "Gastroenterology", "cited": 1516, "abstract": "", "oa": true, "pdf_url": "https://www.gastrojournal.org/article/S0016-5085(15)00451-5/pdf", "local_pdf": "", "api": ""}, {"title": "Randomized controlled trial of screening for hepatocellular carcinoma", "doi": "https://doi.org/10.1007/s00432-004-0552-0", "year": 2004, "authors": ["Boheng Zhang", "Bing‐Hui Yang", "Zhao–You Tang"], "source": "Journal of Cancer Research and Clinical Oncology", "cited": 1498, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/s00432-004-0552-0", "local_pdf": "", "api": ""}, {"title": "Experimental design and analysis and their reporting II: updated and simplified guidance for authors and peer reviewers", "doi": "https://doi.org/10.1111/bph.14153", "year": 2018, "authors": ["Michael J. Curtis", "Steve Alexander", "Giuseppe Cirino", "James R. Docherty", "Christopher H George", "Mark A. Giembycz"], "source": "British Journal of Pharmacology", "cited": 1367, "abstract": "This article updates the guidance published in 2015 for authors submitting papers to British Journal of Pharmacology (Curtis et al., 2015) and is intended to provide the rubric for peer review. Thus, it is directed towards authors, reviewers and editors. Explanations for many of the requirements were outlined previously and are not restated here. The new guidelines are intended to replace those published previously. The guidelines have been simplified for ease of understanding by authors, to make it more straightforward for peer reviewers to check compliance and to facilitate the curation of the journal's efforts to improve standards.", "oa": true, "pdf_url": "https://bpspubs.onlinelibrary.wiley.com/doi/pdfdirect/10.1111/bph.14153", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "A Randomized, Controlled Trial of Corticosteroids in the Treatment of Acute Optic Neuritis", "doi": "https://doi.org/10.1056/nejm199202273260901", "year": 1992, "authors": ["Roy W. Beck", "Patricia A. Cleary", "Malcolm M. Anderson", "John L. Keltner", "William T. Shults", "David I. Kaufman"], "source": "New England Journal of Medicine", "cited": 1357, "abstract": "BACKGROUND AND METHODS: The use of corticosteroids to treat optic neuritis is controversial. At 15 clinical centers, we randomly assigned 457 patients with acute optic neuritis to receive oral prednisone (1 mg per kilogram of body weight per day) for 14 days; intravenous methylprednisolone (1 g per day) for 3 days, followed by oral prednisone (1 mg per kilogram per day) for 11 days; or oral placebo for 14 days. Visual function was assessed over a six-month follow-up period. RESULTS: Visual function recovered faster in the group receiving intravenous methylprednisolone than in the placebo group; this was particularly true for the reversal of visual-field defects (P = 0.0001). Although the differences between the groups decreased with time, at six months the group that received intravenous m", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJM199202273260901?articleTools=true", "local_pdf": "", "api": ""}, {"title": "Randomized Controlled Trial Testing the Effects of Weight Loss on Nonalcoholic Steatohepatitis", "doi": "https://doi.org/10.1002/hep.23276", "year": 2009, "authors": ["Kittichai Promrat", "David E. Kleiner", "Heather M. Niemeier", "Elizabeth H. Jackvony", "Marie Kearns", "Jack R. Wands"], "source": "Hepatology", "cited": 1337, "abstract": "UNLABELLED: Nonalcoholic steatohepatitis (NASH) is a chronic progressive liver disease that is strongly associated with obesity. Currently, there is no approved therapy for NASH. Weight reduction is typically recommended, but efficacy data are lacking. We performed a randomized controlled trial to examine the effects of lifestyle intervention using a combination of diet, exercise, and behavior modification, with a goal of 7% to 10% weight reduction, on clinical parameters of NASH. The primary outcome measure was the change in NASH histological activity score (NAS) after 48 weeks of intervention. Thirty-one overweight or obese individuals (body mass index [BMI], 25-40 kg/m(2)) with biopsy-proven NASH were randomized in a 2:1 ratio to receive intensive lifestyle intervention (LS) or structur", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hep.23276", "local_pdf": "", "api": ""}, {"title": "The Assistat Software Version 7.7 and its use in the analysis of experimental data", "doi": "https://doi.org/10.5897/ajar2016.11522", "year": 2016, "authors": ["de Assis Santos e Silva Francisco", "Alberto Vieira de Azevedo Carlos"], "source": "African Journal of Agricultural Research", "cited": 1219, "abstract": "Statistical programs are essential tools for those who deal with scientific research and need to analyze experimental data. In agriculture, there are often uncontrolled factors, which determine the necessity of statistical analyses of the data. The Assistat software version 7.7 is one of these tools and this study aimed to demonstrate its functionality and efficiency in the analyses of experimental data of agricultural research and evaluate its acceptance. In order to exemplify its utilization, data of agricultural experiments were analyzed using the models of analysis of variance for randomized block and factorial experiments. In addition, the regression was used in the analysis of variance for quantitative treatments. It was concluded that the software was used in many papers published i", "oa": true, "pdf_url": "https://academicjournals.org/journal/AJAR/article-full-text-pdf/5E8596460818", "local_pdf": "041_The Assistat Software Version 7.7 and it.pdf", "api": ""}, {"title": "Discrepancies between Meta-Analyses and Subsequent Large Randomized, Controlled Trials", "doi": "https://doi.org/10.1056/nejm199708213370806", "year": 1997, "authors": ["Jacques LeLorier", "Geneviève Grégoire", "A Aïssa Benhaddad", "J Lapierre", "F Derderian"], "source": "New England Journal of Medicine", "cited": 1188, "abstract": "BACKGROUND: Meta-analyses are now widely used to provide evidence to support clinical strategies. However, large randomized, controlled trials are considered the gold standard in evaluating the efficacy of clinical interventions. METHODS: We compared the results of large randomized, controlled trials (involving 1000 patients or more) that were published in four journals (the New England Journal of Medicine, the Lancet, the Annals of Internal Medicine, and the Journal of the American Medical Association) with the results of meta-analyses published earlier on the same topics. Regarding the principal and secondary outcomes, we judged whether the findings of the randomized trials agreed with those of the corresponding meta-analyses, and we determined whether the study results were positive (in", "oa": true, "pdf_url": "https://www.nejm.org/doi/pdf/10.1056/NEJM199708213370806?articleTools=true", "local_pdf": "", "api": ""}, {"title": "The revised JBI critical appraisal tool for the assessment of risk of bias for randomized controlled trials", "doi": "https://doi.org/10.11124/jbies-22-00430", "year": 2023, "authors": ["Timothy Hugh Barker", "Jennifer Stone", "Kim Sears", "Miloslav Klugar", "Cătălin Tufănaru", "Jo Leonardi‐Bee"], "source": "JBI Evidence Synthesis", "cited": 1155, "abstract": "JBI recently began the process of updating and revising its suite of critical appraisal tools to ensure that these tools remain compatible with recent developments within risk of bias science. Following a rigorous development process led by the JBI Effectiveness Methodology Group, this paper presents the revised critical appraisal tool for the assessment of risk of bias for randomized controlled trials. This paper also presents practical guidance on how the questions of this tool are to be interpreted and applied by systematic reviewers, while providing topical examples. We also discuss the major changes made to this tool compared to the previous version and justification for why these changes facilitate best-practice methodologies in this field.", "oa": true, "pdf_url": "https://doi.org/10.11124/jbies-22-00430", "local_pdf": "", "api": ""}, {"title": "Experiments - Planning, Analysis and Parameter Design Optimization", "doi": "https://doi.org/10.1093/tropej/47.2.126", "year": 2001, "authors": [], "source": "Journal of Tropical Pediatrics", "cited": 1132, "abstract": "This title is the latest addition to the comprehensive Wiley Series in Probability and Statistics.The authors, one from the Department of Statistics and Industrial and Operations Engineering of the University of Michigan and the other from the Statistical Sciences Group at", "oa": true, "pdf_url": "https://academic.oup.com/tropej/article-pdf/47/2/126/4755129/470126.pdf", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Design and analysis of ChIP-seq experiments for DNA-binding proteins", "doi": "https://doi.org/10.1038/nbt.1508", "year": 2008, "authors": ["Peter V. Kharchenko", "Michael Tolstorukov", "Peter J. Park"], "source": "Nature Biotechnology", "cited": 995, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1038/nbt.1508", "local_pdf": "", "api": ""}, {"title": "ANOVA-Like Differential Expression (ALDEx) Analysis for Mixed Population RNA-Seq", "doi": "https://doi.org/10.1371/journal.pone.0067019", "year": 2013, "authors": ["Andrew D. Fernandes", "Jean M. Macklaim", "Thomas Linn", "Gregor Reid", "Gregory B. Gloor"], "source": "PLoS ONE", "cited": 957, "abstract": "Experimental variance is a major challenge when dealing with high-throughput sequencing data. This variance has several sources: sampling replication, technical replication, variability within biological conditions, and variability between biological conditions. The high per-sample cost of RNA-Seq often precludes the large number of experiments needed to partition observed variance into these categories as per standard ANOVA models. We show that the partitioning of within-condition to between-condition variation cannot reasonably be ignored, whether in single-organism RNA-Seq or in Meta-RNA-Seq experiments, and further find that commonly-used RNA-Seq analysis tools, as described in the literature, do not enforce the constraint that the sum of relative expression levels must be one, and thu", "oa": true, "pdf_url": "https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0067019&type=printable", "local_pdf": "046_ANOVA-Like Differential Expression (ALDE.pdf", "api": ""}, {"title": "Survey of the Quality of Experimental Design, Statistical Analysis and Reporting of Research Using Animals", "doi": "https://doi.org/10.1371/journal.pone.0007824", "year": 2009, "authors": ["Carol Kilkenny", "Nick Parsons", "Ed Kadyszewski", "Michael F. W. Festing", "Innes C. Cuthill", "Derek Fry"], "source": "PLoS ONE", "cited": 878, "abstract": "For scientific, ethical and economic reasons, experiments involving animals should be appropriately designed, correctly analysed and transparently reported. This increases the scientific validity of the results, and maximises the knowledge gained from each experiment. A minimum amount of relevant information must be included in scientific publications to ensure that the methods and results of a study can be reviewed, analysed and repeated. Omitting essential information can raise scientific and ethical concerns. We report the findings of a systematic survey of reporting, experimental design and statistical analysis in published biomedical research using laboratory animals. Medline and EMBASE were searched for studies reporting research on live rats, mice and non-human primates carried out ", "oa": true, "pdf_url": "https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0007824&type=printable", "local_pdf": "047_Survey of the Quality of Experimental De.pdf", "api": ""}, {"title": "The Hat Matrix in Regression and ANOVA", "doi": "https://doi.org/10.1080/00031305.1978.10479237", "year": 1978, "authors": ["David C. Hoaglin", "Roy E. Welsch"], "source": "The American Statistician", "cited": 859, "abstract": "In least-squares fitting it is important to understand the influence which a data y value will have on each fitted y value. A projection matrix known as the hat matrix contains this information and, together with the Studentized residuals, provides a means of identifying exceptional data points. This approach also simplifies the calculations involved in removing a data point, and it requires only simple modifications in the preferred numerical least-squares algorithms.", "oa": true, "pdf_url": "https://doi.org/10.1080/00031305.1978.10479237", "local_pdf": "", "api": ""}, {"title": "A Randomized, Controlled Trial of Total Knee Replacement", "doi": "https://doi.org/10.1056/nejmoa1505467", "year": 2015, "authors": ["Søren Thorgaard Skou", "Ewa M. Roos", "Mogens Berg Laursen", "Michael Skovdal Rathleff", "Lars Arendt‐Nielsen", "Ole Simonsen"], "source": "New England Journal of Medicine", "cited": 826, "abstract": "BACKGROUND: More than 670,000 total knee replacements are performed annually in the United States; however, high-quality evidence to support the effectiveness of the procedure, as compared with nonsurgical interventions, is lacking. METHODS: In this randomized, controlled trial, we enrolled 100 patients with moderate-to-severe knee osteoarthritis who were eligible for unilateral total knee replacement. Patients were randomly assigned to undergo total knee replacement followed by 12 weeks of nonsurgical treatment (total-knee-replacement group) or to receive only the 12 weeks of nonsurgical treatment (nonsurgical-treatment group), which was delivered by physiotherapists and dietitians and consisted of exercise, education, dietary advice, use of insoles, and pain medication. The primary outco", "oa": true, "pdf_url": "https://doi.org/10.1056/nejmoa1505467", "local_pdf": "", "api": ""}, {"title": "Abiraterone plus prednisone added to androgen deprivation therapy and docetaxel in de novo metastatic castration-sensitive prostate cancer (PEACE-1): a multicentre, open-label, randomised, phase 3 study with a 2 × 2 factorial design", "doi": "https://doi.org/10.1016/s0140-6736(22)00367-1", "year": 2022, "authors": ["Karim Fizazi", "Stéphanie Foulon", "Joan Carles", "Guilhem Roubaud", "Ray McDermott", "Aude Fléchon"], "source": "The Lancet", "cited": 823, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s0140-6736(22)00367-1", "local_pdf": "", "api": ""}, {"title": "Removal of basic dye Auramine-O by ZnS:Cu nanoparticles loaded on activated carbon: optimization of parameters using response surface methodology with central composite design", "doi": "https://doi.org/10.1039/c4ra15637d", "year": 2015, "authors": ["Arash Asfaram", "Mehrorang Ghaedi", "Shilpi Agarwal", "Inderjeet Tyagi", "Vinod Kumar Gupta"], "source": "RSC Advances", "cited": 725, "abstract": "FESEM images of the prepared ZnS:Cu-NPs-AC.", "oa": true, "pdf_url": "https://pubs.rsc.org/en/content/articlepdf/2015/ra/c4ra15637d", "local_pdf": "", "api": ""}, {"title": "Experimental design for gene expression microarrays", "doi": "https://doi.org/10.1093/biostatistics/2.2.183", "year": 2001, "authors": ["Kathleen F. Kerr"], "source": "Biostatistics", "cited": 714, "abstract": "We examine experimental design issues arising with gene expression microarray technology. Microarray experiments have multiple sources of variation, and experimental plans should ensure that effects of interest are not confounded with ancillary effects. A commonly used design is shown to violate this principle and to be generally inefficient. We explore the connection between microarray designs and classical block design and use a family of ANOVA models as a guide to choosing a design. We combine principles of good design and A-optimality to give a general set of recommendations for design with microarrays. These recommendations are illustrated in detail for one kind of experimental objective, where we also give the results of a computer search for good designs.", "oa": true, "pdf_url": "https://academic.oup.com/biostatistics/article-pdf/2/2/183/781123/020183.pdf", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "MorePower 6.0 for ANOVA with relational confidence intervals and Bayesian analysis", "doi": "https://doi.org/10.3758/s13428-012-0186-0", "year": 2012, "authors": ["Jamie I. D. Campbell", "Valerie A. Thompson"], "source": "Behavior Research Methods", "cited": 673, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758%2Fs13428-012-0186-0.pdf", "local_pdf": "053_MorePower 6.0 for ANOVA with relational .pdf", "api": ""}, {"title": "Statistical Practices of Educational Researchers: An Analysis of their ANOVA, MANOVA, and ANCOVA Analyses", "doi": "https://doi.org/10.3102/00346543068003350", "year": 1998, "authors": ["H. J. Keselman", "Carl J. Huberty", "Lisa M. Lix", "Stephen Olejnik", "Robert A. Cribbie", "Barbara Donahue"], "source": "Review of Educational Research", "cited": 615, "abstract": "Articles published in several prominent educational journals were examined to investigate the use of data analysis tools by researchers in four research paradigms: between-subjects univariate designs, between-subjects multivariate designs, repeated measures designs, and covariance designs. In addition to examining specific details pertaining to the research design (e.g., sample size, group size equality/inequality) and methods employed for data analysis, the authors also catalogued whether (a) validity assumptions were examined, (b) effect size indices were reported, (c) sample sizes were selected on the basis of power considerations, and (d) appropriate textbooks and/or articles were cited to communicate the nature of the analyses that were performed. The present analyses imply that resea", "oa": true, "pdf_url": "https://doi.org/10.3102/00346543068003350", "local_pdf": "001_G_Power 3_ A flexible statistical power .pdf", "api": ""}, {"title": "Beyond t test and ANOVA: applications of mixed-effects models for more rigorous statistical analysis in neuroscience research", "doi": "https://doi.org/10.1016/j.neuron.2021.10.030", "year": 2021, "authors": ["Zhaoxia Yu", "Michele Guindani", "Steven F. Grieco", "Lujia Chen", "Todd C. Holmes", "Xiangmin Xu"], "source": "Neuron", "cited": 604, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.neuron.2021.10.030", "local_pdf": "", "api": ""}, {"title": "Simulation-Based Power Analysis for Factorial Analysis of Variance Designs", "doi": "https://doi.org/10.1177/2515245920951503", "year": 2021, "authors": ["Daniël Lakens", "Aaron R. Caldwell"], "source": "Advances in Methods and Practices in Psychological Science", "cited": 543, "abstract": "Researchers often rely on analysis of variance (ANOVA) when they report results of experiments. To ensure that a study is adequately powered to yield informative results with an ANOVA, researchers can perform an a priori power analysis. However, power analysis for factorial ANOVA designs is often a challenge. Current software solutions do not allow power analyses for complex designs with several within-participants factors. Moreover, power analyses often need [Formula: see text] or Cohen’s f as input, but these effect sizes are not intuitive and do not generalize to different experimental designs. We have created the R package Superpower and online Shiny apps to enable researchers without extensive programming experience to perform simulation-based power analysis for ANOVA designs of up to", "oa": true, "pdf_url": "https://doi.org/10.1177/2515245920951503", "local_pdf": "", "api": ""}, {"title": "Effectiveness of a long-lasting piperonyl butoxide-treated insecticidal net and indoor residual spray interventions, separately and together, against malaria transmitted by pyrethroid-resistant mosquitoes: a cluster, randomised controlled, two-by-two factorial design trial", "doi": "https://doi.org/10.1016/s0140-6736(18)30427-6", "year": 2018, "authors": ["Natacha Protopopoff", "Jacklin F Mosha", "Eliud Lukole", "J. D. Charlwood", "Alexandra Wright", "Charles Dismas Mwalimu"], "source": "The Lancet", "cited": 524, "abstract": "BACKGROUND: Progress in malaria control is under threat by wide-scale insecticide resistance in malaria vectors. Two recent vector control products have been developed: a long-lasting insecticidal net that incorporates a synergist piperonyl butoxide (PBO) and a long-lasting indoor residual spraying formulation of the insecticide pirimiphos-methyl. We evaluated the effectiveness of PBO long-lasting insecticidal nets versus standard long-lasting insecticidal nets as single interventions and in combination with the indoor residual spraying of pirimiphos-methyl. METHODS: We did a four-group cluster randomised controlled trial using a two-by-two factorial design of 48 clusters derived from 40 villages in Muleba (Kagera, Tanzania). We randomly assigned these clusters using restricted randomisati", "oa": true, "pdf_url": "http://www.thelancet.com/article/S0140673618304276/pdf", "local_pdf": "", "api": ""}, {"title": "Experimental Optimization of Fused Deposition Modelling Processing Parameters: A Design-for-Manufacturing Approach", "doi": "https://doi.org/10.1016/j.promfg.2017.07.079", "year": 2017, "authors": ["Ala’aldin Alafaghani", "Ala Qattawi", "Buraaq Alrawi", "Arturo Guzman"], "source": "Procedia Manufacturing", "cited": 498, "abstract": "The Additive Manufacturing (AM) technology initially was developed as a rapid prototyping tool for visualization and validation of designs. The recent development of AM technologies, such as Fused Deposition Modelling (FDM), is driving it from rapid prototyping to rapid manufacturing. However, building end-user functional parts using FDM proved to be a challenging task. The difficulty arises from the large number of processing parameters that affect the final part design such as: building direction, extrusion temperature, layer height, infill pattern and more. The processing parameters of FDM influence the quality of the parts and their functionality. In addition, a more systemic understanding is required to elaborate on the impact of the FDM processing parameters on the final part's mecha", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S2351978917302615/pdf", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Application of response surface methodology (RSM) for optimization of leaching parameters for ash reduction from low-grade coal", "doi": "https://doi.org/10.1016/j.ijmst.2018.04.014", "year": 2018, "authors": ["Sushanta K. Behera", "Himanshu Meena", "Sudipto Chakraborty", "B.C. Meikap"], "source": "International Journal of Mining Science and Technology", "cited": 495, "abstract": "Coal is the world’s most abundant energy source because of its abundance and relatively low cost. Due to the scarcity in the supply of high-grade coal, it is necessary to use low-grade coal for fulfilling energy demands of modern civilization. However, due to its high ash and moisture content, low-grade coal exerts the substantial impact on their consumption like pyrolysis, liquefaction, gasification and combustion process. The present research aimed to develop the efficient technique for the production of clean coal by optimizing the operating parameters with the help of response surface methodology. The effect of three independent variables such as hydrofluoric acid (HF) concentration (10–20% by volume), temperature (60–100 °C), and time (90–180 min), for ash reduction from the low-grade", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S209526861830257X/pdf", "local_pdf": "", "api": ""}, {"title": "Response surface methodology (RSM) for optimizing engine performance and emissions fueled with biofuel: Review of RSM for sustainability energy transition", "doi": "https://doi.org/10.1016/j.rineng.2023.101213", "year": 2023, "authors": ["Ibham Veza", "Martin Spraggon", "I.M. Rizwanul Fattah", "Muhammad Idris"], "source": "Results in Engineering", "cited": 480, "abstract": "Response Surface Methodology (RSM) is a statistical method to design experiments and optimize the effect of process variables. RSM is based on the principles of design of experiments or DOE. Design of experiments or DOE is a field of applied statistics that plans, conducts, analyses, and interprets controlled tests to assess factors that affect parameter values. Response surface methodology or RSM uses a statistical method for designing experiments and optimization. Despite the potential of response surface methodology to predict and optimize engine performance and emissions characteristics, a comprehensive review on RSM for biofuels, particularly for internal combustion engines (ICEs), is difficult to find. The review of response surface methodology is sometimes included together with oth", "oa": true, "pdf_url": "https://doi.org/10.1016/j.rineng.2023.101213", "local_pdf": "", "api": ""}, {"title": "Prediction of surface roughness in CNC face milling using neural networks and Taguchi's design of experiments", "doi": "https://doi.org/10.1016/s0736-5845(02)00005-4", "year": 2002, "authors": ["Panorios Benardos", "George-Christopher Vosniakos"], "source": "Robotics and Computer-Integrated Manufacturing", "cited": 457, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s0736-5845(02)00005-4", "local_pdf": "", "api": ""}, {"title": "Design of experiments with multiple independent variables: A resource management perspective on complete and reduced factorial designs.", "doi": "https://doi.org/10.1037/a0015826", "year": 2009, "authors": ["Linda M. Collins", "John J. Dziak", "Runze Li"], "source": "Psychological Methods", "cited": 440, "abstract": "An investigator who plans to conduct an experiment with multiple independent variables must decide whether to use a complete or reduced factorial design. This article advocates a resource management perspective on making this decision, in which the investigator seeks a strategic balance between service to scientific objectives and economy. Considerations in making design decisions include whether research questions are framed as main effects or simple effects; whether and which effects are aliased (confounded) in a particular design; the number of experimental conditions that must be implemented in a particular design and the number of experimental subjects the design requires to maintain the desired level of statistical power; and the costs associated with implementing experimental condit", "oa": true, "pdf_url": "https://doi.org/10.1037/a0015826", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Designing the design of experiments (DOE) – An investigation on the influence of different factorial designs on the characterization of complex systems", "doi": "https://doi.org/10.1016/j.enbuild.2021.111298", "year": 2021, "authors": ["A. Janković", "Gaurav Chaudhary", "Francesco Goia"], "source": "Energy and Buildings", "cited": 432, "abstract": "Although a general set of guidelines and procedures for performing the design of experiments (DOE) exists, the literature lacks a recommended course of action for finding and selecting the optimal design of experiments among a large range of possible designs. This research tries to fill this gap by comprehensively testing more than thirty different DOEs through nearly half a million simulated experimental runs. The performance of various DOEs in the characterization of the thermal behaviour of a double skin façade (DSF) is assessed by comparing the outcomes of the different designs and using the full factorial design (FFD) as the ground truth. Besides the finding for the specific case study used in this investigation, this research allowed us to obtain some broad conclusions on the behavio", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S037877882100582X/pdf", "local_pdf": "", "api": ""}, {"title": "Design of Experiments (DoE) applied to Pharmaceutical and Analytical Quality by Design (QbD)", "doi": "https://doi.org/10.1590/s2175-97902018000001006", "year": 2018, "authors": ["Isa Martins Fukuda", "Camila Francini Fidelis Pinto", "Camila dos Santos Moreira", "Alessandro Morais Saviano", "Felipe Rebello Lourenço"], "source": "Brazilian Journal of Pharmaceutical Sciences", "cited": 413, "abstract": "According to Quality by Design (QbD) concept, quality should be built into product/method during pharmaceutical/analytical development. Usually, there are many input factors that may affect quality of product and methods. Recently, Design of Experiments (DoE) have been widely used to understand the effects of multidimensional and interactions of input factors on the output responses of pharmaceutical products and analytical methods. This paper provides theoretical and practical considerations for implementation of Design of Experiments (DoE) in pharmaceutical and/or analytical Quality by Design (QbD). This review illustrates the principles and applications of the most common screening designs, such as two-level full factorial, fractionate factorial, and Plackett-Burman designs; and optimiz", "oa": true, "pdf_url": "http://www.scielo.br/pdf/bjps/v54nspe/2175-9790-bjps-54-spe-e01006.pdf", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Sequential Design of Experiments", "doi": "https://doi.org/10.1214/aoms/1177706205", "year": 1959, "authors": ["Herman Chernoff"], "source": "The Annals of Mathematical Statistics", "cited": 396, "abstract": "", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-30/issue-3/Sequential-Design-of-Experiments/10.1214/aoms/1177706205.pdf", "local_pdf": "", "api": ""}, {"title": "Preparation of activated carbon from coconut husk: Optimization study on removal of 2,4,6-trichlorophenol using response surface methodology", "doi": "https://doi.org/10.1016/j.jhazmat.2007.09.014", "year": 2007, "authors": ["I.A.W. Tan", "Abdul Latif Ahmad", "B.H. Hameed"], "source": "Journal of Hazardous Materials", "cited": 377, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0304389407013015", "local_pdf": "", "api": ""}, {"title": "ExpDes: An R Package for ANOVA and Experimental Designs", "doi": "https://doi.org/10.4236/am.2014.519280", "year": 2014, "authors": ["Eric Batista Ferreira", "Pórtya Piscitelli Cavalcanti", "Denismar Alves Nogueira"], "source": "Applied Mathematics", "cited": 376, "abstract": "Analysis of variance (ANOVA) is a usual way for analysing experiments. However, depending on the design and/or the analysis scheme, it can be a hard task. ExpDes, acronym for Experimental Designs, is a package that intends to turn such task easier. Devoted to fixed models and balanced experiments (no missing data), ExpDes allows user to deal with additional treatments in a single run, several experiment designs and exhibits standard and easy-to-interpret outputs. It was developed at the Exact Sciences Institute of the Federal University of Alfenas, Brazil. Stable versions of package ExpDes are available on CRAN (Comprehensive R Archive Network) since 2012. Based on users’ feedback, the package was used to illustrate graduation and post-graduation classes and to carry out data analysis, in ", "oa": true, "pdf_url": "http://www.scirp.org/journal/PaperDownload.aspx?paperID=51204", "local_pdf": "", "api": ""}, {"title": "Design of Experiments Application, Concepts, Examples: State of the Art", "doi": "https://doi.org/10.21533/pen.v5.i3.1802", "year": 2017, "authors": ["Benjamin Duraković"], "source": "Periodicals of Engineering and Natural Sciences (PEN)", "cited": 360, "abstract": "Design of Experiments (DOE) is statistical tool deployed in various types of system, process and product design, development and optimization. It is multipurpose tool that can be used in various situations such as design for comparisons, variable screening, transfer function identification, optimization and robust design. This paper explores historical aspects of DOE and provides state of the art of its application, guides researchers how to conceptualize, plan and conduct experiments, and how to analyze and interpret data including examples. Also this paper reveals that in past 20 years application of DOE have been growing rapidly in manufacturing as well as non-manufacturing industries. It was most popular tool in scientific areas of medicine, engineering, biochemistry, physics, computer", "oa": true, "pdf_url": "http://pen.ius.edu.ba/index.php/pen/article/download/145/175", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "Model-Oriented Design of Experiments", "doi": "https://doi.org/10.2307/1271005", "year": 1999, "authors": ["Steven E. Rigdon", "Valerii V. Federov", "Peter Hackl"], "source": "Technometrics", "cited": 355, "abstract": "1 Some Facts From Regression Analysis.- 1.1 The Linear Model.- 1.2 More about the Information Matrix.- 1.3 Generalized Versions of the Linear Regression Model.- 1.4 Nonlinear Models.- 2 Convex Design Theory.- 2.1 Optimality Criteria.- 2.2 Some Properties of Optimality Criteria.- 2.3 Continuous Optimal Designs.- 2.4 The Sensitivity Function and Equivalence Theorems.- 2.5 Some Examples.- 2.6 Complements.- 3 Numerical Techniques.- 3.1 First Order Algorithm:D-criterion.- 3.2 First Order Algorithm: The General Case.- 3.3 Finite Sample Size.- 4 Optimal Design under Constraints.- 4.1 Cost Constraints.- 4.2 Constraints for Auxiliary Criteria.- 4.3 Directly Constrained Design Measures.- 5 Special Cases and Applications.- 5.1 Designs for Time-Dependent Models.- 5.2 Regression Models with Random Para", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/abs/10.1080/00401706.1999.10485606", "local_pdf": "", "api": ""}, {"title": "Design, analysis and presentation of factorial randomised controlled trials", "doi": "https://doi.org/10.1186/1471-2288-3-26", "year": 2003, "authors": ["Alan Montgomery", "T. J. Peters", "Paul Little"], "source": "BMC Medical Research Methodology", "cited": 338, "abstract": "BACKGROUND: The evaluation of more than one intervention in the same randomised controlled trial can be achieved using a parallel group design. However this requires increased sample size and can be inefficient, especially if there is also interest in considering combinations of the interventions. An alternative may be a factorial trial, where for two interventions participants are allocated to receive neither intervention, one or the other, or both. Factorial trials require special considerations, however, particularly at the design and analysis stages. DISCUSSION: Using a 2 x 2 factorial trial as an example, we present a number of issues that should be considered when planning a factorial trial. The main design issue is that of sample size. Factorial trials are most often powered to dete", "oa": true, "pdf_url": "https://bmcmedresmethodol.biomedcentral.com/counter/pdf/10.1186/1471-2288-3-26", "local_pdf": "070_Design, analysis and presentation of fac.pdf", "api": ""}, {"title": "A Review of Response Surface Methodology: A Literature Survey", "doi": "https://doi.org/10.1080/00401706.1966.10490404", "year": 1966, "authors": ["William J. Hill", "William G. Hunter"], "source": "Technometrics", "cited": 336, "abstract": "Response surface methodology, an experimental strategy initially developed and described by Box and Wilson, has been employed with considerable success in a wide variety of situations, especially in the fields of chemistry and chemical engineering. It is the purpose of this paper to review the literature of response surface methodology, emphasizing especially the practical applications of the method. A comprehensive bibliography is included.", "oa": true, "pdf_url": "https://doi.org/10.1080/00401706.1966.10490404", "local_pdf": "", "api": ""}, {"title": "Effects of temperature, time, and solvent ratio on the extraction of phenolic compounds and the anti-radical activity of Clinacanthus nutans Lindau leaves by response surface methodology", "doi": "https://doi.org/10.1186/s13065-017-0285-1", "year": 2017, "authors": ["Intan Soraya Che Sulaiman", "Mahiran Basri", "Hamid Reza Fard Masoumi", "Wei Jian Chee", "Siti Efliza Ashari", "Maznah Ismail"], "source": "Chemistry Central Journal", "cited": 332, "abstract": "Clinacanthus nutans Lindau is a well-known plant, native to tropical Asian countries. Reports on this plant that is rich in phenolic compounds have focused on its therapeutic anti-inflammatory, anti-herpes simplex, antioxidant, and anti-cancer characteristics. In this paper, the influence of the extraction parameters—temperatures (60–80 °C), times (80–120 min), and solvent ratios (70:30–90:10) of water:ethanol were investigated using response surface methodology in order to determine the optimum extraction conditions that could produce maximum extraction yields of the phenolic compounds and the highest anti-radical activity of the C. nutans extract. The optimum conditions suggested by the predicted model were: an extraction temperature of 60 °C, an extraction time of 120 min and a water:et", "oa": true, "pdf_url": "https://bmcchem.biomedcentral.com/track/pdf/10.1186/s13065-017-0285-1", "local_pdf": "072_Effects of temperature, time, and solven.pdf", "api": ""}, {"title": "How To Optimize Materials and Devices via Design of Experiments and Machine Learning: Demonstration Using Organic Photovoltaics", "doi": "https://doi.org/10.1021/acsnano.8b04726", "year": 2018, "authors": ["Bing Cao", "Lawrence A. Adutwum", "Anton O. Oliynyk", "Erik J. Luber", "Brian C. Olsen", "Arthur Mar"], "source": "ACS Nano", "cited": 326, "abstract": "Most discoveries in materials science have been made empirically, typically through one-variable-at-a-time (Edisonian) experimentation. The characteristics of materials-based systems are, however, neither simple nor uncorrelated. In a device such as an organic photovoltaic, for example, the level of complexity is high due to the sheer number of components and processing conditions, and thus, changing one variable can have multiple unforeseen effects due to their interconnectivity. Design of Experiments (DoE) is ideally suited for such multivariable analyses: by planning one's experiments as per the principles of DoE, one can test and optimize several variables simultaneously, thus accelerating the process of discovery and optimization while saving time and precious laboratory resources. Wh", "oa": true, "pdf_url": "https://pubs.acs.org/doi/pdf/10.1021/acsnano.8b04726", "local_pdf": "", "api": ""}, {"title": "Use of response surface methodology for optimization of fluoride adsorption in an aqueous solution by Brushite", "doi": "https://doi.org/10.1016/j.arabjc.2013.12.028", "year": 2014, "authors": ["M. Mourabet", "A. El Rhilassi", "H. El Boujaady", "M. Bennani-Ziatni", "A. Taïtaï"], "source": "Arabian Journal of Chemistry", "cited": 309, "abstract": "In the present study, Response surface methodology (RSM) was employed for the removal of fluoride on Brushite and the process parameters were optimized. Four important process parameters including initial fluoride concentration (40–50 mg/L), pH (4–11), temperature (10–40 °C) and B dose (0.05–0.15 g) were optimized to obtain the best response of fluoride removal using the statistical Box–Behnken design. The experimental data obtained were analyzed by analysis of variance (ANOVA) and fitted to a second-order polynomial equation using multiple regression analysis. Numerical optimization applying desirability function was used to identify the optimum conditions for maximum removal of fluoride. The optimum conditions were found to be initial concentration = 49.06 mg/L, initial solution pH = 5.3", "oa": true, "pdf_url": "https://doi.org/10.1016/j.arabjc.2013.12.028", "local_pdf": "", "api": ""}, {"title": "An approach for mechanical property optimization of fused deposition modeling with polylactic acid via design of experiments", "doi": "https://doi.org/10.1108/rpj-07-2014-0083", "year": 2016, "authors": ["Jonathan Torres", "Matthew Cole", "Allen Owji", "Zachary DeMastry", "Ali P. Gordon"], "source": "Rapid Prototyping Journal", "cited": 295, "abstract": "Purpose This paper aims to present the influences of several production variables on the mechanical properties of specimens manufactured using fused deposition modeling (FDM) with polylactic acid (PLA) as a media and relate the practical and experimental implications of these as related to stiffness, strength, ductility and generalized loading. Design/methodology/approach A two-factor-level Taguchi test matrix was defined to allow streamlined mechanical testing of several different fabrication settings using a reduced array of experiments. Specimens were manufactured and tested according to ASTM E8/D638 and E399/D5045 standards for tensile and fracture testing. After initial analysis of mechanical properties derived from mechanical tests, analysis of variance was used to infer optimized pr", "oa": true, "pdf_url": "https://doi.org/10.1108/rpj-07-2014-0083", "local_pdf": "", "api": ""}, {"title": "Optimisation of the solvent extraction of phenolic antioxidants from fruits of Euterpe oleracea using Response Surface Methodology", "doi": "https://doi.org/10.1016/j.biortech.2009.03.083", "year": 2009, "authors": ["Darly Rodrigues Pompeu", "Evaldo Martins da Silva", "Hervé Rogez"], "source": "Bioresource Technology", "cited": 295, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0960852409006464/pdf", "local_pdf": "", "api": ""}, {"title": "Optimization of ultrasound assisted extraction of antioxidant compounds from marjoram (Origanum majorana L.) using response surface methodology", "doi": "https://doi.org/10.1016/j.ultsonch.2011.11.001", "year": 2011, "authors": ["Mohammad B. Hossain", "Nigel P. Brunton", "Ankit Patras", "Brijesh K. Tiwari", "Colm P. O’Donnell", "Ana Belén Martín‐Diana"], "source": "Ultrasonics Sonochemistry", "cited": 294, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.ultsonch.2011.11.001", "local_pdf": "", "api": ""}, {"title": "Response surface methodology for optimization of cinnamon essential oil nanoemulsion with improved stability and antifungal activity", "doi": "https://doi.org/10.1016/j.ultsonch.2019.05.021", "year": 2019, "authors": ["Puntipa Pongsumpun", "Satoshi Iwamoto", "Ubonrat Siripatrawan"], "source": "Ultrasonics Sonochemistry", "cited": 282, "abstract": "• Optimization for fabrication of cinnamon oil nanoemulsion was achieved by using RSM. • Cinnamon oil nanoemulsion had good stability and antifungal activity. • Nanoemulsion improved physical and antifungal properties of cinnamon oil. • Cinnamon oil nanoemulsion has high potential for food and agricultural applications. The optimum formulation and ultrasonic condition for fabrication of cinnamon essential oil (CEO) nanoemulsion were determined using Response Surface Methodology (RSM). The CEO nanoemulsions were formed using an ultrasonic bath (43 kHz at power output of 210 W) and an ultrasonic probe (24 kHz at power of 400 W). Probe ultrasonication outperformed bath ultrasonication since it produced nanoemulsions with smaller droplet size, narrower size distribution as measured using polyd", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S135041771930598X/pdf", "local_pdf": "", "api": ""}, {"title": "High-speed bounding with the MIT Cheetah 2: Control design and experiments", "doi": "https://doi.org/10.1177/0278364917694244", "year": 2017, "authors": ["Hae-Won Park", "Patrick M. Wensing", "Sangbae Kim"], "source": "The International Journal of Robotics Research", "cited": 271, "abstract": "This paper presents the design and implementation of a bounding controller for the MIT Cheetah 2 and its experimental results. The paper introduces the architecture of the controller along with the functional roles of its subcomponents. The application of impulse scaling provides feedforward force profiles that automatically adapt across a wide range of speeds. A discrete gait pattern stabilizer maintains the footfall sequence and timing. Continuous feedback is layered to manage balance during the stance phase. Stable hybrid limit cycles are exhibited in simulation using simplified models, and are further validated in untethered three-dimensional bounding experiments. Experiments are conducted both indoors and outdoors on various man-made and natural terrains. The control framework is show", "oa": true, "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/0278364917694244", "local_pdf": "", "api": ""}, {"title": "Optimization of tool geometry parameters for turning operations based on the response surface methodology", "doi": "https://doi.org/10.1016/j.measurement.2010.11.018", "year": 2010, "authors": ["Süleyman Neşeli", "Süleyman Yaldız", "Erol Türkeş"], "source": "Measurement", "cited": 263, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.measurement.2010.11.018", "local_pdf": "", "api": ""}, {"title": "Application of response surface methodology for optimization of biodiesel production by transesterification of soybean oil with ethanol", "doi": "https://doi.org/10.1016/j.fuproc.2010.10.002", "year": 2010, "authors": ["Giovanilton F. Silva", "Fernando L. Camargo", "Andrea Lopes de Oliveira Ferreira"], "source": "Fuel Processing Technology", "cited": 250, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0378382010003504/pdf", "local_pdf": "", "api": ""}, {"title": "Nonlinear response of ozone to precursor emission changes in China: a modeling study using response surface methodology", "doi": "https://doi.org/10.5194/acp-11-5027-2011", "year": 2011, "authors": ["J. Xing", "Shuxiao Wang", "Carey Jang", "Yun Zhu", "Jiming Hao"], "source": "Atmospheric chemistry and physics", "cited": 250, "abstract": "Abstract. Statistical response surface methodology (RSM) is successfully applied for a Community Multi-scale Air Quality model (CMAQ) analysis of ozone sensitivity studies. Prediction performance has been demonstrated through cross validation, out-of-sample validation and isopleth validation. Sample methods and key parameters, including the maximum numbers of variables involved in statistical interpolation and training samples have been tested and selected through computational experiments. Overall impacts from individual source categories which include local/regional NOx and VOC emission sources and NOx emissions from power plants for three megacities – Beijing, Shanghai and Guangzhou – were evaluated using an RSM analysis of a July 2005 modeling study. NOx control appears to be beneficia", "oa": true, "pdf_url": "https://acp.copernicus.org/articles/11/5027/2011/acp-11-5027-2011.pdf", "local_pdf": "082_Nonlinear response of ozone to precursor.pdf", "api": ""}, {"title": "Optimization of carboxymethyl chitosan synthesis using response surface methodology and desirability function", "doi": "https://doi.org/10.1016/j.ijbiomac.2016.01.017", "year": 2016, "authors": ["Andrea de Lacerda Bukzem", "Roberta Signini", "Danilo M. dos Santos", "Luciano M. Lião", "Diego P. R. Ascheri"], "source": "International Journal of Biological Macromolecules", "cited": 247, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0141813016300174/pdf", "local_pdf": "", "api": ""}, {"title": "Optimization of a cultural medium for bacteriocin production by Lactococcus lactis using response surface methodology", "doi": "https://doi.org/10.1016/s0168-1656(01)00377-7", "year": 2002, "authors": ["Chan Li", "Jinghua Bai", "Zhaoling Cai", "Fan Ouyang"], "source": "Journal of Biotechnology", "cited": 243, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s0168-1656(01)00377-7", "local_pdf": "", "api": ""}, {"title": "Probabilistic Analysis of Circular Tunnels in Homogeneous Soil Using Response Surface Methodology", "doi": "https://doi.org/10.1061/(asce)gt.1943-5606.0000060", "year": 2009, "authors": ["Guilhem Mollon", "Daniel Dias", "Abdul‐Hamid Soubra"], "source": "Journal of Geotechnical and Geoenvironmental Engineering", "cited": 237, "abstract": "A probabilistic analysis of a shallow circular tunnel driven by a pressurized shield in a frictional and/or cohesive soil is presented. Both the ultimate limit state (ULS) and serviceability limit state (SLS) are considered in the analysis. Two deterministic models based on numerical simulations are used. The first one computes the tunnel collapse pressure and the second one calculates the maximal settlement due to the applied face pressure. The response surface methodology is utilized for the assessment of the Hasofer-Lind reliability index for both limit states. Only the soil shear strength parameters are considered as random variables while studying the ULS. However, for the SLS, both the shear strength parameters and Young’s modulus of the soil are considered as random variables. For U", "oa": true, "pdf_url": "https://doi.org/10.1061/(asce)gt.1943-5606.0000060", "local_pdf": "", "api": ""}, {"title": "Study of the parameters in electrical discharge machining through response surface methodology approach", "doi": "https://doi.org/10.1016/j.apm.2009.03.021", "year": 2009, "authors": ["Sameh Habib"], "source": "Applied Mathematical Modelling", "cited": 227, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0307904X09000791/pdf", "local_pdf": "", "api": ""}, {"title": "The application of design of experiments (DoE) reaction optimisation and solvent selection in the development of new synthetic chemistry", "doi": "https://doi.org/10.1039/c5ob01892g", "year": 2015, "authors": ["Paul M. Murray", "Fiona Bellany", "Laure Benhamou", "Dejan‐Krešimir Bučar", "Alethea B. Tabor", "Tom D. Sheppard"], "source": "Organic & Biomolecular Chemistry", "cited": 226, "abstract": "This article outlines the benefits of using 'Design of Experiments' (DoE) optimisation during the development of new synthetic methodology. A particularly important factor in the development of new chemical reactions is the choice of solvent which can often drastically alter the efficiency and selectivity of a process. Whilst solvent optimisation is usually done in a non-systematic way based upon a chemist's intuition and previous laboratory experience, we illustrate how optimisation of the solvent for a reaction can be carried out by using a 'map of solvent space' in a DoE optimisation. A new solvent map has been developed specifically for optimisation of new chemical reactions using principle component analysis (PCA) incorporating 136 solvents with a wide range of properties. The new sol", "oa": true, "pdf_url": "https://pubs.rsc.org/en/content/articlepdf/2016/ob/c5ob01892g", "local_pdf": "", "api": ""}, {"title": "Development and Statistical Optimization of Solid Lipid Nanoparticles of Simvastatin by Using 23 Full-Factorial Design", "doi": "https://doi.org/10.1208/s12249-010-9414-z", "year": 2010, "authors": ["Mayank Shah", "Kamla Pathak"], "source": "AAPS PharmSciTech", "cited": 209, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1208/s12249-010-9414-z.pdf", "local_pdf": "", "api": ""}, {"title": "Overview on the Response Surface Methodology (RSM) in Extraction Processes", "doi": "https://doi.org/10.33736/jaspe.161.2015", "year": 2016, "authors": ["Khairul Anwar Mohamad Said", "Mohamed Afizal Mohamed Amin"], "source": "Journal of Applied Science & Process Engineering", "cited": 204, "abstract": "Response Surface Methodology (RSM) is an optimization tool that can identify interrelationship between variables as being adopted by experiment/ research studies in food and herbal plants extraction niche area. This review discusses the optimization approach through utilization of research surface methodology either using central composite design or Box-Behnken method specifically in extraction processes. The use of analysis of variance (ANOVA) to evaluate the degree of accuracy held by the derived model is based on several responses. RSM helps to determine the best experimental design in order to identify the relationship between variables. This paper also discusses on the utilization of RSM to derive a model equation that later can be applied for response prediction and the determination", "oa": true, "pdf_url": "https://doi.org/10.33736/jaspe.161.2015", "local_pdf": "", "api": ""}, {"title": "Production of antioxidant hydrolyzates from a whey protein concentrate with thermolysin: Optimization by response surface methodology", "doi": "https://doi.org/10.1016/j.lwt.2010.06.017", "year": 2010, "authors": ["María del Mar Contreras", "Blanca Hernández‐Ledesma", "Lourdes Amigo", "Pedro J. Martín‐Álvarez", "Isidra Recio"], "source": "LWT", "cited": 202, "abstract": "Whey protein concentrate (WPC) enriched in β-lactoglobulin (β-Lg) was hydrolyzed using Corolase PP® and thermolysin to produce hydrolyzates with antioxidant activity. The optimization of the main experimental variables involved in the process, such as type of enzyme, and hydrolysis conditions, concretely enzyme to substrate ratio, time and temperature, were evaluated using response surface methodology. A central composite circumscribed (CCC) design was employed to study the effect of the experimental variables on the antioxidant activity determined by radical scavenging potency. The parameters of the model were estimated by multiple linear regression, and the highest radical scavenging activity (2.57 μmol Trolox/mg protein) was found in WPC hydrolyzed with thermolysin after 8 h at 80 °C an", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0023643810002355/pdf", "local_pdf": "", "api": ""}, {"title": "Optimization of Enzymatic Hydrolysis of Wheat Straw Pretreated by Alkaline Peroxide Using Response Surface Methodology", "doi": "https://doi.org/10.1021/ie8016863", "year": 2009, "authors": ["Benkun Qi", "Xiangrong Chen", "Fei Shen", "Yi Su", "Yinhua Wan"], "source": "Industrial & Engineering Chemistry Research", "cited": 202, "abstract": "To optimize the enzymatic conversion of widely available lignocellulosic biomass-wheat straw (WS), pretreatment facilitating the enzymatic saccharification process was first performed by alkaline peroxide, resulting in a substrate consisting of 60.17% cellulose, 29.53% hemicelluloses, and 4.59% lignin. Using response surface methodology, the combined effects of enzyme loading, substrate concentration, surfactant concentration, and reaction time on hydrolysis yield from enzymatic saccharification of WS were further investigated. The results showed that both enzyme loading and substrate concentration had interactions with surfactant concentration. A quadratic polynomial equation for predicting the hydrolysis yield was developed. The experimental results were in good agreement with predicted ", "oa": true, "pdf_url": "https://doi.org/10.1021/ie8016863", "local_pdf": "", "api": ""}, {"title": "Fixed-Time Formation Control of Multirobot Systems: Design and Experiments", "doi": "https://doi.org/10.1109/tie.2018.2870409", "year": 2018, "authors": ["Chunyan Wang", "Hilton Tnunay", "Zongyu Zuo", "Barry Lennox", "Zhengtao Ding"], "source": "IEEE Transactions on Industrial Electronics", "cited": 192, "abstract": "Time delays exist in network-connected systems. Especially for vision-based multirobot systems, time delays are diverse and complicated due to the communication network, camera latency, image processing, etc. At the same time, many tasks, such as searching and rescue, have timing requirement. This paper focuses on fixed-time formation control of multirobot systems subject to delay constraints. First, predictor-based state transformation is employed for each robot to deal with the input delay, and the uncertain terms remained in the transformed systems are carefully considered. Then, a couple of nonlinear fixed-time formation protocols are proposed for the multirobot systems with respectively undirected and directed topology, and the corresponding settling time is derived by using the Lyapu", "oa": true, "pdf_url": "https://doi.org/10.1109/tie.2018.2870409", "local_pdf": "", "api": ""}, {"title": "Design of experiments (DoE) to develop and to optimize nanoparticles as drug delivery systems", "doi": "https://doi.org/10.1016/j.ejpb.2021.05.011", "year": 2021, "authors": ["Marcela Tavares Luiz", "Juliana Santos Rosa Viegas", "Juliana Palma Abriata", "Felipe Viegas", "Fabiana T. M. C. Vicentini", "Maria Vitória Lopes Badra Bentley"], "source": "European Journal of Pharmaceutics and Biopharmaceutics", "cited": 189, "abstract": "Nanotechnology has been widely applied to develop drug delivery systems to improve therapeutic performance. The effectiveness of these systems is intrinsically related to their physicochemical properties, so their biological responses are highly susceptible to factors such as the type and quantity of each material that is employed in their synthesis and to the method that is used to produce them. In this context, quality-oriented manufacturing of nanoparticles has been an important strategy to understand and to optimize the factors involved in their production. For this purpose, Design of Experiment (DoE) tools have been applied to obtain enough knowledge about the process and hence achieve high-quality products. This review aims to set up the bases to implement DoE as a strategy to improv", "oa": true, "pdf_url": "https://doi.org/10.1016/j.ejpb.2021.05.011", "local_pdf": "064_Design of Experiments (DoE) applied to P.pdf", "api": ""}, {"title": "The application of analysis of variance ( ANOVA ) to different experimental designs in optometry", "doi": "https://doi.org/10.1046/j.1475-1313.2002.00020.x", "year": 2002, "authors": ["Richard A. Armstrong", "Frank Eperjesi", "Bernard Gilmartin"], "source": "Ophthalmic and Physiological Optics", "cited": 173, "abstract": "", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1046/j.1475-1313.2002.00020.x", "local_pdf": "", "api": ""}, {"title": "Minocycline and celecoxib as adjunctive treatments for bipolar depression: a multicentre, factorial design randomised controlled trial", "doi": "https://doi.org/10.1016/s2215-0366(20)30138-3", "year": 2020, "authors": ["Muhammad Ishrat Husain", "Imran B. Chaudhry", "Ameer B. Khoso", "Muhammad Omair Husain", "John Hodsoll", "Moin Ahmed Ansari"], "source": "The Lancet Psychiatry", "cited": 167, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s2215-0366(20)30138-3", "local_pdf": "", "api": ""}, {"title": "Optimisation of the extraction of phenolic compounds from apples using response surface methodology", "doi": "https://doi.org/10.1016/j.foodchem.2013.10.086", "year": 2013, "authors": ["Aline Alberti", "Acácio Antônio Ferreira Zielinski", "Danianni Marinho Zardo", "Ivo Mottin Demiate", "Alessandro Nogueira", "Luciana Igarashi‐Mafra"], "source": "Food Chemistry", "cited": 167, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0308814613015343/pdf", "local_pdf": "", "api": ""}, {"title": "Optimal Design of Experiments in the Presence of Interference", "doi": "https://doi.org/10.1162/rest_a_00716", "year": 2018, "authors": ["Sarah Baird", "J. Aislinn Bohren", "Craig McIntosh", "Berk Özler"], "source": "The Review of Economics and Statistics", "cited": 162, "abstract": "Abstract We formalize the optimal design of experiments when there is interference between units, that is, an individual’s outcome depends on the outcomes of others in her group. We focus on randomized saturation designs, two-stage experiments that first randomize treatment saturation of a group, then individual treatment assignment. We map the potential outcomes framework with partial interference to a regression model with clustered errors, calculate standard errors of randomized saturation designs, and derive analytical insights about the optimal design. We show that the power to detect average treatment effects declines precisely with the ability to identify novel treatment and spillover effects.", "oa": true, "pdf_url": "https://doi.org/10.1162/rest_a_00716", "local_pdf": "", "api": ""}, {"title": "Aerosolizable Lipid Nanoparticles for Pulmonary Delivery of mRNA through Design of Experiments", "doi": "https://doi.org/10.3390/pharmaceutics12111042", "year": 2020, "authors": ["Hairui Zhang", "J. Sánchez Leal", "Melissa Soto", "Hugh D. C. Smyth", "Debadyuti Ghosh"], "source": "Pharmaceutics", "cited": 157, "abstract": "Messenger RNA is a class of promising nucleic acid therapeutics to treat a variety of diseases, including genetic diseases. The development of a stable and efficacious mRNA pulmonary delivery system would enable high therapeutic concentrations locally in the lungs to improve efficacy and limit potential toxicities. In this study, we employed a Design of Experiments (DOE) strategy to screen a library of lipid nanoparticle compositions to identify formulations possessing high potency both before and after aerosolization. Lipid nanoparticles (LNPs) showed stable physicochemical properties for at least 14 days of storage at 4 °C, and most formulations exhibited high encapsulation efficiencies greater than 80%. Generally, upon nebulization, LNP formulations showed increased particle size and de", "oa": true, "pdf_url": "https://www.mdpi.com/1999-4923/12/11/1042/pdf?version=1604225746", "local_pdf": "", "api": ""}, {"title": "Statistical Process Optimization Through Multi-Response Surface Methodology", "doi": "https://doi.org/10.5281/zenodo.1083451", "year": 2009, "authors": ["Sadigh Raissi", "R- Eslami Farsani"], "source": "Zenodo (CERN European Organization for Nuclear Research)", "cited": 157, "abstract": "In recent years, response surface methodology (RSM) has brought many attentions of many quality engineers in different industries. Most of the published literature on robust design methodology is basically concerned with optimization of a single response or quality characteristic which is often most critical to consumers. For most products, however, quality is multidimensional, so it is common to observe multiple responses in an experimental situation. Through this paper interested person will be familiarize with this methodology via surveying of the most cited technical papers. It is believed that the proposed procedure in this study can resolve a complex parameter design problem with more than two responses. It can be applied to those areas where there are large data sets and a number of", "oa": true, "pdf_url": "https://zenodo.org/record/1083451", "local_pdf": "001_G_Power 3_ A flexible statistical power .pdf", "api": ""}]}, "multivariate_statistics": {"cn": "多元统计分析", "items": [{"title": "clusterProfiler: an R Package for Comparing Biological Themes Among Gene Clusters", "doi": "https://doi.org/10.1089/omi.2011.0118", "year": 2012, "authors": ["Guangchuang Yu", "Li-Gen Wang", "Yanyan Han", "Qing‐Yu He"], "source": "OMICS A Journal of Integrative Biology", "cited": 39542, "abstract": "Increasing quantitative data generated from transcriptomics and proteomics require integrative strategies for analysis. Here, we present an R package, clusterProfiler that automates the process of biological-term classification and the enrichment analysis of gene clusters. The analysis module and visualization module were combined into a reusable workflow. Currently, clusterProfiler supports three species, including humans, mice, and yeast. Methods provided in this package can be easily extended to other species and ontologies. The clusterProfiler package is released under Artistic-2.0 License within Bioconductor project. The source code and vignette are freely available at http://bioconductor.org/packages/release/bioc/html/clusterProfiler.html.", "oa": true, "pdf_url": "https://doi.org/10.1089/omi.2011.0118", "local_pdf": "", "api": ""}, {"title": "A new criterion for assessing discriminant validity in variance-based structural equation modeling", "doi": "https://doi.org/10.1007/s11747-014-0403-8", "year": 2014, "authors": ["Jörg Henseler", "Christian M. Ringle", "Marko Sarstedt"], "source": "Journal of the Academy of Marketing Science", "cited": 36584, "abstract": "Discriminant validity assessment has become a generally accepted prerequisite for analyzing relationships between latent variables. For variance-based structural equation modeling, such as partial least squares, the Fornell-Larcker criterion and the examination of cross-loadings are the dominant approaches for evaluating discriminant validity. By means of a simulation study, we show that these approaches do not reliably detect the lack of discriminant validity in common research situations. We therefore propose an alternative approach, based on the multitrait-multimethod matrix, to assess discriminant validity: the heterotrait-monotrait ratio of correlations. We demonstrate its superior performance by means of a Monte Carlo simulation study, in which we compare the new approach to the Forn", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/s11747-014-0403-8.pdf", "local_pdf": "001_A new criterion for assessing discrimina.pdf", "api": ""}, {"title": "Silhouettes: A graphical aid to the interpretation and validation of cluster analysis", "doi": "https://doi.org/10.1016/0377-0427(87)90125-7", "year": 1987, "authors": ["Peter J. Rousseeuw"], "source": "Journal of Computational and Applied Mathematics", "cited": 21571, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/0377042787901257/pdf", "local_pdf": "", "api": ""}, {"title": "Bootstrap Methods: Another Look at the Jackknife", "doi": "https://doi.org/10.1214/aos/1176344552", "year": 1979, "authors": ["B. Efron"], "source": "The Annals of Statistics", "cited": 17735, "abstract": "We discuss the following problem: given a random sample $\\mathbf{X} = (X_1, X_2, \\cdots, X_n)$ from an unknown probability distribution $F$, estimate the sampling distribution of some prespecified random variable $R(\\mathbf{X}, F)$, on the basis of the observed data $\\mathbf{x}$. (Standard jackknife theory gives an approximate mean and variance in the case $R(\\mathbf{X}, F) = \\theta(\\hat{F}) - \\theta(F), \\theta$ some parameter of interest.) A general method, called the \"bootstrap,\" is introduced, and shown to work satisfactorily on a variety of estimation problems. The jackknife is shown to be a linear approximation method for the bootstrap. The exposition proceeds by a series of examples: variance of the sample median, error rates in a linear discriminant analysis, ratio estimation, estim", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-7/issue-1/Bootstrap-Methods-Another-Look-at-the-Jackknife/10.1214/aos/1176344552.pdf", "local_pdf": "", "api": ""}, {"title": "Convergent and discriminant validation by the multitrait-multimethod matrix.", "doi": "https://doi.org/10.1037/h0046016", "year": 1959, "authors": ["Donald T. Campbell", "Donald W. Fiske"], "source": "Psychological Bulletin", "cited": 17218, "abstract": "This data set was collected to examine the eHealth Literacy Scale as a means of assessing eHealth literacy among German athletes. In this context, we pursued two objectives with this study: first, to test the factorial structure of the GR-eHEALS and assess its construct validity by examining both convergent and discriminant validity; and second, to examine the associations between eHealth literacy and health-related outcomes (i.e., substance use and injuries). This digital survey was conducted as a cross-sectional study, adhering to the approval guidelines of the Ethics Committee of the Faculty of Medicine at the University of Duisburg-Essen (19-8947-BO). Prior to the survey, each participant provided electronic informed consent. Participation was both anonymous and voluntary, without any ", "oa": true, "pdf_url": "https://doi.org/10.1037/h0046016", "local_pdf": "", "api": ""}, {"title": "Cluster analysis and display of genome-wide expression patterns", "doi": "https://doi.org/10.1073/pnas.95.25.14863", "year": 1998, "authors": ["Michael B. Eisen", "Paul T. Spellman", "Patrick O. Brown", "David Botstein"], "source": "Proceedings of the National Academy of Sciences", "cited": 16455, "abstract": "A system of cluster analysis for genome-wide expression data from DNA microarray hybridization is described that uses standard statistical algorithms to arrange genes according to similarity in pattern of gene expression. The output is displayed graphically, conveying the clustering and the underlying expression data simultaneously in a form intuitive for biologists. We have found in the budding yeast Saccharomyces cerevisiae that clustering gene expression data groups together efficiently genes of known similar function, and we find a similar tendency in human data. Thus patterns seen in genome-wide expression experiments can be interpreted as indications of the status of cellular processes. Also, coexpression of genes of known function with poorly characterized or novel genes may provide", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.95.25.14863", "local_pdf": "", "api": ""}, {"title": "A comparative risk assessment of burden of disease and injury attributable to 67 risk factors and risk factor clusters in 21 regions, 1990–2010: a systematic analysis for the Global Burden of Disease Study 2010", "doi": "https://doi.org/10.1016/s0140-6736(12)61766-8", "year": 2012, "authors": ["Stephen S Lim", "Theo Vos", "Abraham D Flaxman", "Goodarz Danaei", "Kenji Shibuya", "Heather Adair‐Rohani"], "source": "The Lancet", "cited": 12022, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s0140-6736(12)61766-8", "local_pdf": "", "api": ""}, {"title": "The measurement and antecedents of affective, continuance and normative commitment to the organization", "doi": "https://doi.org/10.1111/j.2044-8325.1990.tb00506.x", "year": 1990, "authors": ["Natalie J. Allen", "John P. Meyer"], "source": "Journal of Occupational Psychology", "cited": 11616, "abstract": "Organizational commitment has been conceptualized and measured in various ways. The two studies reported here were conducted to test aspects of a three‐component model of commitment which integrates these various conceptualizations. The affective component of organizational commitment, proposed by the model, refers to employees' emotional attachment to, identification with, and involvement in, the organization. The continuance component refers to commitment based on the costs that employees associate with leaving the organization. Finally, the normative component refers to employees' feelings of obligation to remain with the organization. In Study 1, scales were developed to measure these components. Relationships among the components of commitment and with variables considered their antec", "oa": true, "pdf_url": "https://doi.org/10.1111/j.2044-8325.1990.tb00506.x", "local_pdf": "", "api": ""}, {"title": "Best practices in exploratory factor analysis: four recommendations for getting the most from your analysis", "doi": "https://doi.org/10.7275/jyj1-4868", "year": 2020, "authors": ["Anna B. Costello", "Jason W. Osborne"], "source": "", "cited": 10324, "abstract": "Exploratory factor analysis (EFA) is a complex, multi-step process. The goal of this paper is to collect, in one article, information that will allow researchers and practitioners to understand the various choices available through popular software packages, and to make decisions about “best practices” in exploratory factor analysis. In particular, this paper provides practical information on making decisions regarding (a) extraction, (b) rotation, (c) the number of factors to interpret, and (d) sample size.", "oa": true, "pdf_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.110.9154", "local_pdf": "", "api": ""}, {"title": "FactoMineR : An R Package for Multivariate Analysis", "doi": "https://doi.org/10.18637/jss.v025.i01", "year": 2008, "authors": ["Sébastien Lê", "Julie Josse", "François Husson"], "source": "Journal of Statistical Software", "cited": 10239, "abstract": "In this article, we present FactoMineR an R package dedicated to multivariate data analysis. The main features of this package is the possibility to take into account different types of variables (quantitative or categorical), different types of structure on the data (a partition on the variables, a hierarchy on the variables, a partition on the individuals) and finally supplementary information (supplementary individuals and variables). Moreover, the dimensions issued from the different exploratory data analyses can be automatically described by quantitative and/or categorical variables. Numerous graphics are also available with various options. Finally, a graphical user interface is implemented within the Rcmdr environment in order to propose an user friendly package.", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v025.i01", "local_pdf": "", "api": ""}, {"title": "Principal component analysis: a review and recent developments", "doi": "https://doi.org/10.1098/rsta.2015.0202", "year": 2016, "authors": ["Ian T. Jolliffe", "Jorge Cadima"], "source": "Philosophical Transactions of the Royal Society A Mathematical Physical and Engineering Sciences", "cited": 9976, "abstract": "Large datasets are increasingly common and are often difficult to interpret. Principal component analysis (PCA) is a technique for reducing the dimensionality of such datasets, increasing interpretability but at the same time minimizing information loss. It does so by creating new uncorrelated variables that successively maximize variance. Finding such new variables, the principal components, reduces to solving an eigenvalue/eigenvector problem, and the new variables are defined by the dataset at hand, not a priori, hence making PCA an adaptive data analysis technique. It is adaptive in another sense too, since variants of the technique have been developed that are tailored to various different data types and structures. This article will begin by introducing the basic ideas of PCA, discus", "oa": true, "pdf_url": "https://doi.org/10.1098/rsta.2015.0202", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "Global burden of 87 risk factors in 204 countries and territories, 1990–2019: a systematic analysis for the Global Burden of Disease Study 2019", "doi": "https://doi.org/10.1016/s0140-6736(20)30752-2", "year": 2020, "authors": ["Christopher J L Murray", "Aleksandr Y. Aravkin", "Peng Zheng", "Cristiana Abbafati", "Kaja Abbas", "Mohsen Abbasi‐Kangevari"], "source": "The Lancet", "cited": 9892, "abstract": "BACKGROUND: Rigorous analysis of levels and trends in exposure to leading risk factors and quantification of their effect on human health are important to identify where public health is making progress and in which cases current efforts are inadequate. The Global Burden of Diseases, Injuries, and Risk Factors Study (GBD) 2019 provides a standardised and comprehensive assessment of the magnitude of risk factor exposure, relative risk, and attributable burden of disease. METHODS: GBD 2019 estimated attributable mortality, years of life lost (YLLs), years of life lived with disability (YLDs), and disability-adjusted life-years (DALYs) for 87 risk factors and combinations of risk factors, at the global level, regionally, and for 204 countries and territories. GBD uses a hierarchical list of r", "oa": true, "pdf_url": "https://doi.org/10.1016/s0140-6736(20)30752-2", "local_pdf": "", "api": ""}, {"title": "Global, regional, and national burden of stroke and its risk factors, 1990–2019: a systematic analysis for the Global Burden of Disease Study 2019", "doi": "https://doi.org/10.1016/s1474-4422(21)00252-0", "year": 2021, "authors": ["Valery L. Feigin", "Benjamin Stark", "Catherine O. Johnson", "Gregory A. Roth", "Catherine Bisignano", "Gdiom Gebreheat Abady"], "source": "The Lancet Neurology", "cited": 8041, "abstract": "BACKGROUND: Regularly updated data on stroke and its pathological types, including data on their incidence, prevalence, mortality, disability, risk factors, and epidemiological trends, are important for evidence-based stroke care planning and resource allocation. The Global Burden of Diseases, Injuries, and Risk Factors Study (GBD) aims to provide a standardised and comprehensive measurement of these metrics at global, regional, and national levels. METHODS: We applied GBD 2019 analytical tools to calculate stroke incidence, prevalence, mortality, disability-adjusted life-years (DALYs), and the population attributable fraction (PAF) of DALYs (with corresponding 95% uncertainty intervals [UIs]) associated with 19 risk factors, for 204 countries and territories from 1990 to 2019. These estim", "oa": true, "pdf_url": "http://www.thelancet.com/article/S1474442221002520/pdf", "local_pdf": "", "api": ""}, {"title": "CLUMPP: a cluster matching and permutation program for dealing with label switching and multimodality in analysis of population structure", "doi": "https://doi.org/10.1093/bioinformatics/btm233", "year": 2007, "authors": ["Mattias Jakobsson", "Noah A. Rosenberg"], "source": "Bioinformatics", "cited": 6530, "abstract": "MOTIVATION: Clustering of individuals into populations on the basis of multilocus genotypes is informative in a variety of settings. In population-genetic clustering algorithms, such as BAPS, STRUCTURE and TESS, individual multilocus genotypes are partitioned over a set of clusters, often using unsupervised approaches that involve stochastic simulation. As a result, replicate cluster analyses of the same data may produce several distinct solutions for estimated cluster membership coefficients, even though the same initial conditions were used. Major differences among clustering solutions have two main sources: (1) 'label switching' of clusters across replicates, caused by the arbitrary way in which clusters in an unsupervised analysis are labeled, and (2) 'genuine multimodality,' truly dis", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/23/14/1801/49812983/bioinformatics_23_14_1801.pdf", "local_pdf": "", "api": ""}, {"title": "Canonical Correspondence Analysis: A New Eigenvector Technique for Multivariate Direct Gradient Analysis", "doi": "https://doi.org/10.2307/1938672", "year": 1986, "authors": ["Cajo J. F. ter Braak"], "source": "Ecology", "cited": 6002, "abstract": "A new multivariate analysis technique, developed to relate community composition to known variation in the environment, is described. The technique is an extension of correspondence analysis (reciprocal averaging), a popular ordination technique that extracts continuous axes of variation from species occurrence or abundance data. Such ordination axes are typically interpreted with the help of external knowledge and data on environmental variables; this two—step approach (ordination followed by environmental gradient identification) is termed indirect gradient analysis. In the new technique, called canonical correspondence analysis, ordination axes are chosen in the light of known environmental variables by imposing the extra restriction that the axes be linear combinations of environmental", "oa": true, "pdf_url": "https://doi.org/10.2307/1938672", "local_pdf": "", "api": ""}, {"title": "Discriminant analysis of principal components: a new method for the analysis of genetically structured populations", "doi": "https://doi.org/10.1186/1471-2156-11-94", "year": 2010, "authors": ["Thibaut Jombart", "Sébastien Devillard", "François Balloux"], "source": "BMC Genetics", "cited": 5199, "abstract": "BACKGROUND: The dramatic progress in sequencing technologies offers unprecedented prospects for deciphering the organization of natural populations in space and time. However, the size of the datasets generated also poses some daunting challenges. In particular, Bayesian clustering algorithms based on pre-defined population genetics models such as the STRUCTURE or BAPS software may not be able to cope with this unprecedented amount of data. Thus, there is a need for less computer-intensive approaches. Multivariate analyses seem particularly appealing as they are specifically devoted to extracting information from large datasets. Unfortunately, currently available multivariate methods still lack some essential features needed to study the genetic structure of natural populations. RESULTS: W", "oa": true, "pdf_url": "https://bmcgenomdata.biomedcentral.com/counter/pdf/10.1186/1471-2156-11-94", "local_pdf": "001_A new criterion for assessing discrimina.pdf", "api": ""}, {"title": "Broad patterns of gene expression revealed by clustering analysis of tumor and normal colon tissues probed by oligonucleotide arrays", "doi": "https://doi.org/10.1073/pnas.96.12.6745", "year": 1999, "authors": ["Uri Alon", "Naama Barkai", "Daniel A. Notterman", "Kurt Gish", "Suzanne E. Ybarra", "David H. Mack"], "source": "Proceedings of the National Academy of Sciences", "cited": 4219, "abstract": "Oligonucleotide arrays can provide a broad picture of the state of the cell, by monitoring the expression level of thousands of genes at the same time. It is of interest to develop techniques for extracting useful information from the resulting data sets. Here we report the application of a two-way clustering method for analyzing a data set consisting of the expression patterns of different cell types. Gene expression in 40 tumor and 22 normal colon tissue samples was analyzed with an Affymetrix oligonucleotide array complementary to more than 6,500 human genes. An efficient two-way clustering algorithm was applied to both the genes and the tissues, revealing broad coherent patterns that suggest a high degree of organization underlying gene expression in these tissues. Coregulated families", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.96.12.6745", "local_pdf": "", "api": ""}, {"title": "ClustVis: a web tool for visualizing clustering of multivariate data using Principal Component Analysis and heatmap", "doi": "https://doi.org/10.1093/nar/gkv468", "year": 2015, "authors": ["Tauno Metsalu", "Jaak Vilo"], "source": "Nucleic Acids Research", "cited": 4016, "abstract": "The Principal Component Analysis (PCA) is a widely used method of reducing the dimensionality of high-dimensional data, often followed by visualizing two of the components on the scatterplot. Although widely used, the method is lacking an easy-to-use web interface that scientists with little programming skills could use to make plots of their own data. The same applies to creating heatmaps: it is possible to add conditional formatting for Excel cells to show colored heatmaps, but for more advanced features such as clustering and experimental annotations, more sophisticated analysis tools have to be used. We present a web tool called ClustVis that aims to have an intuitive user interface. Users can upload data from a simple delimited text file that can be created in a spreadsheet program. I", "oa": true, "pdf_url": "https://academic.oup.com/nar/article-pdf/43/W1/W566/7476330/gkv468.pdf", "local_pdf": "", "api": ""}, {"title": "Probabilistic Principal Component Analysis", "doi": "https://doi.org/10.1111/1467-9868.00196", "year": 1999, "authors": ["Michael E. Tipping", "Chris Bishop"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 3756, "abstract": "Summary Principal component analysis (PCA) is a ubiquitous technique for data analysis and processing, but one which is not based on a probability model. We demonstrate how the principal axes of a set of observed data vectors may be determined through maximum likelihood estimation of parameters in a latent variable model that is closely related to factor analysis. We consider the properties of the associated likelihood function, giving an EM algorithm for estimating the principal subspace iteratively, and discuss, with illustrative examples, the advantages conveyed by this probabilistic approach to PCA.", "oa": true, "pdf_url": "https://academic.oup.com/jrsssb/article-pdf/61/3/611/49589634/jrsssb_61_3_611.pdf", "local_pdf": "", "api": ""}, {"title": "A Beginner’s Guide to Factor Analysis: Focusing on Exploratory Factor Analysis", "doi": "https://doi.org/10.20982/tqmp.09.2.p079", "year": 2013, "authors": ["An Gie Yong", "Sean Pearce"], "source": "Tutorials in Quantitative Methods for Psychology", "cited": 3312, "abstract": "The following paper discusses exploratory factor analysis and gives an overview of the statistical technique and how it is used in various research designs and applications. A basic outline of how the technique works and its criteria, including its main assumptions are discussed as well as when it should be used. Mathematical theories are explored to enlighten students on how exploratory factor analysis works, an example of how to run an exploratory factor analysis on SPSS is given, and finally a section on how to write up the results is provided. This will allow readers to develop a better understanding of when to employ factor analysis and how to interpret the tables and graphs in the output. The broad purpose of factor analysis is to summarize data so that relationships and patterns can", "oa": true, "pdf_url": "https://www.tqmp.org/RegularArticles/vol09-2/p079/p079.pdf", "local_pdf": "019_A Beginner’s Guide to Factor Analysis_ F.pdf", "api": ""}, {"title": "An Empirical Evaluation of Alternative Methods of Estimation for Confirmatory Factor Analysis With Ordinal Data.", "doi": "https://doi.org/10.1037/1082-989x.9.4.466", "year": 2004, "authors": ["David B. Flora", "Patrick J. Curran"], "source": "Psychological Methods", "cited": 3014, "abstract": "Confirmatory factor analysis (CFA) is widely used for examining hypothesized relations among ordinal variables (e.g., Likert-type items). A theoretically appropriate method fits the CFA model to polychoric correlations using either weighted least squares (WLS) or robust WLS. Importantly, this approach assumes that a continuous, normal latent process determines each observed variable. The extent to which violations of this assumption undermine CFA estimation is not well-known. In this article, the authors empirically study this issue using a computer simulation study. The results suggest that estimation of polychoric correlations is robust to modest violations of underlying normality. Further, WLS performed adequately only at the largest sample size but led to substantial estimation difficu", "oa": true, "pdf_url": "https://doi.org/10.1037/1082-989x.9.4.466", "local_pdf": "", "api": ""}, {"title": "Confirmatory factor analysis with ordinal data: Comparing robust maximum likelihood and diagonally weighted least squares", "doi": "https://doi.org/10.3758/s13428-015-0619-7", "year": 2015, "authors": ["Cheng-Hsien Li"], "source": "Behavior Research Methods", "cited": 2990, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13428-015-0619-7.pdf", "local_pdf": "021_Confirmatory factor analysis with ordina.pdf", "api": ""}, {"title": "Principal component analysis", "doi": "https://doi.org/10.1039/c3ay41907j", "year": 2014, "authors": ["Rasmus Bro", "Age K. Smilde"], "source": "Analytical Methods", "cited": 2958, "abstract": "Principal component analysis is one of the most important and powerful methods in chemometrics as well as in a wealth of other areas.", "oa": true, "pdf_url": "https://pubs.rsc.org/en/content/articlepdf/2014/ay/c3ay41907j", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "A high-performance computing toolset for relatedness and principal component analysis of SNP data", "doi": "https://doi.org/10.1093/bioinformatics/bts606", "year": 2012, "authors": ["Xiuwen Zheng", "David Levine", "Jess Shen", "Stephanie M. Gogarten", "Cathy C. Laurie", "Bruce S. Weir"], "source": "Bioinformatics", "cited": 2836, "abstract": "Abstract Summary: Genome-wide association studies are widely used to investigate the genetic basis of diseases and traits, but they pose many computational challenges. We developed gdsfmt and SNPRelate (R packages for multi-core symmetric multiprocessing computer architectures) to accelerate two key computations on SNP data: principal component analysis (PCA) and relatedness analysis using identity-by-descent measures. The kernels of our algorithms are written in C/C++ and highly optimized. Benchmarks show the uniprocessor implementations of PCA and identity-by-descent are ∼8–50 times faster than the implementations provided in the popular EIGENSTRAT (v3.0) and PLINK (v1.07) programs, respectively, and can be sped up to 30–300-fold by using eight cores. SNPRelate can analyse tens of thousa", "oa": true, "pdf_url": "https://doi.org/10.1093/bioinformatics/bts606", "local_pdf": "", "api": ""}, {"title": "Novel subgroups of adult-onset diabetes and their association with outcomes: a data-driven cluster analysis of six variables", "doi": "https://doi.org/10.1016/s2213-8587(18)30051-2", "year": 2018, "authors": ["Emma Ahlqvist", "Petter Storm", "Annemari Käräjämäki", "Mats Martinell", "Mozhgan Dorkhan", "Annelie Carlsson"], "source": "The Lancet Diabetes & Endocrinology", "cited": 2358, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/s2213-8587(18)30051-2", "local_pdf": "", "api": ""}, {"title": "Normalization of RNA-seq data using factor analysis of control genes or samples", "doi": "https://doi.org/10.1038/nbt.2931", "year": 2014, "authors": ["Davide Risso", "John Ngai", "Terence P. Speed", "Sandrine Dudoit"], "source": "Nature Biotechnology", "cited": 2355, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nbt.2931.pdf", "local_pdf": "", "api": ""}, {"title": "FactoMineR: An R Package for Multivariate Analysis", "doi": null, "year": 2008, "authors": ["Sébastien Lê", "Agrocampus Rennes", "Julie Josse", "Agrocampus Rennes", "François Husson", "Agrocampus Rennes"], "source": "", "cited": 2285, "abstract": "In this article, we present FactoMineR an R package dedicated to multivariate data analysis. The main features of this package is the possibility to take into account different types of variables (quantitative or categorical), different types of structure on the data (a partition on the variables, a hierarchy on the variables, a partition on the individuals) and finally supplementary information (supplementary individuals and variables). Moreover, the dimensions issued from the different exploratory data analyses can be automatically described by quantitative and/or categorical variables. Numerous graphics are also available with various options. Finally, a graphical user interface is implemented within the Rcmdr environment in order to propose an user friendly package.", "oa": true, "pdf_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.422.7829", "local_pdf": "", "api": ""}, {"title": "Regularized Discriminant Analysis", "doi": "https://doi.org/10.1080/01621459.1989.10478752", "year": 1989, "authors": ["Jerome H. Friedman"], "source": "Journal of the American Statistical Association", "cited": 2267, "abstract": "Linear and quadratic discriminant analysis are considered in the small-sample, high-dimensional setting. Alternatives to the usual maximum likelihood (plug-in) estimates for the covariance matrices are proposed. These alternatives are characterized by two parameters, the values of which are customized to individual situations by jointly minimizing a sample-based estimate of future misclassification risk. Computationally fast implementations are presented, and the efficacy of the approach is examined through simulation studies and application to data. These studies indicate that in many circumstances dramatic gains in classification accuracy can be achieved.", "oa": true, "pdf_url": "https://doi.org/10.1080/01621459.1989.10478752", "local_pdf": "", "api": ""}, {"title": "Factor Retention Decisions in Exploratory Factor Analysis: a Tutorial on Parallel Analysis", "doi": "10.1177/1094428104263675", "year": 2004, "authors": ["James C. Hayton", "David G. Allen", "Vida Scarpello"], "source": "Organizational Research Methods", "cited": 2264, "abstract": " The decision of how many factors to retain is a critical component of exploratory factor analysis. Evidence is presented that parallel analysis is one of the most accurate factor retention methods while also being one of the most underutilized in management and organizational research. Therefore, a step-by-step guide to performing parallel analysis is described, and an example is provided using data from the Minnesota Satisfaction Questionnaire. Recommendations for making factor retention decisions are discussed. ", "oa": true, "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/1094428104263675", "local_pdf": "", "api": "crossref"}, {"title": "Factor Analysis as a Tool for Survey Analysis", "doi": "https://doi.org/10.12691/ajams-9-1-2", "year": 2021, "authors": ["Noora Shrestha"], "source": "American Journal of Applied Mathematics and Statistics", "cited": 2239, "abstract": "Factor analysis is particularly suitable to extract few factors from the large number of related variables to a more manageable number, prior to using them in other analysis such as multiple regression or multivariate analysis of variance. It can be beneficial in developing of a questionnaire. Sometimes adding more statements in the questionnaire fail to give clear understanding of the variables. With the help of factor analysis, irrelevant questions can be removed from the final questionnaire. This study proposed a factor analysis to identify the factors underlying the variables of a questionnaire to measure tourist satisfaction. In this study, Kaiser-Meyer-Olkin measure of sampling adequacy and Bartlett’s test of Sphericity are used to assess the factorability of the data. Determinant sc", "oa": true, "pdf_url": "https://doi.org/10.12691/ajams-9-1-2", "local_pdf": "019_A Beginner’s Guide to Factor Analysis_ F.pdf", "api": ""}, {"title": "Exploratory Factor Analysis: A Guide to Best Practice", "doi": "https://doi.org/10.1177/0095798418771807", "year": 2018, "authors": ["Marley W. Watkins"], "source": "Journal of Black Psychology", "cited": 2193, "abstract": "Exploratory factor analysis (EFA) is a multivariate statistical method that has become a fundamental tool in the development and validation of psychological theories and measurements. However, researchers must make several thoughtful and evidence-based methodological decisions while conducting an EFA, and there are a number of options available at each decision point, some better than others. Reviews of the professional literature have consistently found that many applications of EFA are marked by an injudicious choice of methods and incomplete reports. This article provides a systematic, evidence-based guide to the conduct of EFA studies that can be followed by researchers with modest statistical training, supplemented with an example to illustrate its application.", "oa": true, "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/0095798418771807", "local_pdf": "", "api": ""}, {"title": "Identification of Asthma Phenotypes Using Cluster Analysis in the Severe Asthma Research Program", "doi": "https://doi.org/10.1164/rccm.200906-0896oc", "year": 2009, "authors": ["Wendy C. Moore", "Deborah A. Meyers", "Sally E. Wenzel", "W. Gerald Teague", "Huashi Li", "Xingnan Li"], "source": "American Journal of Respiratory and Critical Care Medicine", "cited": 2146, "abstract": "RATIONALE: The Severe Asthma Research Program cohort includes subjects with persistent asthma who have undergone detailed phenotypic characterization. Previous univariate methods compared features of mild, moderate, and severe asthma. OBJECTIVES: To identify novel asthma phenotypes using an unsupervised hierarchical cluster analysis. METHODS: Reduction of the initial 628 variables to 34 core variables was achieved by elimination of redundant data and transformation of categorical variables into ranked ordinal composite variables. Cluster analysis was performed on 726 subjects. MEASUREMENTS AND MAIN RESULTS: Five groups were identified. Subjects in Cluster 1 (n = 110) have early onset atopic asthma with normal lung function treated with two or fewer controller medications (82%) and minimal ", "oa": true, "pdf_url": "https://doi.org/10.1164/rccm.200906-0896oc", "local_pdf": "", "api": ""}, {"title": "On the distribution of the largest eigenvalue in principal components analysis", "doi": "https://doi.org/10.1214/aos/1009210544", "year": 2001, "authors": ["Iain M. Johnstone"], "source": "The Annals of Statistics", "cited": 2049, "abstract": "Let x(1) denote the square of the largest singular value of an n × p matrix X, all of whose entries are independent standard Gaussian variates. Equivalently, x(1) is the largest principal component variance of the covariance matrix $X'X$, or the largest eigenvalue of a p­variate Wishart distribution on n degrees of freedom with identity covariance. Consider the limit of large p and n with $n/p = \\gamma \\ge 1$. When centered by $\\mu_p = (\\sqrt{n-1} + \\sqrt{p})^2$ and scaled by $\\sigma_p = (\\sqrt{n-1} + \\sqrt{p})(1/\\sqrt{n-1} + 1/\\sqrt{p}^{1/3}$, the distribution of x(1) approaches the Tracey-Widom law of order 1, which is defined in terms of the Painlevé II differential equation and can be numerically evaluated and tabulated in software. Simulations show the approximation to be informative ", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-29/issue-2/On-the-distribution-of-the-largest-eigenvalue-in-principal-components/10.1214/aos/1009210544.pdf", "local_pdf": "", "api": ""}, {"title": "Cluster Analysis and Clinical Asthma Phenotypes", "doi": "https://doi.org/10.1164/rccm.200711-1754oc", "year": 2008, "authors": ["Pranabashis Haldar", "Ian Pavord", "Dominick Shaw", "Michael A. Berry", "Michael Thomas", "Christopher E. Brightling"], "source": "American Journal of Respiratory and Critical Care Medicine", "cited": 2017, "abstract": "RATIONALE: Heterogeneity in asthma expression is multidimensional, including variability in clinical, physiologic, and pathologic parameters. Classification requires consideration of these disparate domains in a unified model. OBJECTIVES: To explore the application of a multivariate mathematical technique, k-means cluster analysis, for identifying distinct phenotypic groups. METHODS: We performed k-means cluster analysis in three independent asthma populations. Clusters of a population managed in primary care (n = 184) with predominantly mild to moderate disease, were compared with a refractory asthma population managed in secondary care (n = 187). We then compared differences in asthma outcomes (exacerbation frequency and change in corticosteroid dose at 12 mo) between clusters in a third", "oa": true, "pdf_url": "https://doi.org/10.1164/rccm.200711-1754oc", "local_pdf": "", "api": ""}, {"title": "Canonical correspondence analysis and related multivariate methods in aquatic ecology", "doi": "https://doi.org/10.1007/bf00877430", "year": 1995, "authors": ["Cajo J. F. ter Braak", "P.F.M. Verdonschot"], "source": "Aquatic Sciences", "cited": 1953, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1007/bf00877430", "local_pdf": "", "api": ""}, {"title": "Applied Psychometrics: Sample Size and Sample Power Considerations in Factor Analysis (EFA, CFA) and SEM in General", "doi": "https://doi.org/10.4236/psych.2018.98126", "year": 2018, "authors": ["Theodoros Kyriazos"], "source": "Psychology", "cited": 1874, "abstract": "Adequate statistical power contributes to observing true relationships in a dataset. With a thoughtful power analysis, the adequate but not excessive sample could be detected. Therefore, this paper reviews the issue of what sample size and sample power the researcher should have in the EFA, CFA, and SEM study. Statistical power is the estimation of the sample size that is appropriate for an analysis. In any study, four parameters related to power analysis are Alpha, Beta, statistical power and Effect size. They are prerequisites for a priori sample size determination. Scale development in general and Factor Analysis (EFA, CFA) and SEM are large sample size methods because sample affects precision and replicability of the results. However, the existing literature provides limited and someti", "oa": true, "pdf_url": "http://www.scirp.org/journal/PaperDownload.aspx?paperID=86856", "local_pdf": "", "api": ""}, {"title": "Genesis: cluster analysis of microarray data", "doi": "https://doi.org/10.1093/bioinformatics/18.1.207", "year": 2002, "authors": ["Alexander Sturn", "John Quackenbush", "Zlatko Trajanoski"], "source": "Bioinformatics", "cited": 1813, "abstract": "A versatile, platform independent and easy to use Java suite for large-scale gene expression analysis was developed. Genesis integrates various tools for microarray data analysis such as filters, normalization and visualization tools, distance measures as well as common clustering algorithms including hierarchical clustering, self-organizing maps, k-means, principal component analysis, and support vector machines. The results of the clustering are transparent across all implemented methods and enable the analysis of the outcome of different algorithms and parameters. Additionally, mapping of gene expression data onto chromosomal sequences was implemented to enhance promoter analysis and investigation of transcriptional control mechanisms.", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/18/1/207/48850312/bioinformatics_18_1_207.pdf", "local_pdf": "", "api": ""}, {"title": "Discrete Multivariate Analysis: Theory and Practice.", "doi": "https://doi.org/10.2307/2344845", "year": 1976, "authors": ["R. L. Plackett", "Yvonne Bishop", "Stephen E. Fienberg", "Paul W. Holland"], "source": "Journal of the Royal Statistical Society Series A (General)", "cited": 1755, "abstract": "computer software, or by similar or dissimilar methodology now known or hereafter developed is forbidden.The use in this publication of trade names, trademarks, service marks, and similar terms, even if they are not identifi ed as such, is not to be taken as an expression of opinion as to whether or not they are subject to proprietary rights.", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f2344845", "local_pdf": "", "api": ""}, {"title": "A penalized matrix decomposition, with applications to sparse principal components and canonical correlation analysis", "doi": "https://doi.org/10.1093/biostatistics/kxp008", "year": 2009, "authors": ["Daniela Witten", "Robert Tibshirani", "Trevor Hastie"], "source": "Biostatistics", "cited": 1630, "abstract": "We present a penalized matrix decomposition (PMD), a new framework for computing a rank-K approximation for a matrix. We approximate the matrix X as circumflexX = sigma(k=1)(K) d(k)u(k)v(k)(T), where d(k), u(k), and v(k) minimize the squared Frobenius norm of X - circumflexX, subject to penalties on u(k) and v(k). This results in a regularized version of the singular value decomposition. Of particular interest is the use of L(1)-penalties on u(k) and v(k), which yields a decomposition of X using sparse vectors. We show that when the PMD is applied using an L(1)-penalty on v(k) but not on u(k), a method for sparse principal components results. In fact, this yields an efficient algorithm for the \"SCoTLASS\" proposal (Jolliffe and others 2003) for obtaining sparse principal components. This me", "oa": true, "pdf_url": "https://academic.oup.com/biostatistics/article-pdf/10/3/515/17735953/kxp008.pdf", "local_pdf": "", "api": ""}, {"title": "An Introduction to Multivariate Statistical Analysis", "doi": "https://doi.org/10.1198/tech.2004.s754", "year": 2004, "authors": [], "source": "Technometrics", "cited": 1613, "abstract": "", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/abs/10.1198/tech.2004.s754", "local_pdf": "", "api": ""}, {"title": "Multi‐Omics Factor Analysis—a framework for unsupervised integration of multi‐omics data sets", "doi": "https://doi.org/10.15252/msb.20178124", "year": 2018, "authors": ["Ricard Argelaguet", "Britta Velten", "Damien Arnol", "Sascha Dietrich", "Thorsten Zenz", "John C. Marioni"], "source": "Molecular Systems Biology", "cited": 1582, "abstract": "Abstract Multi‐omics studies promise the improved characterization of biological processes across molecular layers. However, methods for the unsupervised integration of the resulting heterogeneous data sets are lacking. We present Multi‐Omics Factor Analysis (MOFA), a computational method for discovering the principal sources of variation in multi‐omics data sets. MOFA infers a set of (hidden) factors that capture biological and technical sources of variability. It disentangles axes of heterogeneity that are shared across multiple modalities and those specific to individual data modalities. The learnt factors enable a variety of downstream analyses, including identification of sample subgroups, data imputation and the detection of outlier samples. We applied MOFA to a cohort of 200 patient", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.15252/msb.20178124", "local_pdf": "", "api": ""}, {"title": "ECOLOGICAL-NICHE FACTOR ANALYSIS: HOW TO COMPUTE HABITAT-SUITABILITY MAPS WITHOUT ABSENCE DATA?", "doi": "https://doi.org/10.1890/0012-9658(2002)083[2027:enfaht]2.0.co;2", "year": 2002, "authors": ["Alexandre H. Hirzel", "Jean Hausser", "Daniel Chessel", "Nicolas Perrin"], "source": "Ecology", "cited": 1461, "abstract": "We propose a multivariate approach to the study of geographic species distribution which does not require absence data. Building on Hutchinson's concept of the ecological niche, this factor analysis compares, in the multidimensional space of ecological variables, the distribution of the localities where the focal species was observed to a reference set describing the whole study area. The first factor extracted maximizes the marginality of the focal species, defined as the ecological distance between the species optimum and the mean habitat within the reference area. The other factors maximize the specialization of this focal species, defined as the ratio of the ecological variance in mean habitat to that observed for the focal species. Eigenvectors and eigenvalues are readily interpreted ", "oa": true, "pdf_url": "https://doi.org/10.1890/0012-9658(2002)083[2027:enfaht]2.0.co;2", "local_pdf": "", "api": ""}, {"title": "Principal component analysis", "doi": "https://doi.org/10.1038/nmeth.4346", "year": 2017, "authors": ["Jake Lever", "Martin Krzywinski", "Naomi Altman"], "source": "Nature Methods", "cited": 1449, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.4346.pdf", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "Quantum principal component analysis", "doi": "https://doi.org/10.1038/nphys3029", "year": 2014, "authors": ["Seth Lloyd", "Masoud Mohseni", "Patrick Rebentrost"], "source": "Nature Physics", "cited": 1412, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nphys3029.pdf", "local_pdf": "", "api": ""}, {"title": "FACTOR: A computer program to fit the exploratory factor analysis model", "doi": "https://doi.org/10.3758/bf03192753", "year": 2006, "authors": ["Urbano Lorenzo‐Seva", "Pere J. Ferrando"], "source": "Behavior Research Methods", "cited": 1337, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/BF03192753.pdf", "local_pdf": "", "api": ""}, {"title": "Principal component analysis for clustering gene expression data", "doi": "https://doi.org/10.1093/bioinformatics/17.9.763", "year": 2001, "authors": ["Ka Yee Yeung", "Walter L. Ruzzo"], "source": "Bioinformatics", "cited": 1302, "abstract": "MOTIVATION: There is a great need to develop analytical methodology to analyze and to exploit the information contained in gene expression data. Because of the large number of genes and the complexity of biological networks, clustering is a useful exploratory technique for analysis of gene expression data. Other classical techniques, such as principal component analysis (PCA), have also been applied to analyze gene expression data. Using different data analysis techniques and different clustering algorithms to analyze the same data set can lead to very different conclusions. Our goal is to study the effectiveness of principal components (PCs) in capturing cluster structure. Specifically, using both real and synthetic gene expression data sets, we compared the quality of clusters obtained f", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/17/9/763/539767/170763.pdf", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "Codon usage in yeast: cluster analysis clearly differentiates highly and lowly expressed genes", "doi": "https://doi.org/10.1093/nar/14.13.5125", "year": 1986, "authors": ["Paul M. Sharp", "Thérèse M.F. Tuohy", "Krzysztof Mosurski"], "source": "Nucleic Acids Research", "cited": 1270, "abstract": "Codon usage data has been compiled for 110 yeast genes. Cluster analysis on relative synonymous codon usage revealed two distinct groups of genes. One group corresponds to highly expressed genes, and has much more extreme synonymous codon preference. The pattern of codon usage observed is consistent with that expected if a need to match abundant tRNAs, and intermediacy of tRNA-mRNA interaction energies are important selective constraints. Thus codon usage in the highly expressed group shows a higher correlation with tRNA abundance, a greater degree of third base pyrimidine bias, and a lesser tendency to the A+T richness which is characteristic of the yeast genome. The cluster analysis can be used to predict the likely level of gene expression of any gene, and identifies the pattern of codo", "oa": true, "pdf_url": "https://doi.org/10.1093/nar/14.13.5125", "local_pdf": "", "api": ""}, {"title": "Practical Considerations for Using Exploratory Factor Analysis in Educational Research", "doi": "https://doi.org/10.7275/qv2q-rk76", "year": 2020, "authors": ["Amy S. Beavers", "John W. Lounsbury", "Jennifer Richards", "Schuyler W. Huck", "Gary Skolits", "Shelley L. Esquivel"], "source": "", "cited": 1254, "abstract": "The uses and methodology of factor analysis are widely debated and discussed, especially the issues of rotational use, methods of confirmatory factor analysis, and adequate sample size. The variety of perspectives and often conflicting opinions can lead to confusion among researchers about best practices for using factor analysis. The focus of the present review is to clarify terminology, identify key issues, and clarify areas of debate regarding best practices and functions of factor analytic procedures., The conclusions and implications drawn should be useful to researchers in education, psychology, and cognate social fields who employ factor analytic procedures or evaluate research using factor analytic methods. Accessed 27,993 times on https://pareonline.net from March 05, 2013 to Dece", "oa": true, "pdf_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.500.1714", "local_pdf": "", "api": ""}, {"title": "Empirically Derived Eating Patterns Using Factor or Cluster Analysis: A Review", "doi": "https://doi.org/10.1111/j.1753-4887.2004.tb00040.x", "year": 2004, "authors": ["P.K. Newby", "Katherine L. Tucker"], "source": "Nutrition Reviews", "cited": 1200, "abstract": "This paper reviews studies performed to date that have employed cluster or factor analysis to empirically derive eating patterns. Since 1980, at least 93 studies were published that used cluster or factor analysis to define dietary exposures, of which 65 were used to test hypotheses or examine associations between patterns and disease outcomes or biomarkers. Studies were conducted in diverse populations across many countries and continents and suggest that patterns are associated with many different biomarkers and disease outcomes, whether measured by cluster or factor analysis. Despite clear differences in approaches and interpretations, there is some evidence that underlying eating patterns are revealed by either method. Although the research considered herein has created a meaningful bo", "oa": true, "pdf_url": "https://academic.oup.com/nutritionreviews/article-pdf/62/5/177/24091072/nutritionreviews62-0177.pdf", "local_pdf": "", "api": ""}, {"title": "Multivariate Analysis in Metabolomics", "doi": "https://doi.org/10.2174/2213235x11301010092", "year": 2012, "authors": ["Bradley Worley", "Robert Powers"], "source": "Current Metabolomics", "cited": 1183, "abstract": "Metabolomics aims to provide a global snapshot of all small-molecule metabolites in cells and biological fluids, free of observational biases inherent to more focused studies of metabolism. However, the staggeringly high information content of such global analyses introduces a challenge of its own; efficiently forming biologically relevant conclusions from any given metabolomics dataset indeed requires specialized forms of data analysis. One approach to finding meaning in metabolomics datasets involves multivariate analysis (MVA) methods such as principal component analysis (PCA) and partial least squares projection to latent structures (PLS), where spectral features contributing most to variation or separation are identified for further analysis. However, as with any mathematical treatmen", "oa": true, "pdf_url": "https://doi.org/10.2174/2213235x11301010092", "local_pdf": "", "api": ""}, {"title": "Asymptotic Theory for Principal Component Analysis", "doi": "https://doi.org/10.1214/aoms/1177704248", "year": 1963, "authors": ["T. W. Anderson"], "source": "The Annals of Mathematical Statistics", "cited": 1172, "abstract": "Abstract : The asymptotic distribution of the characteristic roots and (normalized) vectors of a sample covariance matrix is given when the observations are from a multivariate normal distribution whose covariance matrix has characteristic roots of arbitrary multiplicity. The elements of each characteristic vector are the coefficients of a principal component (with sum of squares of coefficients being unity), and the corresponding characteristic root is the variance of the principal component. Tests of hypotheses of equality of population roots are treated, and confidence intervals for assumed equal roots are given; these are useful in assessing the importance of principal components. A similar study for correlation matrices is considered. (Author)", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-34/issue-1/Asymptotic-Theory-for-Principal-Component-Analysis/10.1214/aoms/1177704248.pdf", "local_pdf": "", "api": ""}, {"title": "Inflammatory endotypes of chronic rhinosinusitis based on cluster analysis of biomarkers", "doi": "https://doi.org/10.1016/j.jaci.2015.12.1324", "year": 2016, "authors": ["Peter Tomassen", "Griet Vandeplas", "Thibaut Van Zele", "Lars‐Olaf Cardell", "Julia Arebro", "Heidi Olze"], "source": "Journal of Allergy and Clinical Immunology", "cited": 1167, "abstract": "", "oa": true, "pdf_url": "http://www.jacionline.org/article/S0091674916001846/pdf", "local_pdf": "", "api": ""}, {"title": "The Past, Present, and Future of Virtual and Augmented Reality Research: A Network and Cluster Analysis of the Literature", "doi": "https://doi.org/10.3389/fpsyg.2018.02086", "year": 2018, "authors": ["Pietro Cipresso", "Irene Alice Chicchi Giglioli", "Mariano Alcañíz", "Giuseppe Riva"], "source": "Frontiers in Psychology", "cited": 1154, "abstract": "The recent appearance of low cost virtual reality (VR) technologies - like the Oculus Rift, the HTC Vive and the Sony PlayStation VR - and Mixed Reality Interfaces (MRITF) - like the Hololens - is attracting the attention of users and researchers suggesting it may be the next largest stepping stone in technological innovation. However, the history of VR technology is longer than it may seem: the concept of VR was formulated in the 1960s and the first commercial VR tools appeared in the late 1980s. For this reason, during the last 20 years, 100s of researchers explored the processes, effects, and applications of this technology producing 1000s of scientific papers. What is the outcome of this significant research work? This paper wants to provide an answer to this question by exploring, usi", "oa": true, "pdf_url": "https://www.frontiersin.org/articles/10.3389/fpsyg.2018.02086/pdf", "local_pdf": "", "api": ""}, {"title": "Sample Size in Factor Analysis: The Role of Model Error", "doi": "https://doi.org/10.1207/s15327906mbr3604_06", "year": 2001, "authors": ["Robert C. MacCallum", "Keith F. Widaman", "Kristopher J. Preacher", "Sehee Hong"], "source": "Multivariate Behavioral Research", "cited": 1129, "abstract": "This article examines effects of sample size and other design features on correspondence between factors obtained from analysis of sample data and those present in the population from which the samples were drawn. We extend earlier work on this question by examining these phenomena in the situation in which the common factor model does not hold exactly in the population. We present a theoretical framework for representing such lack of fit and examine its implications in the population and sample. Based on this approach we hypothesize that lack of fit of the model in the population will not, on the average, influence recovery of population factors in analysis of sample data, regardless of degree of model error and regardless of sample size. Rather, such recovery will be affected only by phe", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/pdf/10.1207/S15327906MBR3604_06?needAccess=true&role=button", "local_pdf": "", "api": ""}, {"title": "An Extension of Box's Results on the Use of the $F$ Distribution in Multivariate Analysis", "doi": "https://doi.org/10.1214/aoms/1177706545", "year": 1958, "authors": ["Seymour Geisser", "Samuel W. Greenhouse"], "source": "The Annals of Mathematical Statistics", "cited": 1106, "abstract": "The mixed model in a 2-way analysis of variance is characterized by a fixed classification, e.g., treatments, and a random classification, e.g., plots or individuals. If we consider $k$ different treatments each applied to everyone of $n$ individuals, and assume the usual analysis of variance assumptions of uncorrelated errors, equal variances and normality, an appropriate analysis for the set of $nk$ observations $x_{ij}, i = 1, 2, \\cdots n, j = 1, 2, \\cdots k$, is ???? where the $F$ ratio under the null hypothesis has the $F$ distribution with $(k - 1)$ and $(k - 1)(n - 1)$ degrees of freedom. As is well known, if we extend the situation so that the errors have equal correlations instead of being uncorrelated, the $F$ ratio has the same distribution. Under the null hypothesis, the numera", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-29/issue-3/An-Extension-of-Boxs-Results-on-the-Use-of-the/10.1214/aoms/1177706545.pdf", "local_pdf": "", "api": ""}, {"title": "Nonlinear multivariate analysis of neurophysiological signals", "doi": "https://doi.org/10.1016/j.pneurobio.2005.10.003", "year": 2005, "authors": ["Ernesto Pereda", "Rodrigo Quian Quiroga", "Joydeep Bhattacharya"], "source": "Progress in Neurobiology", "cited": 1093, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.pneurobio.2005.10.003", "local_pdf": "", "api": ""}, {"title": "Understanding atmospheric organic aerosols via factor analysis of aerosol mass spectrometry: a review", "doi": "https://doi.org/10.1007/s00216-011-5355-y", "year": 2011, "authors": ["Qi Zhang", "J. L. Jiménez", "Manjula R. Canagaratna", "I. M. Ulbrich", "N. L. Ng", "Douglas R. Worsnop"], "source": "Analytical and Bioanalytical Chemistry", "cited": 1082, "abstract": "Organic species are an important but poorly characterized constituent of airborne particulate matter. A quantitative understanding of the organic fraction of particles (organic aerosol, OA) is necessary to reduce some of the largest uncertainties that confound the assessment of the radiative forcing of climate and air quality management policies. In recent years, aerosol mass spectrometry has been increasingly relied upon for highly time-resolved characterization of OA chemistry and for elucidation of aerosol sources and lifecycle processes. Aerodyne aerosol mass spectrometers (AMS) are particularly widely used, because of their ability to quantitatively characterize the size-resolved composition of submicron particles (PM(1)). AMS report the bulk composition and temporal variations of OA ", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/s00216-011-5355-y.pdf", "local_pdf": "", "api": ""}, {"title": "Linear discriminant analysis: A detailed tutorial", "doi": "https://doi.org/10.3233/aic-170729", "year": 2017, "authors": ["Alaa Tharwat", "Tarek Gaber", "Abdelhameed Ibrahim‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬‬", "Aboul Ella Hassanien"], "source": "AI Communications", "cited": 1082, "abstract": "Linear Discriminant Analysis (LDA) is a very common technique for dimensionality reduction problems as a pre-processing step for machine learning and pattern classification applications. At the same time, it is usually used as a black box, but (sometimes) not well understood. The aim of this paper is to build a solid intuition for what is LDA, and how LDA works, thus enabling readers of all levels be able to get a better understanding of the LDA and to know how to apply this technique in different applications. The paper first gave the basic definitions and steps of how LDA technique works supported with visual explanations of these steps. Moreover, the two methods of computing the LDA space, i.e. class-dependent and class-independent methods, were explained in details. Then, in a step-by-", "oa": true, "pdf_url": "https://doi.org/10.3233/aic-170729", "local_pdf": "", "api": ""}, {"title": "FACTOR ANALYSIS AND PSYCHOMETRIC EVALUATION OF THE CONNOR-DAVIDSON RESILIENCE SCALE (CD-RISC) WITH CHINESE PEOPLE", "doi": "https://doi.org/10.2224/sbp.2007.35.1.19", "year": 2006, "authors": ["Nancy Xiaonan Yu", "Jianxin Zhang"], "source": "Social Behavior and Personality An International Journal", "cited": 1059, "abstract": "This study examines the psychometric properties of the Chinese version of Connor and Davidson's Resilience Scale (CD-RISC; 2003), an American instrument originating from a posttraumatic stress disorder research program. Confirmatory factor analysis of the Chinese data failed to verify the original 5-factor structure of CD-RISC obtained in the USA, while exploratory factor analysis resulted in a 3-factor structure of resilience (labeled respectively as Tenacity, Strength, and Optimism). The reliability coefficient of the Chinese version of CD-RISC was 0.91. The validity of CD-RISC was also satisfying in terms of the actual data matching the expected correlation between resilience measure and the variables of selfesteem, life satisfaction, and personality trait factors of NEO-FFI. It is conc", "oa": true, "pdf_url": "https://doi.org/10.2224/sbp.2007.35.1.19", "local_pdf": "019_A Beginner’s Guide to Factor Analysis_ F.pdf", "api": ""}, {"title": "Sparse PLS discriminant analysis: biologically relevant feature selection and graphical displays for multiclass problems", "doi": "https://doi.org/10.1186/1471-2105-12-253", "year": 2011, "authors": ["Kim‐Anh Lê Cao", "Simon Boitard", "Philippe Besse"], "source": "BMC Bioinformatics", "cited": 1022, "abstract": "BACKGROUND: Variable selection on high throughput biological data, such as gene expression or single nucleotide polymorphisms (SNPs), becomes inevitable to select relevant information and, therefore, to better characterize diseases or assess genetic structure. There are different ways to perform variable selection in large data sets. Statistical tests are commonly used to identify differentially expressed features for explanatory purposes, whereas Machine Learning wrapper approaches can be used for predictive purposes. In the case of multiple highly correlated variables, another option is to use multivariate exploratory approaches to give more insight into cell biology, biological pathways or complex traits. RESULTS: A simple extension of a sparse PLS exploratory approach is proposed to pe", "oa": true, "pdf_url": "https://bmcbioinformatics.biomedcentral.com/counter/pdf/10.1186/1471-2105-12-253", "local_pdf": "", "api": ""}, {"title": "BotMiner: clustering analysis of network traffic for protocol- and structure-independent botnet detection", "doi": null, "year": 2008, "authors": ["Guofei Gu", "Roberto Perdisci", "Junjie Zhang", "Wenke Lee"], "source": "Journal of Bioresource Management", "cited": 1019, "abstract": "Botnets are now the key platform for many Internet attacks, such as spam, distributed denial-of-service (DDoS), identity theft, and phishing. Most of the current botnet detection approaches work only on specific botnet command and control (C&C) protocols (e.g., IRC) and structures (e.g., centralized), and can become ineffective as botnets change their C&C techniques. In this paper, we present a general detection framework that is independent of botnet C&C protocol and structure, and requires no a priori knowledge of botnets (such as captured bot binaries and hence the botnet signatures, and C&C server names/addresses). We start from the definition and essential properties of botnets. We define a botnet as a coordinated group of malware instances that are controlled via C&C communication ch", "oa": true, "pdf_url": "https://corescholar.libraries.wright.edu/cse/4", "local_pdf": "", "api": ""}, {"title": "Use of principal component analysis (PCA) and hierarchical cluster analysis (HCA) for multivariate association between bioactive compounds and functional properties in foods: A critical perspective", "doi": "https://doi.org/10.1016/j.tifs.2017.12.006", "year": 2017, "authors": ["Daniel Granato", "Jânio Sousa Santos", "Graziela Bragueto Escher", "Bruno Luís Ferreira", "Rubén M. Maggio"], "source": "Trends in Food Science & Technology", "cited": 1015, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.tifs.2017.12.006", "local_pdf": "", "api": ""}, {"title": "Item factor analysis: Current approaches and future directions.", "doi": "https://doi.org/10.1037/1082-989x.12.1.58", "year": 2007, "authors": ["R. Wirth", "Michael C. Edwards"], "source": "Psychological Methods", "cited": 909, "abstract": "The rationale underlying factor analysis applies to continuous and categorical variables alike; however, the models and estimation methods for continuous (i.e., interval or ratio scale) data are not appropriate for item-level data that are categorical in nature. The authors provide a targeted review and synthesis of the item factor analysis (IFA) estimation literature for ordered-categorical data (e.g., Likert-type response scales) with specific attention paid to the problems of estimating models with many items and many factors. Popular IFA models and estimation methods found in the structural equation modeling and item response theory literatures are presented. Following this presentation, recent developments in the estimation of IFA parameters (e.g., Markov chain Monte Carlo) are discus", "oa": true, "pdf_url": "https://doi.org/10.1037/1082-989x.12.1.58", "local_pdf": "", "api": ""}, {"title": "A tutorial review: Metabolomics and partial least squares-discriminant analysis – a marriage of convenience or a shotgun wedding", "doi": "https://doi.org/10.1016/j.aca.2015.02.012", "year": 2015, "authors": ["Piotr S. Gromski", "Howbeer Muhamadali", "David I. Ellis", "Yun Xu", "Elon Correa", "Michael L. Turner"], "source": "Analytica Chimica Acta", "cited": 908, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.aca.2015.02.012", "local_pdf": "", "api": ""}, {"title": "On Consistency and Sparsity for Principal Components Analysis in High Dimensions", "doi": "https://doi.org/10.1198/jasa.2009.0121", "year": 2009, "authors": ["Iain M. Johnstone", "Arthur Yu Lu"], "source": "Journal of the American Statistical Association", "cited": 906, "abstract": "Principal components analysis (PCA) is a classic method for the reduction of dimensionality of data in the form of n observations (or cases) of a vector with p variables. Contemporary datasets often have p comparable with or even much larger than n. Our main assertions, in such settings, are (a) that some initial reduction in dimensionality is desirable before applying any PCA-type search for principal modes, and (b) the initial reduction in dimensionality is best achieved by working in a basis in which the signals have a sparse representation. We describe a simple asymptotic model in which the estimate of the leading principal component vector via standard PCA is consistent if and only if p(n)/n→0. We provide a simple algorithm for selecting a subset of coordinates with largest sample var", "oa": true, "pdf_url": "https://doi.org/10.1198/jasa.2009.0121", "local_pdf": "", "api": ""}, {"title": "Repairing Tom Swift's Electric Factor Analysis Machine", "doi": "https://doi.org/10.1207/s15328031us0201_02", "year": 2003, "authors": ["Kristopher J. Preacher", "Robert C. MacCallum"], "source": "Understanding Statistics", "cited": 870, "abstract": "Proper use of exploratory factor analysis (EFA) requires the researcher to make a series of careful decisions. Despite attempts by Floyd and Widaman (1995), Fabrigar, Wegener, MacCallum, and Strahan (1999), and others to elucidate critical issues involved in these decisions, examples of questionable use of EFA are still common in the applied factor analysis literature. Poor decisions regarding the model to be used, the criteria used to decide how many factors to retain, and the rotation method can have drastic consequences for the quality and meaningfulness of factor analytic results. One commonly used approach-principal components analysis, retention of components with eigenvalues greater than 1.0, and varimax rotation of these components-is shown to have potentially serious negative cons", "oa": true, "pdf_url": "https://doi.org/10.1207/s15328031us0201_02", "local_pdf": "", "api": ""}, {"title": "Penalized Discriminant Analysis", "doi": "https://doi.org/10.1214/aos/1176324456", "year": 1995, "authors": ["Trevor Hastie", "Andreas Buja", "Robert Tibshirani"], "source": "The Annals of Statistics", "cited": 868, "abstract": "Fisher's linear discriminant analysis (LDA) is a popular data-analytic tool for studying the relationship between a set of predictors and a categorical response. In this paper we describe a penalized version of LDA. It is designed for situations in which there are many highly correlated predictors, such as those obtained by discretizing a function, or the grey-scale values of the pixels in a series of images. In cases such as these it is natural, efficient and sometimes essential to impose a spatial smoothness constraint on the coefficients, both for improved prediction performance and interpretability. We cast the classification problem into a regression framework via optimal scoring. Using this, our proposal facilitates the use of any penalized regression technique in the classification ", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-23/issue-1/Penalized-Discriminant-Analysis/10.1214/aos/1176324456.pdf", "local_pdf": "", "api": ""}, {"title": "Sample size and subject to item ratio in principal components analysis", "doi": "https://doi.org/10.7275/ktzq-jq66", "year": 2020, "authors": ["Jason W. Osborne", "Anna B. Costello"], "source": "ScholarWorks@UMassAmherst (University of Massachusetts Amherst)", "cited": 826, "abstract": "Statisticians have wrestled with the question of sample size in exploratory factor analysis and principal component analysis for decades, some looking at total N, some at the ratio of subjects to items. Although many articles attempt to examine this issue, few examine both possibilities comprehensively enough to be definitive. This study examines a previously published data set to examine whether N or subject to item ratio is more important in predicting important outcomes in PCA. The results indicate an interaction between the two, where the best outcomes occur in analyses where large Ns and high ratios are present. Accessed 116,372 times on https://pareonline.net from June 07, 2004 to December 31, 2019. For downloads from January 1, 2020 forward, please click on the PlumX Metrics link to", "oa": true, "pdf_url": "https://scholarworks.umass.edu/pare/vol9/iss1/11", "local_pdf": "", "api": ""}, {"title": "Coupled two-way clustering analysis of gene microarray data", "doi": "https://doi.org/10.1073/pnas.210134797", "year": 2000, "authors": ["Gad Getz", "Erel Levine", "Eytan Domany"], "source": "Proceedings of the National Academy of Sciences", "cited": 820, "abstract": "We present a coupled two-way clustering approach to gene microarray data analysis. The main idea is to identify subsets of the genes and samples, such that when one of these is used to cluster the other, stable and significant partitions emerge. The search for such subsets is a computationally complex task. We present an algorithm, based on iterative clustering, that performs such a search. This analysis is especially suitable for gene microarray data, where the contributions of a variety of biological mechanisms to the gene expression levels are entangled in a large body of experimental data. The method was applied to two gene microarray data sets, on colon cancer and leukemia. By identifying relevant subsets of the data and focusing on them we were able to discover partitions and correla", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.210134797", "local_pdf": "", "api": ""}, {"title": "Fuzzy Cluster Analysis", "doi": "https://doi.org/10.1253/jcj.62.750", "year": 1998, "authors": ["Robert Peters", "Stanley A. Shanies", "John C. Peters"], "source": "Japanese Circulation Journal-english Edition", "cited": 817, "abstract": "Several studies have shown that combining the change in the ST-segment with another exercise variable improves the predictive value of stress testing. However, no method has been able to combine many stress test variables with the ST-segment change simultaneously and help the clinician better predict future cardiac events. Fuzzy Cluster Analysis (FCA) was used to combine 5 stress test variables with ST-segment deviation to classify each of 232 positive outpatient stress tests as mildly, moderately, or severely abnormal. Cardiac events were recorded in these 3 patient groups up to 96 months (mean 65 months) after the stress tests. Coronary angiography was performed on 159 of these patients within 1 month of their stress tests. FCA better separated the 3 event-free survival curves than class", "oa": true, "pdf_url": "https://www.jstage.jst.go.jp/article/jcj/62/10/62_10_750/_pdf", "local_pdf": "", "api": ""}, {"title": "Filter bank canonical correlation analysis for implementing a high-speed SSVEP-based brain–computer interface", "doi": "https://doi.org/10.1088/1741-2560/12/4/046008", "year": 2015, "authors": ["Xiaogang Chen", "Yijun Wang", "Shangkai Gao", "Tzyy‐Ping Jung", "Xiaorong Gao"], "source": "Journal of Neural Engineering", "cited": 806, "abstract": "OBJECTIVE: Recently, canonical correlation analysis (CCA) has been widely used in steady-state visual evoked potential (SSVEP)-based brain-computer interfaces (BCIs) due to its high efficiency, robustness, and simple implementation. However, a method with which to make use of harmonic SSVEP components to enhance the CCA-based frequency detection has not been well established. APPROACH: This study proposed a filter bank canonical correlation analysis (FBCCA) method to incorporate fundamental and harmonic frequency components to improve the detection of SSVEPs. A 40-target BCI speller based on frequency coding (frequency range: 8-15.8 Hz, frequency interval: 0.2 Hz) was used for performance evaluation. To optimize the filter bank design, three methods (M1: sub-bands with equally spaced bandw", "oa": true, "pdf_url": "https://iopscience.iop.org/article/10.1088/1741-2560/12/4/046008/pdf", "local_pdf": "", "api": ""}, {"title": "An ensemble prediction of flood susceptibility using multivariate discriminant analysis, classification and regression trees, and support vector machines", "doi": "https://doi.org/10.1016/j.scitotenv.2018.10.064", "year": 2018, "authors": ["Bahram Choubin", "Ehsan Moradi", "Mohammad Golshan", "Jan Adamowski", "Farzaneh Sajedi Hosseini", "Amir Mosavi"], "source": "The Science of The Total Environment", "cited": 796, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.scitotenv.2018.10.064", "local_pdf": "", "api": ""}, {"title": "Conducting and Interpreting Canonical Correlation Analysis in Personality Research: A User-Friendly Primer", "doi": "https://doi.org/10.1207/s15327752jpa8401_09", "year": 2005, "authors": ["Alissa Sherry", "Robin K. Henson"], "source": "Journal of Personality Assessment", "cited": 776, "abstract": "The purpose of this article is to reduce potential statistical barriers and open doors to canonical correlation analysis (CCA) for applied behavioral scientists and personality researchers. CCA was selected for discussion, as it represents the highest level of the general linear model (GLM) and can be rather easily conceptualized as a method closely linked with the more widely understood Pearson r correlation coefficient. An understanding of CCA can lead to a more global appreciation of other univariate and multivariate methods in the GLM. We attempt to demonstrate CCA with basic language, using technical terminology only when necessary for understanding and use of the method. We present an entire example of a CCA analysis using SPSS (Version 11.0) with personality data.", "oa": true, "pdf_url": "https://www.tandfonline.com/doi/pdf/10.1207/s15327752jpa8401_09?needAccess=true", "local_pdf": "", "api": ""}, {"title": "An online multi-channel SSVEP-based brain–computer interface using a canonical correlation analysis method", "doi": "https://doi.org/10.1088/1741-2560/6/4/046002", "year": 2009, "authors": ["Guangyu Bin", "Xiaorong Gao", "Yan Zheng", "Bo Hong", "Shangkai Gao"], "source": "Journal of Neural Engineering", "cited": 775, "abstract": "In recent years, there has been increasing interest in using steady-state visual evoked potential (SSVEP) in brain-computer interface (BCI) systems. However, several aspects of current SSVEP-based BCI systems need improvement, specifically in relation to speed, user variation and ease of use. With these improvements in mind, this paper presents an online multi-channel SSVEP-based BCI system using a canonical correlation analysis (CCA) method for extraction of frequency information associated with the SSVEP. The key parameters, channel location, window length and the number of harmonics, are investigated using offline data, and the result used to guide the design of the online system. An SSVEP-based BCI system with six targets, which use nine channel locations in the occipital and parietal ", "oa": true, "pdf_url": "https://iopscience.iop.org/article/10.1088/1741-2560/6/4/046002/pdf", "local_pdf": "", "api": ""}, {"title": "Gaussian-Process Factor Analysis for Low-Dimensional Single-Trial Analysis of Neural Population Activity", "doi": "https://doi.org/10.1152/jn.90941.2008", "year": 2009, "authors": ["Byron M. Yu", "John P. Cunningham", "Gopal Santhanam", "Stephen I. Ryu", "Krishna V. Shenoy", "Maneesh Sahani"], "source": "Journal of Neurophysiology", "cited": 744, "abstract": "We consider the problem of extracting smooth, low-dimensional neural trajectories that summarize the activity recorded simultaneously from many neurons on individual experimental trials. Beyond the benefit of visualizing the high-dimensional, noisy spiking activity in a compact form, such trajectories can offer insight into the dynamics of the neural circuitry underlying the recorded activity. Current methods for extracting neural trajectories involve a two-stage process: the spike trains are first smoothed over time, then a static dimensionality-reduction technique is applied. We first describe extensions of the two-stage methods that allow the degree of smoothing to be chosen in a principled way and that account for spiking variability, which may vary both across neurons and across time.", "oa": true, "pdf_url": "https://doi.org/10.1152/jn.90941.2008", "local_pdf": "", "api": ""}, {"title": "Three Systems of Insular Functional Connectivity Identified with Cluster Analysis", "doi": "https://doi.org/10.1093/cercor/bhq186", "year": 2010, "authors": ["Ben Deen", "Naomi B. Pitskel", "Kevin A. Pelphrey"], "source": "Cerebral Cortex", "cited": 740, "abstract": "Despite much research on the function of the insular cortex, few studies have investigated functional subdivisions of the insula in humans. The present study used resting-state functional connectivity magnetic resonance imaging (MRI) to parcellate the human insular lobe based on clustering of functional connectivity patterns. Connectivity maps were computed for each voxel in the insula based on resting-state functional MRI (fMRI) data and segregated using cluster analysis. We identified 3 insular subregions with distinct patterns of connectivity: a posterior region, functionally connected with primary and secondary somatomotor cortices; a dorsal anterior to middle region, connected with dorsal anterior cingulate cortex, along with other regions of a previously described control network; an", "oa": true, "pdf_url": "https://academic.oup.com/cercor/article-pdf/21/7/1498/22787671/bhq186.pdf", "local_pdf": "", "api": ""}, {"title": "Principal Component Analysis of Three-Mode Data by Means of Alternating Least Squares Algorithms", "doi": "https://doi.org/10.1007/bf02293599", "year": 1980, "authors": ["Pieter M. Kroonenberg", "Jan de Leeuw"], "source": "Psychometrika", "cited": 728, "abstract": "A new method to estimate the parameters of Tucker’s three-mode principal component model is discussed, and the convergence properties of the alternating least squares algorithm to solve the estimation problem are considered. A special case of the general Tucker model, in which the principal component analysis is only performed over two of the three modes is briefly outlined as well. The Miller & Nicely data on the confusion of English consonants are used to illustrate the programs TUCKALS3 and TUCKALS2 which incorporate the algorithms for the two models described.", "oa": true, "pdf_url": "https://doi.org/10.1007/bf02293599", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "Demixed principal component analysis of neural population data", "doi": "https://doi.org/10.7554/elife.10989", "year": 2016, "authors": ["Dmitry Kobak", "Wieland Brendel", "Christos Constantinidis", "Claudia E. Feierstein", "Ádám Kepecs", "Zachary F. Mainen"], "source": "eLife", "cited": 712, "abstract": "Neurons in higher cortical areas, such as the prefrontal cortex, are often tuned to a variety of sensory and motor variables, and are therefore said to display mixed selectivity. This complexity of single neuron responses can obscure what information these areas represent and how it is represented. Here we demonstrate the advantages of a new dimensionality reduction technique, demixed principal component analysis (dPCA), that decomposes population activity into a few components. In addition to systematically capturing the majority of the variance of the data, dPCA also exposes the dependence of the neural representation on task parameters such as stimuli, decisions, or rewards. To illustrate our method we reanalyze population data from four datasets comprising different species, different ", "oa": true, "pdf_url": "https://doi.org/10.7554/elife.10989", "local_pdf": "", "api": ""}, {"title": "Sparse principal component analysis via regularized low rank matrix approximation", "doi": "https://doi.org/10.1016/j.jmva.2007.06.007", "year": 2007, "authors": ["Haipeng Shen", "Jianhua Z. Huang"], "source": "Journal of Multivariate Analysis", "cited": 699, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0047259X07000887/pdf", "local_pdf": "", "api": ""}, {"title": "THE THEORETICAL FOUNDATIONS OF PRINCIPAL FACTOR ANALYSIS, CANONICAL FACTOR ANALYSIS, AND ALPHA FACTOR ANALYSIS", "doi": "10.1111/j.2044-8317.1970.tb00432.x", "year": 1970, "authors": ["Roderick P. McDonald"], "source": "British Journal of Mathematical and Statistical Psychology", "cited": 661, "abstract": " It is shown that PFA, CFA and AFA are particular cases of a scale‐invariant factoring procedure based on variance ratios of certain weighted combinations of variables. Standard derivations in the literature are shown, in contrast, to have unsatisfactory features. It is suggested that the choice between PFA, CFA and AFA involves relatively independent choices of features of each, and that in most cases CFA is to be preferred. ", "oa": false, "pdf_url": "", "local_pdf": "", "api": "crossref"}, {"title": "A Genealogical Interpretation of Principal Components Analysis", "doi": "https://doi.org/10.1371/journal.pgen.1000686", "year": 2009, "authors": ["Gil McVean"], "source": "PLoS Genetics", "cited": 653, "abstract": "Principal components analysis, PCA, is a statistical method commonly used in population genetics to identify structure in the distribution of genetic variation across geographical location and ethnic background. However, while the method is often used to inform about historical demographic processes, little is known about the relationship between fundamental demographic parameters and the projection of samples onto the primary axes. Here I show that for SNP data the projection of samples onto the principal components can be obtained directly from considering the average coalescent times between pairs of haploid genomes. The result provides a framework for interpreting PCA projections in terms of underlying processes, including migration, geographical isolation, and admixture. I also demons", "oa": true, "pdf_url": "https://doi.org/10.1371/journal.pgen.1000686", "local_pdf": "", "api": ""}, {"title": "Obstacles to the growth of new SMEs in South Africa: A principal component analysis approach", "doi": "https://doi.org/10.5897/ajbm.9000434", "year": 2010, "authors": ["Fatoki Olawale", "David Kudzaishe Garwe"], "source": "AFRICAN JOURNAL OF BUSINESS MANAGEMENT", "cited": 636, "abstract": "The paper investigated the obstacles to the growth of new SMEs in South Africa using the principal component approach. New SMEs are seen as a significant component of the solution to South Africa’s development issues. However, most new SMEs do not grow; their failure rate in South Africa (75%) is one of the highest in the world. The objective of the study was to investigate the internal and external environmental obstacles to the growth of new SMEs. As a new business develops, it exists and survives in an environment characterized by both internal and external factors which impact negatively on the new business’ survival. Thirty variables were identified as obstacles. The principal component analysis with varimax rotation was used to reduce the variables to five clusters. The most importan", "oa": true, "pdf_url": "https://www.academicjournals.org/article/article1380715803_Olawale and Garwe.pdf", "local_pdf": "", "api": ""}, {"title": "On a Heuristic Method of Test Construction and its use in Multivariate Analysis", "doi": "https://doi.org/10.1214/aoms/1177729029", "year": 1953, "authors": ["Sasanka Roy"], "source": "The Annals of Mathematical Statistics", "cited": 629, "abstract": "In this paper two closely related heuristic principles of test construction (to be explained in Section 3), called Type I and Type II methods, of which Type II is identified with the usual likelihood ratio method, are noticed as underlying most of the classical tests of hypotheses, simple or composite, on means of univariate normal populations, and on total or partial correlations or regressions in the case of multinormal variates. In these situations the two methods are found to lead to identical tests having properties which happen to be very good in certain cases and moderately good in others. For certain types of composite hypotheses an extension is then made of the Type I method which is applied to construct tests of three different classes of hypotheses on multinormal populations (so", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-24/issue-2/On-a-Heuristic-Method-of-Test-Construction-and-its-use/10.1214/aoms/1177729029.pdf", "local_pdf": "", "api": ""}, {"title": "Face recognition using kernel direct discriminant analysis algorithms", "doi": "https://doi.org/10.1109/tnn.2002.806629", "year": 2003, "authors": ["Juwei Lu", "Konstantinos N. Plataniotis", "A.N. Venetsanopoulos"], "source": "IEEE Transactions on Neural Networks", "cited": 608, "abstract": "Techniques that can introduce low-dimensional feature representation with enhanced discriminatory power is of paramount importance in face recognition (FR) systems. It is well known that the distribution of face images, under a perceivable variation in viewpoint, illumination or facial expression, is highly nonlinear and complex. It is, therefore, not surprising that linear techniques, such as those based on principle component analysis (PCA) or linear discriminant analysis (LDA), cannot provide reliable and robust solutions to those FR problems with complex face variations. In this paper, we propose a kernel machine-based discriminant analysis method, which deals with the nonlinearity of the face patterns' distribution. The proposed method also effectively solves the so-called \"small samp", "oa": true, "pdf_url": "https://doi.org/10.1109/tnn.2002.806629", "local_pdf": "", "api": ""}, {"title": "ks : Kernel Density Estimation and Kernel Discriminant Analysis for Multivariate Data in R", "doi": "https://doi.org/10.18637/jss.v021.i07", "year": 2007, "authors": ["Tarn Duong"], "source": "Journal of Statistical Software", "cited": 603, "abstract": "Kernel smoothing is one of the most widely used non-parametric data smoothing techniques. We introduce a new R package ks for multivariate kernel smoothing. Currently it contains functionality for kernel density estimation and kernel discriminant analysis. It is a comprehensive package for bandwidth matrix selection, implementing a wide range of data-driven diagonal and unconstrained bandwidth selectors.", "oa": true, "pdf_url": "https://doi.org/10.18637/jss.v021.i07", "local_pdf": "", "api": ""}, {"title": "Assessing the Quality and Appropriateness of Factor Solutions and Factor Score Estimates in Exploratory Item Factor Analysis", "doi": "https://doi.org/10.1177/0013164417719308", "year": 2017, "authors": ["Pere J. Ferrando", "Urbano Lorenzo‐Seva"], "source": "Educational and Psychological Measurement", "cited": 591, "abstract": "This article proposes a comprehensive approach for assessing the quality and appropriateness of exploratory factor analysis solutions intended for item calibration and individual scoring. Three groups of properties are assessed: (a) strength and replicability of the factorial solution, (b) determinacy and accuracy of the individual score estimates, and (c) closeness to unidimensionality in the case of multidimensional solutions. Within each group, indices are considered for two types of factor-analytic models: the linear model for continuous responses and the categorical-variable-methodology model that treats the item scores as ordered-categorical. All the indices proposed have been implemented in a noncommercial and widely known program for exploratory factor analysis. The usefulness of t", "oa": true, "pdf_url": "https://doi.org/10.1177/0013164417719308", "local_pdf": "001_A new criterion for assessing discrimina.pdf", "api": ""}, {"title": "A Principal Component Analysis of 39 Scientific Impact Measures", "doi": "https://doi.org/10.1371/journal.pone.0006022", "year": 2009, "authors": ["Johan Bollen", "Herbert Van de Sompel", "Aric Hagberg", "Ryan Chute"], "source": "PLoS ONE", "cited": 585, "abstract": "BACKGROUND: The impact of scientific publications has traditionally been expressed in terms of citation counts. However, scientific activity has moved online over the past decade. To better capture scientific impact in the digital era, a variety of new impact measures has been proposed on the basis of social network analysis and usage log data. Here we investigate how these new measures relate to each other, and how accurately and completely they express scientific impact. METHODOLOGY: We performed a principal component analysis of the rankings produced by 39 existing and proposed measures of scholarly impact that were calculated on the basis of both citation and usage log data. CONCLUSIONS: Our results indicate that the notion of scientific impact is a multi-dimensional construct that can", "oa": true, "pdf_url": "https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0006022&type=printable", "local_pdf": "", "api": ""}, {"title": "Extensions of Sparse Canonical Correlation Analysis with Applications to Genomic Data", "doi": "https://doi.org/10.2202/1544-6115.1470", "year": 2009, "authors": ["Daniela Witten", "Robert Tibshirani"], "source": "Statistical Applications in Genetics and Molecular Biology", "cited": 582, "abstract": "In recent work, several authors have introduced methods for sparse canonical correlation analysis (sparse CCA). Suppose that two sets of measurements are available on the same set of observations. Sparse CCA is a method for identifying sparse linear combinations of the two sets of variables that are highly correlated with each other. It has been shown to be useful in the analysis of high-dimensional genomic data, when two sets of assays are available on the same set of samples. In this paper, we propose two extensions to the sparse CCA methodology. (1) Sparse CCA is an unsupervised method; that is, it does not make use of outcome measurements that may be available for each observation (e.g., survival time or cancer subtype). We propose an extension to sparse CCA, which we call sparse super", "oa": true, "pdf_url": "https://doi.org/10.2202/1544-6115.1470", "local_pdf": "", "api": ""}, {"title": "Statistical power for cluster analysis", "doi": "https://doi.org/10.1186/s12859-022-04675-1", "year": 2022, "authors": ["Edwin S. Dalmaijer", "Camilla L. Nord", "Duncan E. Astle"], "source": "BMC Bioinformatics", "cited": 573, "abstract": "BACKGROUND: Cluster algorithms are gaining in popularity in biomedical research due to their compelling ability to identify discrete subgroups in data, and their increasing accessibility in mainstream software. While guidelines exist for algorithm selection and outcome evaluation, there are no firmly established ways of computing a priori statistical power for cluster analysis. Here, we estimated power and classification accuracy for common analysis pipelines through simulation. We systematically varied subgroup size, number, separation (effect size), and covariance structure. We then subjected generated datasets to dimensionality reduction approaches (none, multi-dimensional scaling, or uniform manifold approximation and projection) and cluster algorithms (k-means, agglomerative hierarchi", "oa": true, "pdf_url": "https://bmcbioinformatics.biomedcentral.com/counter/pdf/10.1186/s12859-022-04675-1", "local_pdf": "", "api": ""}, {"title": "Hierarchical Cluster Analysis: Comparison of Three Linkage Measures and Application to Psychological Data", "doi": "https://doi.org/10.20982/tqmp.11.1.p008", "year": 2015, "authors": ["Odilia Yim", "Kylee T. Ramdeen"], "source": "The Quantitative Methods for Psychology", "cited": 556, "abstract": "Cluster analysis refers to a class of data reduction methods used for sorting cases, observations, or variables of a given dataset into homogeneous groups that differ from each other.The present paper focuses on hierarchical agglomerative cluster analysis, a statistical technique where groups are sequentially created by systematically merging similar clusters together, as dictated by the distance and linkage measures chosen by the researcher.Specific distance and linkage measures are reviewed, including a discussion of how these choices can influence the clustering process by comparing three common linkage measures (single linkage, complete linkage, average linkage).The tutorial guides researchers in performing a hierarchical cluster analysis using the SPSS statistical software.Through an ", "oa": true, "pdf_url": "https://www.tqmp.org/RegularArticles/vol11-1/p008/p008.pdf", "local_pdf": "", "api": ""}, {"title": "An Overview of Principal Component Analysis", "doi": "https://doi.org/10.4236/jsip.2013.43b031", "year": 2013, "authors": ["Sasan Karamizadeh", "Shahidan M. Abdullah", "Azizah Abdul Manaf", "Mazdak Zamani", "Ali Reza Hooman"], "source": "Journal of Signal and Information Processing", "cited": 540, "abstract": "The principal component analysis (PCA) is a kind of algorithms in biometrics. It is a statistics technical and used orthogonal transformation to convert a set of observations of possibly correlated variables into a set of values of linearly uncorrelated variables. PCA also is a tool to reduce multidimensional data to lower dimensions while retaining most of the information. It covers standard deviation, covariance, and eigenvectors. This background knowledge is meant to make the PCA section very straightforward, but can be skipped if the concepts are already familiar.", "oa": true, "pdf_url": "http://www.scirp.org/journal/PaperDownload.aspx?paperID=38103", "local_pdf": "", "api": ""}, {"title": "Full-Information Item Factor Analysis", "doi": "https://doi.org/10.1177/014662168801200305", "year": 1988, "authors": ["R. Darrell Bock", "Robert D. Gibbons", "Eiji Muraki"], "source": "Applied Psychological Measurement", "cited": 535, "abstract": "A method of item factor analysis based on Thur stone's multiple-factor model and implemented by marginal maximum likelihood estimation and the EM algorithm is described. Statistical significance of suc cessive factors added to the model is tested by the likelihood ratio criterion. Provisions for effects of guessing on multiple-choice items, and for omitted and not-reached items, are included. Bayes constraints on the factor loadings are found to be necessary to suppress Heywood cases. Numerous applications to simulated and real data are presented to substantiate the accuracy and practical utility of the method. Index terms: Armed Services Vocational Aptitude Bat tery, Beta prior, EM algorithm, Item factor analysis, TESTFACT, Tetrachoric correlation.", "oa": true, "pdf_url": "https://journals.sagepub.com/doi/pdf/10.1177/014662168801200305?download=true", "local_pdf": "", "api": ""}, {"title": "Robust Perron cluster analysis in conformation dynamics", "doi": "https://doi.org/10.1016/j.laa.2004.10.026", "year": 2004, "authors": ["Peter Deuflhard", "Marcus Weber"], "source": "Linear Algebra and its Applications", "cited": 533, "abstract": "The key to molecular conformation dynamics is the direct identification of metastable conformations, which are almost invariant sets of molecular dynamical systems. Once some reversible Markov operator has been discretized, a generalized symmetric stochastic matrix arises. This matrix can be treated by Perron cluster analysis, a rather recent method involving a Perron cluster eigenproblem. The paper presents an improved Perron cluster analysis algorithm, which is more robust than earlier suggestions. Numerical examples are included.", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0024379504004689/pdf", "local_pdf": "", "api": ""}, {"title": "Face recognition using kernel principal component analysis", "doi": "https://doi.org/10.1109/97.991133", "year": 2002, "authors": ["Kwang In Kim", "Keechul Jung", "Hang Joon Kim"], "source": "IEEE Signal Processing Letters", "cited": 517, "abstract": "A kernel principal component analysis (PCA) was previously proposed as a nonlinear extension of a PCA. The basic idea is to first map the input space into a feature space via nonlinear mapping and then compute the principal components in that feature space. This article adopts the kernel PCA as a mechanism for extracting facial features. Through adopting a polynomial kernel, the principal components can be computed within the space spanned by high-order correlations of input pixels making up a facial image, thereby producing a good performance.", "oa": true, "pdf_url": "https://doi.org/10.1109/97.991133", "local_pdf": "", "api": ""}, {"title": "Principal Component Analysis for Protein Folding Dynamics", "doi": "https://doi.org/10.1016/j.jmb.2008.10.018", "year": 2008, "authors": ["Gia G. Maisuradze", "Adam Liwo", "Harold A. Scheraga"], "source": "Journal of Molecular Biology", "cited": 503, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jmb.2008.10.018", "local_pdf": "015_Discriminant analysis of principal compo.pdf", "api": ""}, {"title": "Exploratory factor analysis in validation studies: Uses and recommendations", "doi": "https://doi.org/10.7334/psicothema2013.349", "year": 2014, "authors": ["Isabel Izquierdo", "Julio Olea", "Francisco J. Abad"], "source": "Psicothema", "cited": 493, "abstract": "BACKGROUND: The Exploratory Factor Analysis (EFA) procedure is one of the most commonly used in social and behavioral sciences. However, it is also one of the most criticized due to the poor management researchers usually display. The main goal is to examine the relationship between practices usually considered more appropriate and actual decisions made by researchers. METHOD: The use of exploratory factor analysis is examined in 117 papers published between 2011 and 2012 in 3 Spanish psychological journals with the highest impact within the previous five years. RESULTS: RESULTS show significant rates of questionable decisions in conducting EFA, based on unjustified or mistaken decisions regarding the method of extraction, retention, and rotation of factors. CONCLUSIONS: Overall, the curre", "oa": true, "pdf_url": "https://doi.org/10.7334/psicothema2013.349", "local_pdf": "", "api": ""}, {"title": "Technique of Factor Analysis", "doi": "https://doi.org/10.1038/136297b0", "year": 1935, "authors": ["William Stephenson"], "source": "Nature", "cited": 490, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/136297b0.pdf", "local_pdf": "", "api": ""}, {"title": "Applied multivariate analysis", "doi": null, "year": 1972, "authors": ["James S. Press"], "source": "Infoscience (Ecole Polytechnique Fédérale de Lausanne)", "cited": 487, "abstract": "", "oa": true, "pdf_url": "http://infoscience.epfl.ch/record/2791", "local_pdf": "", "api": ""}, {"title": "A principal component analysis of facial expressions", "doi": "https://doi.org/10.1016/s0042-6989(01)00002-5", "year": 2001, "authors": ["Andrew J. Calder", "A. Mike Burton", "Paul Miller", "Andrew W. Young", "Shigeru Akamatsu"], "source": "Vision Research", "cited": 479, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0042698901000025/pdf", "local_pdf": "", "api": ""}, {"title": "Cluster analysis of gene expression dynamics", "doi": "https://doi.org/10.1073/pnas.132656399", "year": 2002, "authors": ["Marco Ramoni", "Paola Sebastiani", "Isaac S. Kohane"], "source": "Proceedings of the National Academy of Sciences", "cited": 474, "abstract": "This article presents a Bayesian method for model-based clustering of gene expression dynamics. The method represents gene-expression dynamics as autoregressive equations and uses an agglomerative procedure to search for the most probable set of clusters given the available data. The main contributions of this approach are the ability to take into account the dynamic nature of gene expression time series during clustering and a principled way to identify the number of distinct clusters. As the number of possible clustering models grows exponentially with the number of observed time series, we have devised a distance-based heuristic search procedure able to render the search process feasible. In this way, the method retains the important visualization capability of traditional distance-base", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.132656399", "local_pdf": "", "api": ""}]}}}